// English content. Full stories: Sonya through Viktor + Ruslan (id 0-12). Rest of menu is translated, stories pending.
(function () {
  const CHARACTERS = [
    { id: 0, key: 'sonya',  name: 'Sonya',  gender: 'ж', theme: 'survived a late-term abortion, disability, adoption', softTheme: "a path from rejection to family", color: '#ea8853',
      closingVerse: 'Though my father and mother forsake me, the LORD will receive me. (Psalm 27:10)',
      closingPrayer: 'Lord, You saw me before anyone chose to accept or reject me. Thank You for being the Father who never leaves. Help me see myself as valuable as You see me.' },
    { id: 1, key: 'nastya', name: 'Claire', gender: 'ж', theme: "survived a genocide/massacre, forgave her family's killers", softTheme: "forgiveness after loss", color: '#c2555f',
      closingVerse: 'Be kind to one another, tenderhearted, forgiving one another, as God in Christ forgave you. (Eph. 4:32)',
      closingPrayer: 'Lord, You know what this forgiveness cost — You paid for it Yourself on the cross. Give me strength to forgive the way You forgave me: not because the pain does not count, but because You are stronger than it.' },
    { id: 2, key: 'liza',   name: 'Rachel',   gender: 'ж', theme: 'abused by someone she trusted; justice and forgiveness', softTheme: "a path through abuse", color: '#397ec6',
      closingVerse: 'The LORD is near to the brokenhearted and saves the crushed in spirit. (Psalm 34:18)',
      closingPrayer: 'Lord, You are close to those whose hearts have been broken by betrayal. Forgiveness does not mean it did not hurt, and it does not mean going back to where it is not safe. Let me walk the road to healing in Your time, one step at a time.' },
    { id: 3, key: 'timur',  name: 'Marcus',  gender: 'м', theme: 'gang leader turned preacher', softTheme: "from gang to faith", color: '#e46128',
      closingVerse: 'Therefore, if anyone is in Christ, he is a new creation. The old has passed away; behold, the new has come. (2 Cor. 5:17)',
      closingPrayer: 'Lord, You do not take away my past to erase it, but so it no longer decides who I am. Thank You for letting me start over. Help me be faithful to who You are calling me to become.' },
    { id: 4, key: 'sergey', name: 'Michael', gender: 'м', theme: 'captivity and torture, PTSD and alcoholism, forgave his torturer', softTheme: "captivity, and a path to forgiveness", color: '#9ac639',
      closingVerse: 'The Spirit of the Lord GOD is upon me... he has sent me to heal the brokenhearted, to proclaim liberty to the captives. (Isaiah 61:1)',
      closingPrayer: 'Lord, You come to the captive and the brokenhearted — that means You come to me too. Free me not only from what was done to me, but from what it still holds inside. Give me peace where the memory still hurts.' },
    { id: 5, key: 'maksim', name: 'Anthony', gender: 'м', theme: 'corruption and prison, converted through a book, ministry to former inmates', softTheme: "prison, and a new path", color: '#7539c6',
      closingVerse: 'For I know the plans I have for you, declares the LORD, plans for welfare and not for evil, to give you a future and a hope. (Jer. 29:11)',
      closingPrayer: 'Lord, even behind bars You had a future for me that I could not see. Thank You for not writing me off. Let my second life become hope for those still behind bars — real bars, or ones they built inside.' },
    { id: 6, key: 'kristina', name: 'Christine', gender: 'ж', theme: 'lecturer and activist, converted through a years-long friendship with a pastor', softTheme: "a path through friendship", color: '#c68039',
      closingVerse: 'Iron sharpens iron, and one man sharpens another. (Prov. 27:17)',
      closingPrayer: 'Lord, thank You for people who did not rush me toward faith but simply stayed. Help me be that kind of friend for someone else — patient, real, not counting the years it takes.' },
    { id: 7, key: 'polina', name: 'Paige', gender: 'ж', theme: 'suicide attempt, disability, became a pro-life advocate', softTheme: "pain turned into a calling", color: '#ea536e',
      closingVerse: 'The God of all comfort, who comforts us in all our affliction, so that we may be able to comfort those who are in any affliction. (2 Cor. 1:3-4)',
      closingPrayer: 'Lord, You did not let my pain go to waste — You let it become something that could comfort someone else. Keep turning my scars into a place where someone else who is hurting can come.' },
    { id: 8, key: 'marina', name: 'Michelle', gender: 'ж', theme: 'kidnapped and enslaved by traffickers, faith as an anchor', softTheme: "a path through slavery", color: '#23dcb7',
      closingVerse: 'He who dwells in the shelter of the Most High will abide in the shadow of the Almighty. I will say to the LORD, my refuge and my fortress, my God, in whom I trust. (Psalm 91:1-2)',
      closingPrayer: 'Lord, in the worst place I was taken to against my will, You were my refuge, even when I had nothing else to hold onto. Thank You for being there where it seemed You could not be. Lead me on to real freedom — not just the outward kind.' },
    { id: 9, key: 'alina', name: 'Amber', gender: 'ж', theme: 'addiction and life on the street, recovery through a shelter', softTheme: "the street, and the way home", color: '#de8d24',
      closingVerse: 'While he was still a long way off, his father saw him and felt compassion, and ran and embraced him and kissed him. (Luke 15:20)',
      closingPrayer: 'Lord, You did not wait for me to clean myself up before accepting me — You ran to meet me while I was still far off. Thank You for the home I have now, and for the door that was always open.' },
    { id: 10, key: 'zara', name: 'Leah', gender: 'ж', theme: 'conversion from a Muslim family, risking her life', softTheme: "faith at great risk", color: '#c639a0',
      closingVerse: 'Whoever finds his life will lose it, and whoever loses his life for my sake will find it. (Matt. 10:39)',
      closingPrayer: 'Lord, You know what it cost me to choose You. Give me courage to stay faithful even when it costs dearly, and comfort for those I lost along the way.' },
    { id: 11, key: 'viktor', name: 'Nathan', gender: 'м', theme: 'atheist journalist, converted through his own investigation', softTheme: "a search for truth", color: '#397fc6',
      closingVerse: 'And you will know the truth, and the truth will set you free. (John 8:32)',
      closingPrayer: 'Lord, I went looking for facts and found You instead. Thank You for standing up to my investigation and not being afraid of my questions. Help me keep searching honestly — in faith too, not only in facts.' },
    { id: 12, key: 'ruslan', name: 'Ethan', gender: 'м', theme: 'from a religious family, converted through a years-long argument with a friend', softTheme: "a long road to faith", color: '#accd32',
      closingVerse: 'Let us not grow weary of doing good, for in due season we will reap, if we do not give up. (Gal. 6:9)',
      closingPrayer: 'Lord, thank You for a friend who did not give up arguing with me all those years. Let me not grow tired of sowing where I cannot yet see a harvest, and let me trust You with the timing I do not get to choose.' },
    { id: 13, key: 'roman', name: 'Derek', gender: 'м', theme: 'drug lord, prison, became a pastor', softTheme: "prison, and a new life", color: '#e3361c',
      closingVerse: 'Christ Jesus came into the world to save sinners, of whom I am the foremost — that in me, as the foremost, Jesus Christ might display his perfect patience. (1 Tim. 1:15-16)',
      closingPrayer: 'Lord, if You could make a pastor out of me, then no story is too dark for anyone. Let my life be proof of that for someone who still thinks they have gone too far.' },
    { id: 14, key: 'anton', name: 'Jake', gender: 'м', theme: 'homeless, heroin addiction', softTheme: "the street, and addiction", color: '#3939c6',
      closingVerse: 'The steadfast love of the LORD never ceases; his mercies never come to an end; they are new every morning; great is your faithfulness. (Lam. 3:22-23)',
      closingPrayer: 'Lord, addiction takes a lot, but not Your faithfulness — it is new every morning, even after a bad day. Give me today, one day at a time, and do not let me forget You are there even at the bottom.' },
    { id: 15, key: 'pavel', name: 'Paul', gender: 'м', theme: 'clinical death and miraculous healing', softTheme: "death, and a miracle", color: '#e9b74a',
      closingVerse: 'I shall not die, but I shall live, and recount the deeds of the LORD. (Psalm 118:17)',
      closingPrayer: 'Lord, You gave me life back for a reason. Thank You for one more day — and another, and another. Help me not to waste this time, but to tell others what You did.' },
    { id: 16, key: 'yulia', name: 'Julia', gender: 'ж', theme: 'grew up in a closed religious group, rebuilt her faith after leaving', softTheme: "faith, rebuilt", color: '#3ac66b',
      closingVerse: 'You will seek me and find me, when you seek me with all your heart. (Jer. 29:13)',
      closingPrayer: 'Lord, I had to take apart the faith I was given and build my own — a real one. Thank You for not disappearing along with what turned out to be false. Help me trust You, not the system that claimed to speak for You.' },
    { id: 17, key: 'oksana', name: 'Erin', gender: 'ж', theme: 'combat PTSD, alcohol, ministry to fellow veterans', softTheme: "war, and a path to healing", color: '#48ca87',
      closingVerse: 'He heals the brokenhearted and binds up their wounds. (Psalm 147:3)',
      closingPrayer: 'Lord, war left things in me that do not show on the outside. Thank You for not being afraid of what I have seen, and for not turning away from my pain. Let my healing become a support for others who went through the same thing beside me.' },
    { id: 18, key: 'vika', name: 'Victoria', gender: 'ж', theme: 'domestic abuse, faith as a path to dignity', softTheme: "abuse, and dignity reclaimed", color: '#de2458',
      closingVerse: 'So God created man in his own image. (Gen. 1:27)',
      closingPrayer: 'Lord, someone tried to convince me I was worth nothing. Thank You for seeing me differently from the start — made in Your image, with a dignity no one can take from me. Help me live knowing that.' },
    { id: 19, key: 'tanya', name: 'Tara', gender: 'ж', theme: 'psychosis linked to bipolar disorder, faith alongside treatment', softTheme: "a mind in crisis, faith close by", color: '#b862d2',
      closingVerse: 'My power is made perfect in weakness. Therefore I will boast all the more gladly of my weaknesses. (2 Cor. 12:9)',
      closingPrayer: 'Lord, You are there on the days my mind fails me, and on the days treatment helps me stand again. Thank You for doctors, for medication, and for Your presence — all together, not one instead of the other. Give me patience with myself on the hard days.' },
    { id: 20, key: 'galya', name: 'Gail', gender: 'ж', theme: 'bankruptcy and poverty, trusting God with finances', softTheme: "poverty, and trust", color: '#c69139',
      closingVerse: 'Look at the birds of the air: they neither sow nor reap... and your heavenly Father feeds them. Are you not of more value than they? (Matt. 6:26)',
      closingPrayer: 'Lord, when everything was lost, I feared You would leave along with everything else. Thank You that You did not. Help me trust You with what I have left — and with what I do not.' },
    { id: 21, key: 'denis', name: 'Dennis', gender: 'м', theme: 'radical nationalist, converted through a Black pastor', softTheme: "a path through hatred", color: '#644f4f',
      closingVerse: 'If anyone says, "I love God," and hates his brother, he is a liar. (1 John 4:20)',
      closingPrayer: 'Lord, forgive me for what filled me before You cleared it out. Thank You for the man I was taught to hate, who showed me You instead. Do not let me go back to where You brought me out of.' },
    { id: 22, key: 'ignat', name: 'Ian', gender: 'м', theme: 'secret pastor in a country where faith is banned, prison', softTheme: "faith outlawed", color: '#d12e79',
      closingVerse: 'We must obey God rather than men. (Acts 5:29)',
      closingPrayer: 'Lord, You know the price I paid to speak of You where it is forbidden. Let me keep being faithful, even in prison, even in silence — You hear, even when no one else does.' },
    { id: 23, key: 'artem', name: 'Arthur', gender: 'м', theme: 'bankruptcy after a business collapse, faith and financial recovery', softTheme: "collapse, and recovery", color: '#39c691',
      closingVerse: 'I will restore to you the years that the swarming locust has eaten. (Joel 2:25)',
      closingPrayer: 'Lord, when everything I had built collapsed, I did not know if there was anything on the other side. Thank You that You do not measure my worth by what I lost. Teach me to build again so my worth rests in You, not in what can be lost again.' },
    { id: 24, key: 'grisha', name: 'Gregory', gender: 'м', theme: 'teenage killing, prison, ministry as a chaplain', softTheme: "prison, and a path of ministry", color: '#c66c39',
      closingVerse: 'Create in me a clean heart, O God, and renew a right spirit within me. (Psalm 51:10)',
      closingPrayer: 'Lord, what I did as a teenager cannot be undone — and I am not asking for that. I am asking for the heart You promised to create new. Let my life behind bars become a service to those who are where I once was.' },
    { id: 25, key: 'stas', name: 'Stanley', gender: 'м', theme: 'divorce, rebuilding fatherhood through faith', softTheme: "divorce, and a path back to family", color: '#395fc6',
      closingVerse: 'Fathers, do not provoke your children to anger, but bring them up in the discipline and instruction of the Lord. (Eph. 6:4)',
      closingPrayer: 'Lord, divorce took a lot from me, but not the right to be a father. Help me rebuild what can be rebuilt, step by step, and be a father who leads with love, not absence.' },
    { id: 26, key: 'zhenya', name: 'Jenny', gender: 'ж', theme: 'eating disorder, healing through faith', softTheme: "body, mind, and healing", color: '#d36973',
      closingVerse: 'I praise you, for I am fearfully and wonderfully made. (Psalm 139:14)',
      closingPrayer: 'Lord, for a long time I was at war with the body You made. Help me see myself the way You do — not a project to fix, but something You called wonderful. Lead me toward healing, step by step, not alone.' },
    { id: 27, key: 'inna', name: 'Ivy', gender: 'ж', theme: 'miscarriages and infertility, trusting God in grief', softTheme: "loss, and trust", color: '#56a5ce',
      closingVerse: 'You have kept count of my tossings; put my tears in your bottle. (Psalm 56:8)',
      closingPrayer: 'Lord, You know how many times I have cried over the children I could not hold on to. Thank You that not one of those tears went unnoticed by You. Help me trust You with what I do not understand.' },
    { id: 28, key: 'karina', name: 'Carrie', gender: 'ж', theme: 'sex industry, leaving through non-judgmental ministry', softTheme: "a path without judgment", color: '#c63a6b',
      closingVerse: 'Neither do I condemn you; go, and from now on sin no more. (John 8:11)',
      closingPrayer: 'Lord, thank You for the people who did not turn away from me but simply stayed, without judgment, while I found my way back. Help me be that kind of safe place for someone else.' },
    { id: 29, key: 'darya', name: 'Dana', gender: 'ж', theme: 'athlete at the peak of fame, who survived childhood sexual abuse and hid it in secret for years', softTheme: "fame, and a hidden emptiness", color: '#7bc639',
      closingVerse: 'For what does it profit a man to gain the whole world and forfeit his soul? (Mark 8:36)',
      closingPrayer: 'Lord, I had everything others dream of, and I was still empty inside. Thank You that You were not satisfied with my achievements — You wanted me. Fill the place that no medal, no applause, could fill.' },
    { id: 30, key: 'milana', name: 'Melanie', gender: 'ж', theme: 'cancer diagnosis, peace despite fear', softTheme: "illness, and peace within", color: '#c75538',
      closingVerse: 'Peace I leave with you; my peace I give to you... Let not your hearts be troubled, neither let them be afraid. (John 14:27)',
      closingPrayer: 'Lord, the diagnosis gave me no guarantees, but Your peace does not depend on guarantees. Thank You that this peace stayed with me even on the most frightening days of waiting. Be near everyone who, like me, is afraid and waiting for results right now.' },
    { id: 31, key: 'egor', name: 'George', gender: 'м', theme: 'athlete at the peak of fame, the emptiness of success', softTheme: "fame, and emptiness", color: '#3982c6',
      closingVerse: 'I considered all my works... and behold, all was vanity and a striving after wind, and there was nothing to be gained under the sun. (Eccl. 2:11)',
      closingPrayer: 'Lord, I achieved everything that was supposed to make me happy, and stood empty at the top. Thank You for showing me that before it was too late. Help me seek what actually fills.' },
    { id: 32, key: 'vadim', name: 'Vincent', gender: 'м', theme: 'death sentence, repentance before execution', softTheme: "a sentence, and repentance", color: '#c63939',
      closingVerse: 'And Jesus said to him, truly, I say to you, today you will be with me in paradise. (Luke 23:43)',
      closingPrayer: 'Lord, You forgave the thief beside You on the cross in his final hours — so there is forgiveness for me too. Thank You for giving me time to repent before my time runs out. Receive me as I have become, not as I was.' },
    { id: 33, key: 'kostya', name: 'Kenneth', gender: 'м', theme: 'blind from birth, music and faith', softTheme: "music against the dark", color: '#8748ca',
      closingVerse: 'One thing I do know: I was blind, and now I see. (John 9:25)',
      closingPrayer: 'Lord, my eyes have never seen light — but I hear and feel You with my whole life, like that blind man in the Gospel who knew You without sight. Thank You for the music through which I can speak of You to those who see but do not notice. Let my darkness be a place where Your light shows through.' },
    { id: 34, key: 'marat', name: 'Martin', gender: 'м', theme: 'organized crime, leaving at the cost of everything', softTheme: "a path out of crime", color: '#3939c6',
      closingVerse: 'He reached down from on high and took hold of me; he drew me out of deep waters. (Psalm 18:16)',
      closingPrayer: 'Lord, getting out cost me almost everything I had. Thank You for pulling me out of a place that seemed to have no way out. Protect me and the people I love on this new road — You know what it cost me.' },
    { id: 35, key: 'yuriy', name: 'Jordan', gender: 'м', theme: 'war refugee, faith amid losing everything', softTheme: "losing everything, and faith", color: '#7dc639',
      closingVerse: 'Though the fig tree should not blossom... yet I will rejoice in the LORD; I will take joy in the God of my salvation. (Hab. 3:17-18)',
      closingPrayer: 'Lord, I lost my home, my land, my whole way of life — but not You. Thank You for walking with me even where I have nothing of my own. Help me put down roots again where You have brought me.' },
    { id: 36, key: 'olya', name: 'Olivia', gender: 'ж', theme: 'paralysis after an injury, faith amid stillness', softTheme: "stillness, and faith", color: '#63d29b',
      closingVerse: 'Be still, and know that I am God. (Psalm 46:10)',
      closingPrayer: 'Lord, a body that used to move without a second thought is now still, and my faith had to learn to stand again. Thank You for not requiring movement from me to be near. Teach me to find You in the stillness I never chose.' },
    { id: 37, key: 'natasha', name: 'Diane', gender: 'ж', theme: 'widowhood, grief and a diary as prayer', softTheme: "widowhood, and memory", color: '#ca4887',
      closingVerse: 'The LORD watches over the sojourners; he upholds the widow and the fatherless. (Psalm 146:9)',
      closingPrayer: 'Lord, You called Yourself the protector of widows long before I became one. Thank You that every page of the diary I wrote to You was heard. Be near on the evenings when the silence in the house is loudest.' },
    { id: 38, key: 'lena', name: 'Megan', gender: 'ж', theme: 'teenage pregnancy, choosing life', softTheme: "youth, and a hard choice", color: '#cdb754',
      closingVerse: 'For you formed my inward parts; you knitted me together in my mother\'s womb. (Psalm 139:13)',
      closingPrayer: 'Lord, I was nowhere near ready for the decision I had to make too young. Thank You for being with me in the worst fear and not turning away from me, a scared kid. Give me wisdom to raise what I chose to protect.' },
    { id: 39, key: 'vera', name: 'Faith', gender: 'ж', theme: 'caring for a mother with dementia, love without recognition', softTheme: "love without recognition", color: '#567dce',
      closingVerse: 'Love bears all things... Love never ends. (1 Cor. 13:7-8)',
      closingPrayer: 'Lord, my mother does not recognize me anymore, but I keep coming. Thank You that my love does not depend on being recognized in return — just like Your love for me does not depend on whether I remember it every day. Give me strength for one more day of care.' },
    { id: 40, key: 'alya', name: 'Alyssa', gender: 'ж', theme: 'famous singer, panic behind the mask of success', softTheme: "success, and a hidden fear", color: '#c7388e',
      closingVerse: 'Do not be anxious about anything, but in everything by prayer and supplication with thanksgiving let your requests be made known to God... and the peace of God will guard your hearts. (Phil. 4:6-7)',
      closingPrayer: 'Lord, no one backstage can see how hard my heart is pounding. Thank You that You do not need me to smile when I am actually afraid. Give me Your peace — the kind that does not depend on applause and does not disappear when the lights go down.' },
    { id: 41, key: 'nina', name: 'Nadine', gender: 'ж', theme: 'chronic invisible illness, prayer without healing', softTheme: "illness without healing", color: '#48a9ca',
      closingVerse: 'So we do not lose heart. Though our outer self is wasting away, our inner self is being renewed day by day. (2 Cor. 4:16)',
      closingPrayer: 'Lord, the healing I have prayed for for years still has not come, and I will not pretend that is easy to accept. Thank You for staying close even when the answer to my prayer is not the one I am hoping for. Renew me within, even when my body is tired.' },
    { id: 42, key: 'lyuda', name: 'Linda', gender: 'ж', theme: "mother of a child with autism, acceptance in full view of others", softTheme: "motherhood in full view", color: '#c6973a',
      closingVerse: 'He will tend his flock like a shepherd; he will gather the lambs in his arms; he will carry them in his bosom. (Isaiah 40:11)',
      closingPrayer: 'Lord, the stares of strangers in the store do not know what it costs my child and me every day. Thank You that You do not judge the way people do, and that You hold us both, the way a caring shepherd carries a lamb. Give me patience in public and in private.' },
    { id: 43, key: 'andrey', name: 'Andrew', gender: 'м', theme: 'secret Christian seminar, labor camps for faith', softTheme: "labor camps, for his faith", color: '#75c639',
      closingVerse: 'Neither height nor depth, nor anything else in all creation, will be able to separate us from the love of God in Christ Jesus our Lord. (Rom. 8:38-39)',
      closingPrayer: 'Lord, they took years of my life for believing in You, but they could not take the faith itself. Thank You that Your love reached me even behind barbed wire. Let my story be a reminder that the cost of faith can be high — and that You are worth it.' },
    { id: 44, key: 'gleb', name: 'Glen', gender: 'м', theme: 'rock musician, fame and addiction', softTheme: "fame, and addiction", color: '#c6397b',
      closingVerse: 'He drew me up from the pit of destruction, out of the miry bog, and set my feet upon a rock... and he put a new song in my mouth. (Psalm 40:2-3)',
      closingPrayer: 'Lord, the stage gave me addiction, not the freedom it promised. Thank You for pulling me out of the pit I dug for myself. Give me a new song — not for applause, but for You.' },
    { id: 45, key: 'oleg', name: 'Oliver', gender: 'м', theme: 'widowhood after thirty years of marriage', softTheme: "widowhood after a long love", color: '#32accd',
      closingVerse: 'Even though I walk through the valley of the shadow of death, I will fear no evil, for you are with me. (Psalm 23:4)',
      closingPrayer: 'Lord, we walked side by side for thirty years, and now I walk alone. Thank You for not leaving me in this valley of shadow. Help me thank You for the years we had, even when it hurts that they ended.' },
    { id: 46, key: 'kirill', name: 'Carl', gender: 'м', theme: 'successful executive, hidden alcoholism', softTheme: "success, and a hidden struggle", color: '#683ac6',
      closingVerse: 'As a deer pants for flowing streams, so pants my soul for you, O God. My soul thirsts for God, for the living God. (Psalm 42:1-2)',
      closingPrayer: 'Lord, from the outside everything looked successful, while inside I was drowning in what I hid even from those closest to me. Thank You for seeing the real me behind the title and the status. Satisfy the thirst I was trying to drown in the wrong things.' },
    { id: 47, key: 'vlad', name: 'Walter', gender: 'м', theme: 'false conviction, prison, exoneration', softTheme: "injustice, and exoneration", color: '#c67539',
      closingVerse: 'Commit your way to the LORD; trust in him, and he will act. He will bring forth your righteousness as the light, and your justice as the noonday. (Psalm 37:5-6)',
      closingPrayer: 'Lord, You knew the truth the whole time people believed the lie about me. Thank You for bringing that truth to light — even if not as fast as I wanted. Help me not carry bitterness for the years that were unjustly taken from me.' },
    { id: 48, key: 'kolya', name: 'Nicholas', gender: 'м', theme: 'materialist scientist, honestly investigating faith', softTheme: "science, and an honest search", color: '#1ca0e3',
      closingVerse: 'The heavens declare the glory of God, and the sky above proclaims his handiwork. (Psalm 19:1)',
      closingPrayer: 'Lord, I searched for You the same way I searched for everything else — honestly, checking, asking questions. Thank You for standing up to the closest scrutiny. Help me not lose that honesty now that I believe.' },
    { id: 49, key: 'bogdan', name: 'Theodore', gender: 'м', theme: 'hostage of an armed group, faith in captivity', softTheme: "faith in captivity", color: '#c66839',
      closingVerse: 'He will call upon me, and I will answer him; I will be with him in trouble; I will rescue him and honor him. (Psalm 91:15)',
      closingPrayer: 'Lord, in captivity I did not know if I would ever see a free day again, but I knew You were there even there. Thank You for being with me in trouble, just as You promised. Help me never forget who held me when I could hold on to nothing myself.' },
  ];

  const STORIES = {
    sonya: {
      start: 'sonya_intro',
      scenes: {
        sonya_intro: { text: "Sonya was never supposed to survive — she was supposed to die. At seven and a half months of pregnancy, doctors injected a saline solution into the womb: it was meant to burn the baby from the inside and out and induce labor of a stillborn within a day. But the doctor on duty that morning hadn't yet started her shift. Sonya was born alive — with burns no living creature should have survived — and took her first breath entirely on her own.", next: 'sonya_childhood' },
        sonya_childhood: { text: "Sonya spent her first months moving between temporary shelters, until a woman named Tamara took her in — not wealthy, but firm in her faith. Tamara was told: at seventeen months, the girl weighed fourteen kilograms of \"dead weight\" and would likely never walk on her own — cerebral palsy, brain damage from lack of oxygen in the hours before birth. \"Nothing will ever come of her,\" they warned Tamara. She simply worked with the girl three times a day, no days off. By three and a half, Sonya took her first steps — with a walker and leg braces, but on her own.", next: 'sonya_choice1' },
        sonya_choice1: { text: "At fourteen, coming into the kitchen for water, Sonya froze in the doorway: the adults were discussing her, not noticing she was standing right there. \"She was supposed to die,\" someone said matter-of-factly, like talking about the weather. That night, lying awake, Sonya put it all together for the first time: the scars no one had ever properly explained, the limp, the three sessions a day with Tamara — none of it had started with an illness or an accident, but with someone else's decision, made for her.", choices: [
          { label: "Accept it as part of God's plan and start talking about it openly", effects: { faith: 10 }, next: 'sonya_bridgeA' },
          { label: "Bury it deep inside and tell no one", effects: { faith: -10 }, next: 'sonya_bridgeB' },
        ] },
        sonya_bridgeA: { text: "Sonya started talking about her birth — first in her church community, where her voice shook so hard everyone could hear it, then at youth gatherings, then in front of halls full of strangers. Every single time, she was genuinely terrified. Every time, afterward, it got a little easier to carry what she used to carry in silence. A few years later, her biological mother found her — lost, aged, struggling for words, as if she'd rehearsed this meeting a hundred times and still forgot where to start.", next: 'sonya_choice2' },
        sonya_bridgeB: { text: "Sonya learned to smile in a way that kept anyone from asking questions — learned to change the subject the moment a conversation touched her childhood or the scar on her leg. She hid that part of herself so carefully she nearly convinced herself it didn't exist. Years later, when her biological mother found her, Sonya felt not relief but a sharp panic — as if someone had dug up a secret she'd kept buried behind her back.", next: 'sonya_choice2' },
        sonya_choice2: { text: "Her mother stands in front of her — shorter than Sonya had imagined, hands trembling slightly — and says quietly, \"Hello. I'm your mother.\" Between them: thirty-some years, and a decision neither of them ever chose to make. She has to decide, right now, standing in the doorway, what to do with those words.", choices: [
          { label: "Forgive and let go, however hard that is", effects: { faith: 15 }, next: 'sonya_endLight' },
          { label: "Turn away and leave, wanting to hear none of it", effects: { faith: -15 }, next: 'sonya_endDark' },
        ] },
        sonya_endLight: { text: "Sonya forgave — not because it was easy, or because her mother had somehow earned it, but because she decided not to carry someone else's guilt as her own for the rest of her life. Today she visits shelters for troubled teens and tells them what no one was there to tell her: that their life is not a mistake, even if someone once decided otherwise. The end of Sonya's story.", next: null, choices: [] },
        sonya_endDark: { text: "Sonya walked away that day without looking back, and never again answered calls from that number. Years later, she still flinches at the word \"mom\" on other people's playgrounds, and keeps everyone who tries to get close at a distance — safe, but completely alone. The end of Sonya's story.", next: null, choices: [] },
      },
    },
    nastya: {
      start: 'nastya_intro',
      scenes: {
        nastya_intro: { text: "Claire grew up in a small town where everything was simply, warmly ordinary: Sunday Mass, loud family dinners, a father who knew every neighbor by name. When killings along ethnic lines swept the country, all of it vanished within a week. A local pastor — the very man who had preached every Sunday in the church of her childhood — hid Claire and seven other women in a cramped space behind a wardrobe in his own house, a closet that once held bedding and now held eight bodies, as long as no one breathed too deeply or moved.", next: 'nastya_scene2' },
        nastya_scene2: { text: "Claire spent ninety-one days in that closet, hearing through the wall the voices of those hunting her and women like her — sometimes right beside her, once literally on the other side of the wardrobe. The women learned not to make a sound even in their sleep. She had gone into hiding a thriving college student weighing over a hundred and ten pounds; three months later she came out weighing barely half that, and instead of counting the days, she repeated to herself the names of relatives she learned, in scraps of news, were being found dead one by one.", next: 'nastya_choice1' },
        nastya_choice1: { text: "Just before the killing began, her father had managed to tell her only one thing: pray the rosary, whatever happens. In the third week in hiding, Claire caught herself unable to say the words of the prayer \"forgive us as we forgive\" — words she had known by heart since childhood. Inside her was nothing but hatred for the people killing outside, and shame for that hatred.", choices: [
          { label: "Keep praying, even feeling nothing", effects: { faith: 10 }, next: 'nastya_bridgeA' },
          { label: "Stop praying and hold on to hatred alone", effects: { faith: -10 }, next: 'nastya_bridgeB' },
        ] },
        nastya_bridgeA: { text: "Claire prayed all fifteen decades of the rosary in a row, sometimes as many as twenty-seven times in a single day until she lost count, and it was in that exhausting repetition, not in any single luminous moment, that the sense slowly returned that God was still there, not just beads in her own hands. Reading a scrap of Gospel that had ended up in the closet by candlelight, she suddenly understood: forgiveness isn't a feeling that arrives on its own, but a decision you have to make again each morning. When the massacre ended and the women finally stepped into the light, Claire had almost no family left — just an empty house and a list of names with no one left to carry them.", next: 'nastya_choice2' },
        nastya_bridgeB: { text: "Hatred kept Claire on her feet when everything else — hunger, fear, despair — should have broken her. When the massacre ended, she had almost no family left, and inside her remained only that cold, hard feeling she mistook for strength.", next: 'nastya_choice2' },
        nastya_choice2: { text: "Two years later, Claire runs into a man at the market whom she's certain killed people in her neighborhood — she recognizes him by the scar above his eyebrow, burned into her memory through a crack in the wardrobe. He recognizes her too, and freezes on the spot with a basket of vegetables in his hands, as if it were an ordinary day at an ordinary market.", choices: [
          { label: "Walk up and tell him she forgives him", effects: { faith: 15 }, next: 'nastya_endLight' },
          { label: "Walk past, wishing he'd pay for it too someday", effects: { faith: -15 }, next: 'nastya_endDark' },
        ] },
        nastya_endLight: { text: "Claire walked up and spoke the words of forgiveness, though her throat tightened on every word and her hands shook so badly she clasped them behind her back. It didn't bring her family back or erase the ninety-one days in the dark, but it took from hatred its power over her own life. She went on to work for several years at United Nations headquarters in New York and wrote a book about those ninety-one days that became an international bestseller. Today she tells this story around the world — not to be pitied, but so someone else might find that same thing in themselves. The end of Claire's story.", next: null, choices: [] },
        nastya_endDark: { text: "Claire walked past without a word, gripping tight in her fist the same hatred she'd carried all those years. She survived in body, but sometimes, waking in the middle of the night, she still hears the voices behind the wardrobe — and knows she never fully left that closet. The rosary someone lent her for those ninety-one days in the dark still lies untouched at the bottom of a drawer, never taken out again in all the years since. The end of Claire's story.", next: null, choices: [] },
      },
    },
    liza: {
      start: 'liza_intro',
      scenes: {
        liza_intro: { text: "From the age of thirteen, Rachel saw a sports doctor the whole family and the whole club trusted — a man with a reputation, awards on his office walls, and a line of parents hoping to enroll their kids with him. Under the guise of medical treatment, he sexually abused her again and again across many sessions, and she stayed silent, certain no one would believe her over him.", next: 'liza_scene2' },
        liza_scene2: { text: "Years later, Rachel had ended her athletic career, gotten married, had children — from the outside, an ordinary, happy life. But at night the same office lighting haunted her dreams, and she noticed she couldn't watch broadcasts of the sport she used to compete in. She told only her husband, in a whisper, years after their wedding — and even then, not everything.", next: 'liza_choice1' },
        liza_choice1: { text: "Sixteen years had passed. Scrolling the news late one night while her husband slept, Rachel came across an article about other girls who had survived the same thing from the same man — almost word for word the same details she had never told anyone in full. She realized: stay silent forever, or be the first to say it out loud, under her own name. By the time the case reached trial, more than a hundred and fifty women would come forward with the same story about the same man.", choices: [
          { label: "Come forward publicly, even if it wrecks her standing with the community", effects: { faith: 10 }, next: 'liza_bridgeA' },
          { label: "Stay silent and go on as if nothing happened", effects: { faith: -10 }, next: 'liza_bridgeB' },
        ] },
        liza_bridgeA: { text: "Rachel filed the first report, under her real name, knowing there would be no turning back once it went public — the legal training she'd once gotten for entirely different reasons unexpectedly came in useful for untangling the case herself. Part of the community turned its back on her, calling it a betrayal of a man they had so respected. But she kept preparing her statement for the trial in the evenings after the children fell asleep, telling herself that justice and forgiveness weren't mutually exclusive — and within weeks of her coming forward, the number of other women who found the courage to speak up after her had already climbed into the dozens.", next: 'liza_choice2' },
        liza_bridgeB: { text: "Rachel went on living as before, smiling at community gatherings while hiding inside a weight that only grew heavier with the years. She would see him on the news collecting another award, and every time felt like she was suffocating in her own living room — and a few years later, other women began speaking up on their own, without her.", next: 'liza_choice2' },
        liza_choice2: { text: "When the case finally reaches trial — thanks to her own report, or to the other women who found the courage to speak in her place — Rachel is called to testify. Though she had been the first to come forward, months earlier, she ends up last on the list of speakers, after more than a hundred and fifty other women who followed her, over seven days of victim testimony, to that same room and that same microphone. The whole room — journalists, former teammates, the defendant himself — watches her, waiting to hear what she'll say.", choices: [
          { label: "Speak of both justice and forgiving him before God", effects: { faith: 15 }, next: 'liza_endLight' },
          { label: "Say only that she wants him to suffer as she suffered", effects: { faith: -15 }, next: 'liza_endDark' },
        ] },
        liza_endLight: { text: "Rachel said words that surprised the whole room: she demanded the full force of the law — and in the same breath, looking him in the eye, said: \"I pray you experience the crushing weight of guilt, so that one day you may know true repentance and true forgiveness from God — you need that far more than forgiveness from me, though I give you that too.\" It didn't ease the pain instantly or return the stolen years, but it took from the past the right to decide who she'd become next. The end of Rachel's story.", next: null, choices: [] },
        liza_endDark: { text: "Rachel got the sentence she'd fought for, but the fury she walked out of that courtroom with never let go of her. Years later she still wakes at night with the same feeling she had on the day of the verdict — victory turned out far lonelier than she'd imagined. The end of Rachel's story.", next: null, choices: [] },
      },
    },
    timur: {
      start: 'timur_intro',
      scenes: {
        timur_intro: { text: "By sixteen, Marcus ran one of the most dangerous gangs in the district — people crossed the street the moment they spotted him coming, and that feeling of power was the only thing that drowned out the memory of the home he'd run from at twelve. His own mother used to call him \"the devil's son\" and hit him with whatever was at hand, and it was those words, even more than the beatings, that finally drove him out onto the street. The only law he recognized was force, and the only family he had was whoever wore the same tattoos.", next: 'timur_scene2' },
        timur_scene2: { text: "Marcus had long since lost count of the fights he'd been in and the people he'd put in the hospital. One of his closest friends in the gang died right in his arms after a knife fight — Marcus remembered his last words for the rest of his life, though he never spoke of that night to anyone. At night, once the gang scattered, all that was left was an empty yard and a silence with no one left to prove himself to — and in that silence, sometimes, real fear crept in, though Marcus would never have admitted it out loud.", next: 'timur_choice1' },
        timur_choice1: { text: "One day an unfamiliar preacher showed up in the neighborhood — no bodyguards, no fear, as if he had no idea where he'd wandered into — and told Marcus straight to his face that he felt as if God had sent him personally to this exact street corner, to this exact gang, and not some other part of the city. He added that God loved Marcus and would not stop loving him no matter what he did. Marcus answered by beating him and holding a knife to his throat, promising to kill him if he ever came back — but instead of struggling, the preacher quietly answered that Marcus could cut him into a thousand pieces, and every piece would still cry out the same thing: \"Jesus loves you\" — and the whole time, he seemed to be silently praying under the blows.", choices: [
          { label: "Go anyway and hear what this preacher has to say", effects: { faith: 10 }, next: 'timur_bridgeA' },
          { label: "Round up the gang and break up his next meeting", effects: { faith: -10 }, next: 'timur_bridgeB' },
        ] },
        timur_bridgeA: { text: "Marcus showed up at the next meeting with half the gang — just to show who ran things, and maybe shut the whole thing down with one word. It was a hot July night, and thousands of people from all over the city packed the hall — far more than Marcus had ever seen in one place. But listening to the sermon among strangers, he suddenly felt not anger but guilt for everything he'd done — for the first time in years. His feet carried him forward, toward the stage, even as his mind screamed at him to turn around.", next: 'timur_choice2' },
        timur_bridgeB: { text: "Marcus and his crew came to break up the meeting, but the crush and shouting inside the packed hall scattered the gang in every direction before he could do anything. That hot summer, thousands of people from all over the area poured into these meetings every night, and it was that flood of strangers that instantly tore Marcus away from his crew. Marcus found himself alone, pressed into a crowd of strangers listening to the very preacher he'd sworn to kill.", next: 'timur_choice2' },
        timur_choice2: { text: "The speaker asks if anyone wants to give their life to God right now, without waiting for tomorrow. Marcus stands there, feeling something far bigger than any street fight he'd ever been part of being decided.", choices: [
          { label: "Step forward and change everything", effects: { faith: 15 }, next: 'timur_endLight' },
          { label: "Turn around and walk back to the street", effects: { faith: -15 }, next: 'timur_endDark' },
        ] },
        timur_endLight: { text: "Marcus stepped forward under the eyes of strangers. That same night, he and another gang leader handed the preacher their knives in exchange for a Bible — a gesture that became, for him, the symbol of an old life ending. He spent the next three years at a Bible college, where he met his future wife, and on returning to his old city he went on to run the country's first rehabilitation center for troubled teens, opened by that same preacher. That night one life ended and another began — no knife in his belt, no gang at his back, but also without the loneliness that had always hidden behind the power. Years later he wrote a book about it, founded his own outreach ministry, and now goes out to street kids just like he once was — in dozens of countries, not just his old neighborhood — telling them what someone once told him. The end of Marcus's story.", next: null, choices: [] },
        timur_endDark: { text: "Marcus turned around and went back to the street, to the same yard and the same silence that scared him more than any gang. He often thought of the last words of the friend who had died in his arms, but he never found the courage to change anything about his own life. A few years later his name turned up in the news again — no longer as a leader's name, just another line in the district crime report, without a word about who he could have become. The end of Marcus's story.", next: null, choices: [] },
      },
    },
    sergey: {
      start: 'sergey_intro',
      scenes: {
        sergey_intro: { text: "Before the war, Michael had competed at major international meets as one of the country's most promising runners — on the final lap he'd pull ahead so hard that people talked about it for years afterward. He met the war not on the ground but in the sky: when his plane went down over the ocean on a combat mission, he and one other crewman were the only survivors. For forty-seven days they drifted on a small raft under a blazing sun, fighting off sharks with their bare hands and eating raw fish and the odd bird that landed nearby, before they were finally picked up — and taken straight into captivity. At the camp, where he was tortured for over two years, one guard the prisoners nicknamed Bird had singled him out as his personal target. Michael came home — his body healed faster than his mind. Waiting for him was a wife who didn't recognize the man who'd come back in place of the one she'd seen off to serve, and nightmares that let go of him not one single night.", next: 'sergey_scene2' },
        sergey_scene2: { text: "By day Michael seemed almost like his old self — joking, going to work, smiling at the neighbors. But the moment the light went out, he was back in the camp: the same guard's voice, the same smell, the same helplessness. He began fearing the dark more than he'd feared it in captivity itself, and admitted it to no one, including himself. Some nights, lying awake, he tried to pray — the way he'd promised on the raft — but the words never got past the first sentence, as if God had stayed behind on that raft too.", next: 'sergey_choice1' },
        sergey_choice1: { text: "Michael started drinking just to get a little sleep without dreams of the camp, and every month the dose he needed grew. One night he woke up with his hands around his own wife's throat — he'd dreamed he was strangling the guard he privately called Bird. In tears, his wife silently packed her things to leave, without a single word of reproach, which was more frightening than any scream.", choices: [
          { label: "Beg her to stay and promise to quit drinking", effects: { faith: 0 }, next: 'sergey_bridgeCommon' },
          { label: "Let her go without a word, thinking he deserves to be alone", effects: { faith: -5 }, next: 'sergey_bridgeCommon' },
        ] },
        sergey_bridgeCommon: { text: "His wife went to a large tent meeting with a visiting preacher anyway, more out of despair than faith — and came home different: calm, almost glowing, as if she'd finally found what she'd been searching for for years. She told him that for the first time in her life she'd truly prayed in her own words, not read off a page — and something inside her had shifted. She asked nothing of Michael, just invited him to come along next time, if he wanted.", choices: [
          { label: "Go with her and listen", effects: { faith: 10 }, next: 'sergey_choice2' },
          { label: "Stay home drinking alone", effects: { faith: -10 }, next: 'sergey_endDark' },
        ] },
        sergey_choice2: { text: "The preacher speaks of war, suffering, and how God asks of a person not strength but faith — simple words that somehow break through what years of therapy never touched. Michael suddenly remembers the vow he made on that very raft in the middle of the ocean, when it seemed he wouldn't live to see morning: 'If you save me, I will serve you for the rest of my life.' A vow he made — and nearly forgot the moment solid ground was under his feet again.", choices: [
          { label: "Pray honestly for the first time in years and forgive his torturer", effects: { faith: 15 }, next: 'sergey_endLight' },
          { label: "Get up and walk out silently, not ready to forgive", effects: { faith: -15 }, next: 'sergey_endDark' },
        ] },
        sergey_endLight: { text: "That same night, for the first time in years, Michael had no nightmares — no guard's voice, no smell, no helplessness. He wrote a letter to the man he'd called Bird — not to excuse him, but to finally free himself of a weight he'd carried longer than the captivity itself had lasted. Years later he flew back to the country where he'd been held and walked into the prison holding the camp's former guards, to tell each one, face to face: I forgive you. His wife stayed, and the nightmares never came back. The end of Michael's story.", next: null, choices: [] },
        sergey_endDark: { text: "The nightmares never let Michael go. In time there was no wife left beside him, no strength left to fight them alone, and the guard's voice grew quieter — simply because Michael had stopped fighting at all. The end of Michael's story.", next: null, choices: [] },
      },
    },
    maksim: {
      start: 'maksim_intro',
      scenes: {
        maksim_intro: { text: "Anthony was the right hand of an influential politician — an adviser who handled the dirtiest business of campaigns and backroom deals without asking unnecessary questions, and once boasted in a small circle that he'd walk over bodies for his patron if it came to that. He took pride in how well he did it. He'd long since stopped asking himself where hardball politics ended and outright criminal conduct began, because that question would have kept him up at night if he ever took it seriously. Journalists later spread that line about walking over bodies everywhere, and though Anthony always insisted his words had been twisted and blown out of proportion, by then the reputation of a man ready to do anything for power had already stuck to his name for good.", next: 'maksim_scene2' },
        maksim_scene2: { text: "At the peak of his career, Anthony had an office two doors down from the country's top officials, the respect of people he'd once feared, and total confidence that the cover-up scheme he was part of would never surface. That confidence collapsed on an ordinary Tuesday, with a single phone call from his own lawyer.", next: 'maksim_choice1' },
        maksim_choice1: { text: "The scheme Anthony was part of unraveled faster than he could put together a defense. Journalists were already printing his name on front pages, the investigation dug deeper by the day, and former partners gave testimony against him one after another to save themselves at the cost of his freedom.", choices: [
          { label: "Admit guilt and take responsibility", effects: { faith: 10 }, next: 'maksim_bridgeA' },
          { label: "Pin it all on subordinates and hold out to the last", effects: { faith: -10 }, next: 'maksim_bridgeB' },
        ] },
        maksim_bridgeA: { text: "Anthony went to the investigator himself and admitted to part of the charges that were, in fact, true — a decision his lawyer called suicidal. It cost him his reputation and part of his sentence for conspiracy, but for the first time in years it lifted a weight he'd carried for months without admitting it even to himself. The little more than seven months he'd spend behind bars felt, in the living of it, far longer than his entire turbulent career before it.", next: 'maksim_choice2' },
        maksim_bridgeB: { text: "Anthony held out to the end, shifting blame onto everyone below him in the chain and hiring ever more expensive lawyers. The sentence caught up with him anyway — only now with the added mark of a man who sold out his own people to save himself, and didn't even save himself.", next: 'maksim_choice2' },
        maksim_choice2: { text: "In prison, in a cell built for four, a package arrives for Anthony from an old friend from his past life — the last person he expected to hear from after the verdict. Inside is a worn book about faith with a short handwritten letter. The first pages seem dull and naive — exactly what he'd expect from a book like that. The friend who'd sent it had only recently turned to faith himself, after years of the same hard-nosed business career, and admitted in the letter that he too used to think books like this were naive. What struck Anthony most was the chapter on pride — it read as if it had been written about him personally.", choices: [
          { label: "Read the book to the end and let himself change", effects: { faith: 15 }, next: 'maksim_endLight' },
          { label: "Toss the book aside and count down the days to release", effects: { faith: -15 }, next: 'maksim_endDark' },
        ] },
        maksim_endLight: { text: "Anthony finished the book in one sleepless night — and by dawn no longer recognized in himself the man he'd been just the day before. When he got out, he didn't go back into power; instead, he founded a prison ministry that grew, over the following decades, into dozens of countries around the world — and it turned out to be far harder, and far more important, than any deal he'd ever made. He later told his own story in a confessional book he called \"Born Again,\" and it was that book that first drew millions of readers' attention to what actually happens behind bars in his country. The end of Anthony's story.", next: null, choices: [] },
        maksim_endDark: { text: "Anthony served his sentence to the day and walked free the same man who'd walked into power years earlier — maybe a little more careful, and considerably more bitter toward his former partners. A couple of years later his name surfaced in the news again, this time in a new case, and the book stayed unread on a shelf in a rented apartment. The end of Anthony's story.", next: null, choices: [] },
      },
    },
    kristina: {
      start: 'kristina_intro',
      scenes: {
        kristina_intro: { text: "Christine taught English literature with tenure and was a respected voice in her city's lesbian community — her public columns had shaped the views of a whole circle of like-minded readers for years. She specialized in queer theory and nineteenth-century literature read through Freud, Marx, and Darwin, and had earned tenure only a couple of years before that letter, right after finishing her doctorate in the same field. She wrote a scathing piece against a Christian men's movement that was gaining popularity — and never expected that among the hundreds of replies, thrilled and outraged alike, would be a letter from a local pastor that would upend everything she believed.", next: 'kristina_scene2' },
        kristina_scene2: { text: "The letter didn't attack or preach — the pastor simply, genuinely asked how exactly she'd arrived at her views, and suggested they talk about it in person sometime. Christine was about to throw it out with the rest of her mail, but something made her sit down and write a reply instead — still sharp, expecting the correspondence to end right there.", next: 'kristina_choice1' },
        kristina_choice1: { text: "His reply was a simple dinner invitation from the pastor and his wife — no argument attached, no attempt whatsoever to change her mind, as if the debate didn't interest him at all. Christine holds the invitation in her hands and has to decide whether to go to dinner with people whose beliefs she'd just publicly mocked in print.", choices: [
          { label: "Go to dinner out of curiosity, strange as it is", effects: { faith: 10 }, next: 'kristina_bridgeA' },
          { label: "Throw out the letter and write a scathing article about it", effects: { faith: -10 }, next: 'kristina_bridgeB' },
        ] },
        kristina_bridgeA: { text: "Christine went to that dinner — and then another, and another, until these evenings became a steady, unforced practice for almost two years. The pastor and his wife never once tried to out-argue her — they simply listened and kept inviting her back, even when Christine deliberately provoked arguments with sharp questions at their own table. Out of pure stubbornness, she started reading the Bible herself, the way a scholar reads a primary source — hunting for contradictions for a future takedown article.", next: 'kristina_choice2' },
        kristina_bridgeB: { text: "Christine skipped the dinner and instead wrote a scathing column about the letter for her readers, which drew plenty of approving replies from people who agreed with her. But one short, undemanding line from the pastor's letter — \"maybe we could just talk sometime\" — kept nagging at her long after the piece ran, and, hidden from her colleagues, she opened a Bible herself for the first time in years. Beyond her newspaper columns, she'd spent years publishing academic work in that same field of queer studies and was a known figure in the city's advocacy community — the last thing she wanted was to risk that reputation over a letter from some random pastor.", next: 'kristina_choice2' },
        kristina_choice2: { text: "Nearly two years into reading — at that shared table on one branch of this story, or alone in the evenings on the other — Christine catches herself mid-lecture, realizing she can no longer honestly defend her old views to her students. Accepting the new ones means losing her tenure, her reputation as an uncompromising fighter, and most of the community she'd called her own for twenty years.", choices: [
          { label: "Accept the faith, even knowing the cost", effects: { faith: 15 }, next: 'kristina_endLight' },
          { label: "Set the Bible aside and go back to her old life", effects: { faith: -15 }, next: 'kristina_endDark' },
        ] },
        kristina_endLight: { text: "Christine accepted the faith — and, just as she'd feared, lost her tenured position and most of the community she'd called her own for twenty years. She herself later called what happened not a graceful spiritual journey but \"a train wreck\" — never finding gentler words for it even years later — after which it finally became possible to build something real from the ground up. She later wrote a book about it, The Secret Thoughts of an Unlikely Convert, holding nothing back, including exactly what the decision cost her. The end of Christine's story.", next: null, choices: [] },
        kristina_endDark: { text: "Christine set the Bible aside without finishing it and went back to her old columns and her old certainty in herself. She still writes the pastor and his wife short letters now and then — she just can't explain, even to herself, why she can't fully let go of this strange friendship that asks nothing of her. The end of Christine's story.", next: null, choices: [] },
      },
    },
    polina: {
      start: 'polina_intro',
      scenes: {
        polina_intro: { text: "At sixteen, Paige attempted suicide — not on impulse, but after months of quiet, methodical despair that no one close to her suspected. Until that night she'd been an ordinary varsity cheerleader with a loving family and plenty of friends, and not one of them had ever suspected what was happening inside her. She survived, but was left in a wheelchair: her body, the one thing that had obeyed her her whole life, didn't obey her this time either, leaving her alive, though paralyzed.", next: 'polina_scene2' },
        polina_scene2: { text: "In her first weeks at the hospital, Paige barely spoke — not to the doctors, not to her parents, who came every day with the same helpless faces. She stared at the ceiling and waited for the pain to pass, both the physical kind and the other kind that had brought her here, but neither one went anywhere. Doctors spoke carefully about years of rehabilitation, making no promises she'd walk again, and Paige had to relearn how to use hands that now obeyed her only some of the time.", next: 'polina_choice1' },
        polina_choice1: { text: "Lying motionless for weeks in the hospital, Paige hears her roommate — an ordinary older woman recovering from surgery — quietly praying aloud every night before sleep, not for show, just out of a lifetime's habit. One day she's invited to join, with no pressure, the way you'd offer someone water.", choices: [
          { label: "Listen, and one day try praying herself", effects: { faith: 10 }, next: 'polina_bridgeA' },
          { label: "Ignore it and grow even angrier at the world", effects: { faith: -10 }, next: 'polina_bridgeB' },
        ] },
        polina_bridgeA: { text: "Paige began praying clumsily, not knowing the right words, just voicing her pain however it came out, and in the evenings she started reading the Bible in bits and pieces, asking anyone willing about God — questions she'd simply never had the time or the desire to ask before. For the first time in a long while, something inside grew a little quieter, though her body never obeyed the way it once had, and the wheelchair stayed part of her life. About a year after that night, deliberately and no longer clumsily, she gave her life to Christ — and says that's when her whole idea of happiness finally changed: not a goal still to be reached, but a peace already available to her now, in a body that never fully recovered.", next: 'polina_choice2' },
        polina_bridgeB: { text: "Paige grew angry at her roommate, at the doctors, at her own body for refusing to die the way she wanted and planned. The anger never left — it only grew, day by day, inside four identical hospital walls, and the question of why no one around her had ever noticed anything stayed unanswered.", next: 'polina_choice2' },
        polina_choice2: { text: "Two years after being discharged, already used to the wheelchair, Paige is invited to speak before a state legislative committee looking into access to crisis support for teenagers — to tell it all exactly as it happened, including what she tried to do to herself and why, in front of people who could change the actual rules for thousands of other sixteen-year-olds.", choices: [
          { label: "Agree, and tell it all exactly as it happened", effects: { faith: 15 }, next: 'polina_endLight' },
          { label: "Refuse — let no one know", effects: { faith: -15 }, next: 'polina_endDark' },
        ] },
        polina_endLight: { text: "Paige rolled up to the podium in her wheelchair and told it all without polish, looking every legislator in the eye in turn. Her words made it into the official record of the hearing, and afterward a girl her own age came up to her, shaking, and said she'd thought about the same thing just last week — and changed her mind after hearing Paige's story. A documentary was later made about her journey, and Paige now helps schools across the country start peer-support programs so teenagers in crisis can get help in time instead of staying silent for years the way she once did. Today Paige speaks across the country to youth groups and lawmakers, working to make sure other teenagers in crisis, like she once was at sixteen, get help in time. The end of Paige's story.", next: null, choices: [] },
        polina_endDark: { text: "Paige refused to testify before the committee and went on living, hiding her scars under her clothes and her story under familiar silence. The hearing went ahead without her account, and the proposed measures were never passed that year. Sometimes she read about peer-support programs opening in other states without a single word about stories like her own, and wondered how many sixteen-year-olds like her she might have helped if she'd only spoken up back then. The end of Paige's story.", next: null, choices: [] },
      },
    },
    marina: {
      start: 'marina_intro',
      scenes: {
        marina_intro: { text: "Michelle was kidnapped at twenty-one and held in trafficking for nearly twenty years — beatings, being sold from hand to hand, several desperate escapes and just as many recaptures across different cities and even different countries her owners moved her through. She held onto one simple thought, repeating it like a prayer: that one day she would see her children again, the ones left at home the night she was taken. A hard, deprived childhood in a poor mountain village had already taught her to endure pain in silence long before the kidnapping — a skill that would bitterly serve her in circumstances far worse than she could have imagined.", next: 'marina_scene2' },
        marina_scene2: { text: "Michelle lost count of the cities, countries, and owners she passed through over those years — the names kept changing, but the fear stayed exactly the same. The one thing that never changed was a photo of her children, which she kept sewn into the lining of the one piece of clothing she had left, unfolding it only in the dead of night, when she was certain no one could see it — or take even this last thing from her. Over those years she was moved between cities on trips lasting more than a full day at a stretch, and in every new place she found others just like her — dozens of women locked in the same nightmare of trafficking.", next: 'marina_choice1' },
        marina_choice1: { text: "After yet another brutal punishment for trying to contact home, Michelle is left alone in the dark of a shed and remembers a prayer her grandmother taught her as a child — simple words that had long felt like they belonged to another, now-impossible life.", choices: [
          { label: "Whisper the prayer, even without believing anyone will hear", effects: { faith: 10 }, next: 'marina_bridgeA' },
          { label: "Decide there is no God, since He allows this", effects: { faith: -10 }, next: 'marina_bridgeB' },
        ] },
        marina_bridgeA: { text: "Michelle began repeating that prayer every night — not because she believed, but because she had nothing else left besides the words and the photo in the lining. Slowly the prayer became the one place where she felt like a person with a name, not merchandise. She would later say it was that faith that kept her from breaking completely — believing that one day she would see her children again, and one day become an ordinary, free woman again.", next: 'marina_choice2' },
        marina_bridgeB: { text: "Michelle stopped praying and held on only to anger and the thought of her children, like the last fuel she had left. The anger gave her strength to keep moving and surviving, but it burned away everything inside her that wasn't pure survival — compassion, tears, the very ability to feel anything besides rage. Month by month that armor grew thicker, and the rare flickers of hope for anything beyond revenge and survival grew shorter and rarer.", next: 'marina_choice2' },
        marina_choice2: { text: "After her release — almost accidental, the result of a raid she only learned about once she'd already been led outside — a social worker, herself a deeply religious woman, offers to take Michelle to church with her. Just to try it; no one is forcing her, and nothing is expected in return. Her freedom actually began with one client who refused to touch her and secretly contacted the police instead — that single act of decency set off the chain of events that, years later, led to the raid and the arrest of several traffickers.", choices: [
          { label: "Go, and let herself trust again", effects: { faith: 15 }, next: 'marina_endLight' },
          { label: "Refuse — trust cost too much last time", effects: { faith: -15 }, next: 'marina_endDark' },
        ] },
        marina_endLight: { text: "Michelle went. The faith that began as a whisper in the dark of a shed became the foundation of her new life in freedom — today she works a hotline for trafficking victims, helping recognize over the phone the same signs of captivity that once went unnoticed in her, travels to schools and police stations to teach people to spot those signs early, and holds her now-grown children in her arms again, children she had almost given up hope of ever seeing. She later testified against traffickers in court even though they tried to have her killed for it, and she did not back down. She also founded a small foundation helping women who survived sexual slavery, and there she often repeats one line: her faith always helped her not fall, even when there seemed to be nowhere left to fall. The end of Michelle's story.", next: null, choices: [] },
        marina_endDark: { text: "Michelle refused and built a new life alone, never fully trusting anyone again, not even her own grown children. She is free in body, but at night she still locks every lock she can find, not just the apartment door. She never told anyone her whole story, not her children, not new acquaintances, preferring to leave the past buried rather than spoken aloud. The end of Michelle's story.", next: null, choices: [] },
      },
    },
    alina: {
      start: 'alina_intro',
      scenes: {
        alina_intro: { text: "Amber grew up in a believing family, with parents who'd spent years serving as missionaries, but by around twelve a quiet resentment toward church and God had already started building up inside her. For years she lived between drugs, alcohol, and the street, selling herself for her next fix — a path that began with one party at sixteen and quietly became the only life she remembered, while that childhood resentment toward faith only grew. She had long since stopped believing any other life was possible for her, and had lost count of the hospitals where indifferent, exhausted doctors had revived her after an overdose.", next: 'alina_scene2' },
        alina_scene2: { text: "On winter nights Amber sometimes thought about how much time she had left — not with horror, but with the tired indifference of someone who'd long since stopped making plans past the next hit. She'd been diagnosed with depression as a teenager, and had grown to feel an almost physical hatred toward her own body and her reflection in the mirror — and it was that pain, not just boredom, that other people's pills, and then everything else, were meant to drown out. The only thing that still recalled another possible life was an old photo of herself in her senior year of school, which she still carried, for some reason, in her jacket pocket — though the girl in the photo now felt like a complete stranger from someone else's life.", next: 'alina_choice1' },
        alina_choice1: { text: "A woman from a street mission approaches Amber, not for the first time, with hot coffee and not a single word of judgment — just talking to her like a person, every week, despite Amber having been rude to her before.", choices: [
          { label: "Agree to come to the mission shelter for even one night", effects: { faith: 10 }, next: 'alina_bridgeA' },
          { label: "Wave her off — she's heard promises that meant nothing before", effects: { faith: -10 }, next: 'alina_bridgeB' },
        ] },
        alina_bridgeA: { text: "Amber agreed to come to the mission shelter for one night and stayed a month. At the shelter, for the first time in a long while, nothing was asked of her in return — only a bed, a plate of food, and time to start over, if she wanted it. In the evenings the shelter's women prayed together before dinner, and Amber — at first just to fit in — began joining them, until one day she caught herself praying not out of habit but for real, in her own words, for the first time in her life. It was this unconditional care from the shelter's women, who never once asked for anything back, that Amber would later call the first time she physically felt the love of God, rather than just hearing about it in words. The first weeks of sobriety were harder than she'd imagined — withdrawal came in waves at night, and more than once she came within a hair of walking back to her old streets. It was during those weeks that she learned she was pregnant, and made what was maybe the hardest decision of her life — to carry the baby and place it with a loving family through adoption, instead of numbing it all with another hit the way she once would have.", next: 'alina_choice2' },
        alina_bridgeB: { text: "Amber waved her off and went back to her usual streets that same night. The old childhood resentment toward God and church, where it had all started, never went away — it only grew stronger every time she turned away. A couple of weeks later, the same woman found her again on the same corner, with the same hot coffee, without a single word of reproach for turning her down.", next: 'alina_choice2' },
        alina_choice2: { text: "Whether she'd made it through the first brutal weeks of sobriety at the shelter, or simply heard the same invitation again from the coffee woman who never gave up after so many refusals, Amber faces a choice: finally go to a group meeting where she'll have to tell her story out loud to strangers, or go back to where no one asks questions or judges.", choices: [
          { label: "Go, and tell it exactly as it happened", effects: { faith: 15 }, next: 'alina_endLight' },
          { label: "Go back to the street — at least there's no need to explain anything", effects: { faith: -15 }, next: 'alina_endDark' },
        ] },
        alina_endLight: { text: "Amber told her story in a circle of women just like her, and for the first time in years felt no shame — only enormous relief. A few years into sobriety she earned a nursing degree, and today works in the very field that once revived her, and on weekends brews that same hot coffee for other women on the same streets where she once stood herself — not holding out a brochure, but the same patience once shown to her — telling each of them honestly that it was Jesus who lifted the addiction from her, not willpower, which she never had back then at all. She still writes letters to the child she placed for adoption, letters he'll one day be able to read. The end of Amber's story.", next: null, choices: [] },
        alina_endDark: { text: "Amber went back to the street that same night, as always. The woman with the coffee still looks for her every week, so far without luck, and the old photo from her jacket pocket has long since been lost. The childhood resentment toward God, where it had all started, stayed with her to the end — and she never again found anywhere the kind of love she'd once seen in her missionary parents. The end of Amber's story.", next: null, choices: [] },
      },
    },
    zara: {
      start: 'zara_intro',
      scenes: {
        zara_intro: { text: "Leah grew up in an influential Muslim family, on a large ancestral estate in the foothills that generations of her family had held onto along with homes in two European capitals, where relatives spent part of the year. It all collapsed within a single year: first her parents died, one after the other, then her marriage fell apart — and Leah was left entirely alone among the household staff and distant relatives, in a vast house full of strangers' voices and complete inner emptiness.", next: 'zara_scene2' },
        zara_scene2: { text: "Left alone, Leah began praying as she never had before — simple, almost desperate words into the emptiness of the room: \"If You are there, show me who You are.\" She began having unusually vivid, recurring dreams unlike ordinary ones, and a local Christian woman secretly brought her a Bible, which Leah read in the evenings, hiding the book under her pillow from the household staff — in a country where this isn't technically illegal, but where converting from Islam to Christianity is, in practice, often punished far faster and more harshly than any court ever could. The word \"Father,\" which the book used for God, struck her especially hard and almost defiantly — she'd buried her own father so recently, and least of all expected to say that word again to anyone. Unwilling to rely on dreams alone, she also began carefully rereading the Quran she had known by heart since childhood, searching those long-familiar verses for an answer to the same question she whispered into the empty room every night.", next: 'zara_choice1' },
        zara_choice1: { text: "A relative, stopping by the estate to check on her, happened to notice an unfamiliar book on the nightstand and, frowning, asked directly what it was and why Leah was reading something like that instead of the Quran.", choices: [
          { label: "Tell the truth, whatever it costs", effects: { faith: 10 }, next: 'zara_bridgeA' },
          { label: "Lie and keep it a total secret", effects: { faith: -10 }, next: 'zara_bridgeB' },
        ] },
        zara_bridgeA: { text: "Leah told the truth right there by the bed, bracing for a scandal — and it wasn't long in coming. Word swept through relatives and neighbors across the estate within a matter of weeks, gathering details along the way that had never even happened.", next: 'zara_choice2' },
        zara_bridgeB: { text: "Leah lied, claiming on the spot that the book must have been left behind by one of the foreign guests, and kept reading it in secret at night, putting out the light at the smallest creak of a floorboard outside her bedroom door.", next: 'zara_choice2' },
        zara_choice2: { text: "Word of her faith — whether openly admitted by her or carefully hidden away at night — reached the whole area sooner or later regardless, and soon someone tried to burn her house down at night, thankfully destroying only the veranda, but leaving an unmistakable warning. Through a Christian charity that helps people like her, Leah is offered a chance to leave the country immediately, giving up the ancestral estate, the homes in Europe, and everything she had known her whole life.", choices: [
          { label: "Leave that same autumn, whatever lies ahead", effects: { faith: 15 }, next: 'zara_endLight' },
          { label: "Stay — the fear of losing her only home is stronger", effects: { faith: -15 }, next: 'zara_endDark' },
        ] },
        zara_endLight: { text: "Leah left across the ocean with a single suitcase, leaving behind the house where generations of her family had grown up. In her new home, she wrote a book about what she had lived through, which sold hundreds of thousands of copies in several languages and has spent decades helping others walk a similar path. The end of Leah's story.", next: null, choices: [] },
        zara_endDark: { text: "Leah stayed, choosing to bury her faith so deep that at times she doubted it had ever really happened. The house survived, but she never again opened a Bible in daylight, keeping that winter in her memory as something that seemed to have happened to someone else. The end of Leah's story.", next: null, choices: [] },
      },
    },
    viktor: {
      start: 'viktor_intro',
      scenes: {
        viktor_intro: { text: "Nathan ran the legal desk at a major city newspaper, held degrees in both journalism and law, and took pride in never believing a single fact without evidence and cross-referenced sources — that reputation as an unshakeable skeptic mattered to him more than almost any relationship. When his wife suddenly came to faith after several difficult years of marriage, Nathan's first thought was that he'd been swindled, as if someone else had been swapped in for his wife, and he seriously considered divorce before deciding instead that he'd apply the same methods he'd used for years to cross-examine witnesses in court, and easily prove to her with facts that she was wrong.", next: 'viktor_scene2' },
        viktor_scene2: { text: "Nathan, who called himself a committed atheist and had told colleagues more than once that the only thing he trusted was facts backed by at least two independent sources, was used to years of extracting confessions from hardened criminals in the courtroom, and started with what he considered an easy warm-up — a quick rundown of the objections to the resurrection he'd heard dozens of times at press gatherings. But every one of these familiar objections, once he actually checked it seriously instead of just repeating it from memory, fell apart at the first serious primary source — and that irritated him far more than he was willing to admit.", next: 'viktor_choice1' },
        viktor_choice1: { text: "Nathan decides to use every skill from his journalism career to methodically, genuinely take his wife's faith apart with evidence, rather than just wave it off over dinner.", choices: [
          { label: "Start a genuinely honest investigation, wherever it leads", effects: { faith: 10 }, next: 'viktor_bridgeA' },
          { label: "Only gather facts that already confirm he's right", effects: { faith: -10 }, next: 'viktor_bridgeB' },
        ] },
        viktor_bridgeA: { text: "For nearly two years, Nathan methodically studied historical documents, interviewed experts, historians, archaeologists, and legal scholars, trying to find even one weak point in the resurrection account — evenings, squeezed in between his regular newsroom duties, because he couldn't bring himself to truly walk away from the investigation. The deeper he dug as a professional, the harder it became to refute it by the standards of his own field. As a lawyer, he looked first of all for a motive to lie among the witnesses — and found none: almost everyone who claimed the resurrection paid for those words with prison, torture, or execution, and in all his years of legal practice he had never once come across a witness willing to die for his own invention. Harder still was explaining the empty tomb: if the body had simply stayed where it was, the authorities only had to produce it for the crowd to settle the question once and for all — yet neither the Romans nor the Jewish elders, who had every motive in the world to do exactly that, ever did.", next: 'viktor_choice2' },
        viktor_bridgeB: { text: "Nathan hastily put together a folder of objections that satisfied him over breakfast, but it fell apart at the first serious conversation with people who had actually studied the question for years, rather than just repeating the same tired talking points. He was convinced that decades of professional experience let him cut corners and trust the first convenient objection, without even checking it against the same two-independent-source standard he'd spent years demanding from his own reporters.", next: 'viktor_choice2' },
        viktor_choice2: { text: "After two years of an investigation that started as an attack on his wife's faith, Nathan sits with a conclusion completely at odds with where he began two years earlier — and that discovery frightens him more than any story he has ever broken.", choices: [
          { label: "Accept the conclusions of his own investigation and embrace the faith", effects: { faith: 15 }, next: 'viktor_endLight' },
          { label: "Discard his own conclusions, because changing his mind is too uncomfortable", effects: { faith: -15 }, next: 'viktor_endDark' },
        ] },
        viktor_endLight: { text: "Nathan admitted: staying an atheist after an investigation like that would take more blind faith than becoming a Christian — and his professional integrity could no longer allow that. He left journalism to spend his time explaining to others the same investigation that had upended his own life, and turned his two years of research into a book, written in the same language of legal evidence he had once used for his reporting. In time he became a teaching pastor at his church, and the book he never planned to write went on to sell millions of copies worldwide and was made into a feature film about his own investigation. The end of Nathan's story.", next: null, choices: [] },
        viktor_endDark: { text: "Nathan tossed the folder with his own conclusions into a desk drawer and kept his old public opinion — just to avoid admitting to his colleagues that he'd been wrong for two years straight. He still proudly showed off his law and journalism degrees as proof that he knew how to tell fact from fiction — but he never opened the folder holding his own investigation's conclusions again. His wife never brought up the subject at dinner again. The end of Nathan's story.", next: null, choices: [] },
      },
    },
    ruslan: {
      start: 'ruslan_intro',
      scenes: {
        ruslan_intro: { text: "Ethan had known the sacred texts by heart since childhood and had spent his whole life preparing to defend his faith — that is what his whole family expected, proud of what a serious child he had grown into. At medical school he became friends with a Christian classmate — their first argument started when Ethan spotted an open Bible in his room and, sure of an easy win, struck up the conversation himself — and their friendship quickly turned into a years-long, but always respectful, argument, carried on alongside years of medical training where both were used to demanding proof before taking anything on faith.", next: 'ruslan_scene2' },
        ruslan_scene2: { text: "The argument went on for years over tea after lectures, never once turning into a quarrel — they respected each other too much to get personal, though both had honestly warned each other from the start that they were willing to follow the truth even if it meant tearing down everything they'd believed since childhood. Ethan knew all the standard answers to the standard questions in advance, but his friend stubbornly refused to ask standard questions, digging far deeper than Ethan was used to answering.", next: 'ruslan_choice1' },
        ruslan_choice1: { text: "After one such conversation, his friend raised a serious historical argument from primary sources that Ethan — for all his preparation — could not find a convincing answer to, and that frightened him far more than any argument before it.", choices: [
          { label: 'See the question through to the end, even if he will not like the answer', effects: { faith: 10 }, next: 'ruslan_bridgeA' },
          { label: 'Close the subject and never raise it with his friend again', effects: { faith: -10 }, next: 'ruslan_bridgeB' },
        ] },
        ruslan_bridgeA: { text: "For three and a half years Ethan studied the sources of both faiths in the evenings, secretly from most people he knew, meticulously documenting every finding as if he were keeping a medical chart rather than a personal record of doubt — a habit medicine itself had trained into him. At some point, for the first time in his life, he began directly asking God in prayer for a personal sign, not just a textual one — and not long after one such night, he had a dream he took as a direct answer to that request. Not to win the next round of tea-time debate, but to finally, once and for all, learn the truth, however uncomfortable it turned out to be.", next: 'ruslan_choice2' },
        ruslan_bridgeB: { text: "Ethan avoided the subject for months, finding ever new excuses to postpone meeting his friend. He kept telling himself he already knew the answer — he just needed to reread the right passage more carefully — but each time he set the book down without finding what he was looking for. The question left unanswered kept sounding in his head every time he opened his usual books before bed.", next: 'ruslan_choice2' },
        ruslan_choice2: { text: 'Years into secret study, Ethan arrives at a conclusion that frightens him: he can no longer honestly defend his old faith to himself, let alone to others — and an open conversion will cost him nearly every relationship he has, including his family.', choices: [
          { label: 'Accept what he believes to be true, whatever the cost', effects: { faith: 15 }, next: 'ruslan_endLight' },
          { label: 'Stay in his old faith for the sake of family and friends', effects: { faith: -15 }, next: 'ruslan_endDark' },
        ] },
        ruslan_endLight: { text: "Ethan made the choice he calls the most painful of his life — and, as he feared, lost nearly everyone he loved within a single year, including his father, who never fully forgave him. He left medicine to have those same honest debates on stage in front of thousands, joined an international Christian apologetics ministry, and finished a book about his journey that became a bestseller in several languages. At thirty-three he was diagnosed with stage IV stomach cancer, but even then he didn't stop — recording videos for his audience from his hospital bed and honestly explaining the path of doubt and loss he had walked himself, not just where he ended up — until the illness took him far too young. The end of Ethan's story.", next: null, choices: [] },
        ruslan_endDark: { text: "Ethan stayed in his old faith, keeping his family and familiar circle of friends, but his friend's question was never honestly answered — just buried deep enough not to keep him up at night. He went on to become a practicing doctor, just as his family had always hoped, but from time to time, especially during night shifts, he found himself thinking back to that unresolved conversation and wondering what he'd say to his friend now, years later, if he ever worked up the nerve to ask again. The end of Ethan's story.", next: null, choices: [] },
      },
    },
    roman: {
      start: 'roman_intro',
      scenes: {
        roman_intro: { text: "Derek built his network in Queens and, together with his older brothers, supplied cocaine up and down the Eastern Seaboard, working directly with a Colombian cartel — money, risk, and other people's fear were as normal a part of his life as morning coffee is for other people, until he was set up by one of his own associates, caught by federal agents and turned informant. Even before building the network with his brothers, Derek himself got hooked on marijuana at twelve, joined a street gang at thirteen, and started selling small amounts of cocaine in his own Queens neighborhood just to pay for his own growing habit — only later did it grow into supplying the whole Eastern Seaboard. He was one of five brothers in a family of Dominican immigrants who had come to New York in the early sixties with almost no money, hoping for a better life for their children.", next: 'roman_scene2' },
        roman_scene2: { text: "Derek and one of his brothers were pulled over on the highway while delivering product to a client in Manhattan — both tried to run but were caught on the spot, and the car held nearly four million dollars' worth of cocaine. Derek had long sensed this day would come, and the moment of arrest brought not so much fear as a strange, almost relieving feeling: no more waiting. The arrest came during a citywide crackdown on drug traffickers — Derek was first taken to the notorious Rikers Island jail, and only from there was he moved through the state prison system to await trial.", next: 'roman_choice1' },
        roman_choice1: { text: "The prosecutor initially demands twenty-five years for everything at once. His lawyer, looking away, says there's a real chance to significantly cut the sentence if Derek can convincingly show the court he is genuinely changing — before the trial itself, not after.", choices: [
          { label: 'Look honestly, for the first time, at who he has become', effects: { faith: 10 }, next: 'roman_bridgeA' },
          { label: 'Treat it purely as a tactic for a shorter sentence', effects: { faith: -10 }, next: 'roman_bridgeB' },
        ] },
        roman_bridgeA: { text: "Even before the trial, his older brother, himself newly a believer, began visiting Derek regularly in the detention center, and one day, without any pressure, simply told him about Jesus — not like a preacher on schedule, but like family. His brother had greeted him that day with the words, \"Hallelujah, praise the Lord — you know God loves you,\" and at first Derek just brushed it off irritably, sure prison had driven his brother a little crazy. Derek started attending the prison chapel services — at first just to kill time between interrogations, but at one of the gatherings an inmate preacher said something that lodged in him deeper than any fine speech, that the peace God gives surpasses all human understanding, and against all expectation he felt for the first time in his life that real, tangible peace inside, not just a passing lull. He began keeping a short journal in the evenings, trying honestly, for the first time in his life, to reckon day by day how many people and families had been hurt by what he'd built for money. Months later he began leading part of the services himself, reading Bible passages aloud to new inmates who, like he once had, came to the chapel just to kill time between interrogations.", next: 'roman_choice2' },
        roman_bridgeB: { text: "Derek dutifully showed up at the services just for show, rehearsing the right words of remorse in front of his cell mirror for the future judge, but nothing genuinely changed inside — only his irritation grew at having to pretend. That same brother, during one of his rare visits, quietly said to his face, \"You know God loves you\" — but Derek just shook his head and changed the subject to trial-defense details, never really answering.", next: 'roman_choice2' },
        roman_choice2: { text: "The judge reads out the reduced sentence — three years instead of the original twenty-five, amid hushed whispers in a courtroom where both former customers and the parents of people pulled into his network are sitting. Derek now has those specific years to decide, in action rather than words to a judge, who he'll be when he walks free.", choices: [
          { label: 'Use these years to genuinely become a different person', effects: { faith: 15 }, next: 'roman_endLight' },
          { label: 'Just sit out the sentence and go back to his old connections', effects: { faith: -15 }, next: 'roman_endDark' },
        ] },
        roman_endLight: { text: "Derek walked out of prison a completely different man and returned to the same city not as a dealer, but as the pastor of a small church in the same neighborhood where he once sold death. Today his church is full of people the whole district used to fear — including, once, himself. After his release Derek wrote a book about the road he'd traveled — Shifting Shadows: How a New York Drug Lord Found Freedom in the Last Place He Expected — and besides pastoring his own church he now also runs a separate children's ministry in the same neighborhood where he once recruited teenagers just like he'd been at thirteen. The end of Derek's story.", next: null, choices: [] },
        roman_endDark: { text: "Derek walked free right on schedule and restored his old connections almost immediately, as if those years behind bars had never happened. They changed little besides the address where his new case summonses are now sent. The book he might have written in other circumstances, he never started, and the chapel he once visited only for show, he never thought about again. The end of Derek's story.", next: null, choices: [] },
      },
    },
    anton: {
      start: 'anton_intro',
      scenes: {
        anton_intro: { text: "Jake ended up homeless and addicted to heroin on the street at twenty-five — it all started innocently enough, with petty street crime and company that seemed fun, and ended with nothing left to lose, including a roof over his head. The addiction didn't start with tragedy but with boredom: at twelve he tried pills and alcohol simply because, as he put it later, he was bored and wanted a thrill. By thirteen he was already stealing cars just for the ride, and at fourteen he ran away from home and hitchhiked across the country. He'd once sworn to himself he'd never touch heroin, but at seventeen he broke that vow — and never stopped again.", next: 'anton_scene2' },
        anton_scene2: { text: "In winter, Jake learned to find the warm subway ventilation grates and to tell which courtyards he could sleep in without risk of being chased off or robbed by his own kind. He had long since stopped counting days and almost stopped considering himself someone for whom any other life was possible. By his late twenties he was cycling through several different clinics on forged paperwork just to get methadone in doses that would have killed an ordinary person — each time just a way to make it to the next day, not a reason to stop.", next: 'anton_choice1' },
        anton_choice1: { text: 'Someone at the homeless shelter Jake only visited to warm up offers him something simple: just come to the evening meeting and listen — no conditions, no pressure to join a program, just come once.', choices: [
          { label: 'Come, because he really has nothing left to lose', effects: { faith: 10 }, next: 'anton_bridgeA' },
          { label: "Refuse — he doesn't believe in anything or anyone anymore", effects: { faith: -10 }, next: 'anton_bridgeB' },
        ] },
        anton_bridgeA: { text: "Jake came out of pure curiosity and stayed listening far longer than he had planned. At the end he was told simply to give his life to God right there, in the hall — and, without really knowing what that meant, he did exactly that, more out of exhaustion than faith. He later learned that the people in that hall had been praying for him every day for three months before he ever agreed to come — and only told him so that same night. During the group prayer his body suddenly began to shake and break out in a cold sweat, and his mind, submerged in a drug haze for years, felt clear for the first time in two decades.", next: 'anton_choice2' },
        anton_bridgeB: { text: "Jake refused and spent that night in his usual spot — on the subway grate, with the usual dose, listening to the same meeting he had been invited to sounding faintly somewhere in the distance. It wasn't the first time he'd been offered a chance like that: over years of arrests, more than one cellmate in a holding cell had told him about places that actually helped people like him — but each time it sounded like just another empty story, and he went right back to where he'd come from.", next: 'anton_choice2' },
        anton_choice2: { text: "The next morning Jake's body demands its usual dose of heroin, as it had demanded every morning for years — but something inside him, which he cannot quite explain even to himself, holds him in place for the first time instead of driving him out to find it.", choices: [
          { label: 'Not go looking for the dose, and stay at the shelter', effects: { faith: 15 }, next: 'anton_endLight' },
          { label: 'Go looking for the usual dose, like every morning', effects: { faith: -15 }, next: 'anton_endDark' },
        ] },
        anton_endLight: { text: "Jake did not go looking for the dose — and, against everything he knew about withdrawal from past experience, felt none of the usual agony in his body. He calls it not willpower, which he had never had, but someone else carrying it for him, on that one particular day. Within a few months of sobriety he was finally able to call his family again, and for the first time in years said his own full name out loud instead of his street nickname. The small Bible studies he started leading eventually grew into a community around a soup kitchen for the homeless, and later into his own church with a prison ministry and a housing program for ex-felons — the very kind of place a stranger's offhand suggestion had once led him to. The end of Jake's story.", next: null, choices: [] },
        anton_endDark: { text: "Jake went looking for his usual dose, like any other morning. The homeless shelter remained just another stop on his route, somewhere he sometimes drops by to warm up in winter, nothing more. Years later he still occasionally ended up in the same holding cells, where someone would try again to tell him about God, and every time it ended with the same indifferent shrug. The end of Jake's story.", next: null, choices: [] },
      },
    },
    pavel: {
      start: 'pavel_intro',
      scenes: {
        pavel_intro: { text: 'Paul was diving for lobster off a tropical island when he was stung, one after another, by five deadly jellyfish — a rare, almost impossible occurrence. The venom was enough to kill an ordinary person within four minutes, and at that moment he believed neither in God nor in any life after death.', next: 'pavel_scene2' },
        pavel_scene2: { text: 'Friends on the boat pulled Paul out of the water already convulsing, his skin blackened by burns where the tentacles had touched him. While they waited for the rescue boat, his body began going numb from the feet up, and his consciousness began fading in slow, heavy waves, as if someone were gradually turning off the lights in different rooms of the same house.', next: 'pavel_choice1' },
        pavel_choice1: { text: 'As his body went numb and his consciousness faded completely, Paul unexpectedly and clearly remembers the one Christian in his family — his mother, who had prayed for him every single day for as long as he could remember — and her old words that you can call on God even now, in the last second, if you truly want to.', choices: [
          { label: 'Call on God from the depths of his heart, even without truly believing', effects: { faith: 10 }, next: 'pavel_bridgeA' },
          { label: 'Wave the thought off as a dying delirium', effects: { faith: -10 }, next: 'pavel_bridgeB' },
        ] },
        pavel_bridgeA: { text: "Paul called out — not a proper prayer, the rules of which he didn't really know, but simply a cry of despair from the depths of what remained of his consciousness. First an absolute, freezing darkness closed in around him — a loneliness so complete he later called it the only real death he ever experienced. Then a light appeared, and in that light he saw his entire life at once, every wrong thing he'd ever done, plainly and truthfully, without a single accusation — and felt not condemnation but a question: did he now, knowing all of it, want to start over. In that same light he clearly sensed not emptiness and not some faceless force, but a Person — loving so unconditionally that the shame of his own life began to melt away on its own, as though he'd been met not by a judge but by someone who had been waiting for him at home for years. Even without a single word spoken, he understood the main thing: that light had a name, and that name belonged not to some abstract idea but to the One who had once passed through real death himself, so that this very moment could possibly end another way. Moments later, doctors in the ambulance officially pronounced him dead.", next: 'pavel_choice2' },
        pavel_bridgeB: { text: 'Paul dismissed the thought of God as nonsense produced by a dying brain, and simply waited for it to be over — without a single prayer, without a single word directed anywhere beyond his own fading mind. Doctors in the ambulance soon pronounced him dead, exactly as all the signs indicated.', next: 'pavel_choice2' },
        pavel_choice2: { text: 'Twenty minutes later, already in the hospital morgue, on a metal table for bodies under a sheet, Paul unexpectedly and inexplicably comes back to consciousness — alive, completely paralyzed, unable to move a single muscle, but alive, to the horror of the orderly who walks into the room and drops his clipboard.', choices: [
          { label: 'Accept this as a second chance, given for a reason', effects: { faith: 15 }, next: 'pavel_endLight' },
          { label: 'Write it off as a rare medical fluke and forget about it', effects: { faith: -15 }, next: 'pavel_endDark' },
        ] },
        pavel_endLight: { text: "Lying paralyzed, overhearing doctors murmur to each other that he wasn't likely to make it, Paul spent the whole night asking for one thing without stopping: that every cell in his body, poisoned by the venom, would be healed by morning. By dawn he could move a finger, then a hand, and by noon he walked out of the hospital on his own two feet, though every medical prognosis said he should have stayed paralyzed for life, if he survived at all. He wrote a book about what happened and since then has traveled to dozens of countries on every continent, speaking to packed halls about exactly what he saw beyond that line — darkness, light, judgment, and a choice, not just a story of a miraculous escape from jellyfish venom in warm tropical water. The end of Paul's story.", next: null, choices: [] },
        pavel_endDark: { text: "Paul wrote off what happened as a rare, unexplainable medical miracle and tried to forget about it as quickly as possible, going back to his old life as a diver — the same boat, the same night dives for lobster, the same crowd of friends at the bar after his shift. Doctors examining him before discharge just shook their heads, unable to explain either the burns that healed faster than normal or the paralysis that lifted on its own — but for Paul it stayed just a medical oddity, never a reason to ask a deeper question. Sometimes at night he still remembers that tunnel of light and the darkness before it — and still hasn't decided for himself what to do with that memory, putting off that conversation with himself for a tomorrow that never quite comes. The end of Paul's story.", next: null, choices: [] },
      },
    },
    yulia: {
      start: 'yulia_intro',
      scenes: {
        yulia_intro: { text: "Julia was born into a closed missionary community that moved between communes on several continents, living by the rules of a single movement leader — what to wear, who to be friends with, which literature was even allowed to be opened. Nobody there gave a second thought to school diplomas, the kind other kids outside the community took for granted: the one subject that mattered was unconditional obedience. Because of the constant moves, Julia grew up across six countries on several continents and could speak three languages by ear long before she properly learned to read in any of them.", next: 'yulia_scene2' },
        yulia_scene2: { text: "Julia genuinely believed that obedience to the organization was faith itself, and saw almost nothing beyond the communes in all twenty-three years she lived there. By that age she made a decision unthinkable to almost everyone she'd known since birth: to leave completely alone, with no normal school records and not a single acquaintance on the outside. The only prayer she knew was the memorized collective chant the whole community recited in unison on the leader's cue every morning — she had never once found her own words for talking to God.", next: 'yulia_choice1' },
        yulia_choice1: { text: "Working several odd jobs at once and renting a bunk in a hostel, Julia set herself an almost impossible goal — pass the exams and get into a real college. At her admissions interview, the dean asked point-blank why her records showed no normal school history, and clearly expected a full explanation.", choices: [
          { label: 'Tell the truth about the cult she grew up in', effects: { faith: 10 }, next: 'yulia_bridgeA' },
          { label: 'Lie and invent a comfortable version of her childhood', effects: { faith: -10 }, next: 'yulia_bridgeB' },
        ] },
        yulia_bridgeA: { text: "Julia told the truth, expecting rejection — but instead the dean arranged tutors for her and helped her cover five years of schooling in two. Learning that Julia had grown up across six countries and picked up three languages by ear, the dean, to her surprise, secured her a full scholarship — the nomadic childhood she'd been ashamed of suddenly became an asset on paper. She studied nights after work, reading through the very Bible she'd only ever been allowed to hear filtered through preachers' retellings, never in full with her own eyes. That same winter she tried, for the first time in her life, to pray in her own words instead of the group chant — and found herself at a loss for where to even begin when no one was leading her.", next: 'yulia_choice2' },
        yulia_bridgeB: { text: "Julia lied, inventing a comfortable home story with no mention of the community, and the dean asked nothing further. The lie spared her the awkward looks of her classmates, but every retelling of a 'normal childhood' grew heavier to carry, and she started avoiding personal conversations altogether. She never worked up the nerve to tell the dean about the six countries and three languages that had shaped her far more than any school — and along with them, she erased from her new biography the one real prayer she'd ever tried to say in her own words.", next: 'yulia_choice2' },
        yulia_choice2: { text: "Years later, now holding a real law degree and working at a major firm, Julia gets an offer from a publisher — write a book under her own name about what actually went on inside the community she grew up in. Publishing it would mean telling her fellow lawyers, who still think of her as an ordinary person with an ordinary past, everything.", choices: [
          { label: "Write the book under her own name, hiding nothing", effects: { faith: 15 }, next: 'yulia_endLight' },
          { label: "Decline, and leave the past buried for good", effects: { faith: -15 }, next: 'yulia_endDark' },
        ] },
        yulia_endLight: { text: "Julia wrote the book under her own name, softening nothing for the comfort of old acquaintances from the community. It reached thousands of readers, many of whom had grown up in similar closed groups and, for the first time, learned they weren't alone in carrying that kind of story. Readers most often wrote her the same thing: that after reading her book, they tried for the first time to pray in their own words instead of someone else's memorized text, just as she once had. Part of her family, having eventually left the community themselves, reached out to her again after the book came out, for the first time in years. The end of Julia's story.", next: null, choices: [] },
        yulia_endDark: { text: "Julia turned down the book, deciding that the safe image of a lawyer with no past was safer than any honesty. She went on living with the sense that at any moment someone could find out the truth, and that quiet dread stayed with her through all the years of her career that followed. The chant memorized in childhood remained the only prayer she ever knew how to say — she never found her own words for talking to God in all the years since. The end of Julia's story.", next: null, choices: [] },
      },
    },
    oksana: {
      start: 'oksana_intro',
      scenes: {
        oksana_intro: { text: "Erin came home after ten months in a war zone, where she'd served in combat roles alongside the men of her unit and more than once, treating the wounded under fire, silently repeated a short, desperate prayer — 'God, let me get home alive' — and once home, she did not recognize herself in the mirror: flinching at any slammed door, unable to sleep more than two hours straight, pouring herself a little more every evening just to shut her mind off for a while. Erin served in the Army National Guard and later the Army Reserve, and her job on deployment wasn't holding a weapon on the front line but transporting the wounded straight out of gunfire and treating them on the spot, whispering one more short prayer over the stretcher every time — 'God, don't let this one die' — before the evacuation arrived.", next: 'oksana_scene2' },
        oksana_scene2: { text: "At home, her daughter greeted her with a 'welcome back' drawing that hung on the fridge for just a week before Erin stopped noticing it at all. The neighbors knew her as a quiet, polite woman — no one but her daughter saw how her hands shook at night, when the bottle ran out before sleep did. A woman from a Christian organization that works with the military reached out to her first, within the first months after she came home, but Erin flatly refused to talk and simply shut the door on her.", next: 'oksana_choice1' },
        oksana_choice1: { text: "Her daughter, who'd barely turned ten, increasingly hid in her room with the door shut whenever her mother came home drunk in the evenings. A neighbor in the building, a quiet believing woman they barely exchanged greetings with, said one day, without any pressure: 'Come to our Easter service, just sit with us, nothing more.'", choices: [
          { label: "Come, at least once, because there's nothing left to lose", effects: { faith: 10 }, next: 'oksana_bridgeA' },
          { label: "Refuse — she doesn't need anyone's pity", effects: { faith: -10 }, next: 'oksana_bridgeB' },
        ] },
        oksana_bridgeA: { text: "Erin came to that Easter service and, to her own surprise, came back again a week later. The service that day was specifically about Christ as a Commander — in language that she, having served nearly a year on the front line, could genuinely understand — and afterward the pastor told her a single sentence she would remember for years to come: 'Now you serve a new Commander in Chief.' Week after week, the church's pastors simply, kindly stayed near her, asking nothing and demanding no explanations — and after months of that steady, entirely undeserved care, the armor she'd spent years building up since her service began to crack, and she chose to speak first herself about things she'd never told even her military psychologist. Around those same days she rewatched a short film about combat PTSD that she would later help make herself — fifteen simple minutes of human stories instead of medical terms that finally let her say out loud about herself what she had never admitted even to herself before. That first prayer since coming home — 'God, I want to follow Your leadership' — she said out loud, not just under her breath, for the first time in all her years of service and after it.", next: 'oksana_choice2' },
        oksana_bridgeB: { text: "Erin refused and kept coping alone, as she had learned to during her service. The bottle gradually became more familiar and easier to understand than her own daughter, sitting quietly behind a closed door in the next room. That same woman from the Christian military organization who'd first reached out right after she came home called again more than once in the months that followed — but Erin cut the call short every time and hung up.", next: 'oksana_choice2' },
        oksana_choice2: { text: 'Months into regular meetings, Erin is asked to speak to a group of other veterans who, like her, came home completely different people and have stayed silent about it for years.', choices: [
          { label: 'Tell it all honestly, including the bottle and the shame', effects: { faith: 15 }, next: 'oksana_endLight' },
          { label: 'Refuse — it is too personal to share with strangers', effects: { faith: -15 }, next: 'oksana_endDark' },
        ] },
        oksana_endLight: { text: "Erin told it all exactly as it was, including the bottle and the shame in front of her daughter. Today she works with veterans just like herself, helping them walk the path she walked — from a bottle every night to a daughter who finally stopped hiding when her mother comes home. She now volunteers with the very combat-PTSD task force at the Christian military organization she once refused to even talk to, and helps make the same kind of short films about war and faith that once helped her say the truth out loud for the first time. The end of Erin's story.", next: null, choices: [] },
        oksana_endDark: { text: "Erin refused to share and kept coping alone to the end. Her daughter grew up remembering a mother who was always physically there, but truly present only rarely. That same Christian military organization that first offered her help wrote to her a few more times over the following years, but never got a reply. The end of Erin's story.", next: null, choices: [] },
      },
    },
    vika: {
      start: 'vika_intro',
      scenes: {
        vika_intro: { text: "Victoria was a pastor's wife, and for years explained away her bruises as her own clumsiness — first to herself, then to doctors at checkups, then to her small children, who started asking uncomfortable questions. Since her wedding day she'd been told that a wife's submission to her husband was part of submission to God, and she genuinely believed it — meaning she had to endure however much it took, and her own pain was no reason to break something meant to be sacred. Leaving a husband who served in ministry meant not just a divorce, but wrecking the whole congregation's standing — and that held her in place harder than any bruise.", next: 'vika_scene2' },
        vika_scene2: { text: "Year after year followed the same circle: a fight, shouting, a blow, tears, apologies, calm again for a few weeks — and then back to the start. Every night after, Victoria prayed the same prayer — not for a way out, but that her husband would change and that she'd find the strength to endure a little longer. With the congregation, and even with part of her own family, she had long since perfected the same story about her own clumsiness, knowing that a pastor's wife complaining of beatings would wreck far more than just her own marriage.", next: 'vika_choice1' },
        vika_choice1: { text: "After one especially brutal night, when she had to explain a bruised cheekbone not to the congregation but to her own child, a friend who happened to see her battered face quietly held out the number for a help center and said: 'Just keep it on you. You don't have to call today.' Victoria took the slip of paper in silence, feeling that for the first time in years someone had offered her help instead of one more reason to endure a little longer.", choices: [
          { label: 'Keep the number and call when things get truly frightening', effects: { faith: 10 }, next: 'vika_bridgeA' },
          { label: "Throw the number away — she doesn't want to wreck her husband's reputation", effects: { faith: -10 }, next: 'vika_bridgeB' },
        ] },
        vika_bridgeA: { text: "Victoria kept the number, tucked into the lining of her wallet. Before dialing it, she opened her Bible for the first time in years not to find confirmation for her endurance, but with a real question: did God actually want her to stay somewhere she feared for her own life? The answer she found that evening wasn't about obeying her husband — it was about her body and her life being valuable to God in their own right. That same evening she finally worked up the nerve to call and leave with the children, knowing this would inevitably mean long years of custody litigation ahead — far longer and more exhausting than she could have imagined while still inside the marriage.", next: 'vika_choice2' },
        vika_bridgeB: { text: "Victoria threw the number away that same evening and stayed, deciding her husband's and the whole congregation's reputation mattered more than her own safety. That night she prayed the same prayer she'd prayed for years — asking for strength to endure a little longer, not for a way out. Her friend, hearing about it, never reproached her with a single word — she simply held out the same number again a few weeks later, rewritten on a separate card.", next: 'vika_choice2' },
        vika_choice2: { text: "In the middle of an exhausting custody battle that clearly threatened to drag on for years, Victoria prayed the same thing every morning before a hearing — not for a win in court, but that she wouldn't lose herself in the fight. She had to decide whether to keep fighting in court for her children and for the truth of what had happened, or to back down just to make it all end sooner.", choices: [
          { label: 'Keep fighting for her children and the truth, however many years it takes', effects: { faith: 15 }, next: 'vika_endLight' },
          { label: "Back down, just so it's over sooner", effects: { faith: -15 }, next: 'vika_endDark' },
        ] },
        vika_endLight: { text: "Victoria went through a custody battle that stretched on for almost ten years, and through all of it held on to a faith that felt no less real to her than the exhausting fight itself. The prayer that once asked for strength to endure became something else entirely — gratitude that God had been on the side of her safety the whole time, not on the side of her silence. Today, together with other women like her, she runs a support ministry for believing mothers going through divorce after leaving a marriage like hers — with ready-made materials for preparing for custody hearings, and with the most important message of all: God never asked her to stay somewhere she was being hurt. The end of Victoria's story.", next: null, choices: [] },
        vika_endDark: { text: "Victoria backed down in the custody battle before it was over, just to make it end sooner — and for years afterward regretted not having had the strength to see the fight for her children and the truth through to the end. The end of Victoria's story.", next: null, choices: [] },
      },
    },
    tanya: {
      start: 'tanya_intro',
      scenes: {
        tanya_intro: { text: 'Tara had a doctorate in theology and worked as an assistant chaplain at a university — comforting and supporting others as part of her job — when she first heard voices, quiet and almost gentle at first, then demanding and cruel. Doctors called it psychosis linked to bipolar disorder; Tara herself, a doctor of theology by training, spent long months unable to find in her own books where the illness ended and something else began, something with no medical name. Her first real breakdown had come shortly after the birth of her child — doctors called it postpartum depression at the time, and only later, after several more episodes, did she receive the far more serious diagnosis.', next: 'tanya_scene2' },
        tanya_scene2: { text: "The first of several hospitalizations was especially hard — her colleagues at church didn't know how to act around a chaplain who had suddenly become a patient on a psychiatric ward herself. Many in the congregation were used to seeing Tara as someone who gives comfort, not someone who needs it, and some of them simply vanished from her life, as if the diagnosis were contagious. Even her own theology students had no idea where she had disappeared to during those weeks. Alongside teaching and chaplaincy, she had spent years on the board of a local chapter of a family support organization for people with mental illness, and on the advisory board of the university's psychiatric hospital — she knew the subject from both sides long before she ever admitted it out loud herself.", next: 'tanya_choice1' },
        tanya_choice1: { text: 'During her third hospitalization that year, a longtime colleague from the faculty offered to talk with Tara honestly, without comforting theological formulas, about what she was actually feeling right now — not chaplain to chaplain, but simply one suffering person to another.', choices: [
          { label: 'Agree, and for the first time not hide behind her professional role', effects: { faith: 10 }, next: 'tanya_bridgeA' },
          { label: 'Refuse — too strange to end up on the other side herself', effects: { faith: -10 }, next: 'tanya_bridgeB' },
        ] },
        tanya_bridgeA: { text: "To her own surprise, Tara agreed, and the conversation turned out to be nothing about explaining the illness away with faith, or excusing it by faith — just someone, for the first time in a long while, listening to her as a person, not as a chaplain who was supposed to manage on her own. She went back to the same fixed hours of prayer, following the ancient monastic pattern she herself had spent years teaching her students but had long since stopped truly living herself — and the old psalms, with their honest complaints to God, began to sound to her completely different from lines in a textbook.", next: 'tanya_choice2' },
        tanya_bridgeB: { text: 'Tara refused and spent those weeks on the ward in almost total silence, out of habit still comforting the other patients with words she could no longer apply to herself, alone with the voices that the medication muted to a whisper but never fully took away.', next: 'tanya_choice2' },
        tanya_choice2: { text: "Years later, after several more hospitalizations, Tara is offered the chance to write an honest, first-person book about faith and mental illness — not a theological treatise for other people's crises, but an admission that she herself had struggled with exactly this for years, as someone others trusted to comfort them. The publisher asks her directly not to skip the hardest chapters — the suicidal thoughts, the psychiatric wards themselves, the electroconvulsive therapy she had to undergo — the things usually left unspoken inside the church.", choices: [
          { label: "Write it honestly, including the moments when faith didn't offer instant rescue", effects: { faith: 15 }, next: 'tanya_endLight' },
          { label: 'Refuse — too risky to admit weakness in front of the whole congregation', effects: { faith: -15 }, next: 'tanya_endDark' },
        ] },
        tanya_endLight: { text: "Tara wrote the book without embellishment, honestly describing both the voices and the attacks of despair, and how the church sometimes answered her pain with empty comfort instead of real presence beside her. She writes plainly: the bipolar disorder never went away, and hospitalizations sometimes still happen — faith didn't replace the medication and the psychiatrist, but stayed alongside the treatment, not instead of it. The book reached thousands of believers who, for the first time, honestly heard that mental illness and deep faith can coexist in one person at once, without canceling each other out. Reissued years later, the book came out with a foreword from one of the country's best-known church leaders, which widened its readership even further. The end of Tara's story.", next: null, choices: [] },
        tanya_endDark: { text: 'Tara refused to publish the book, deciding that admitting to this particular weakness would cost her professional reputation as a chaplain too much. She kept comforting others on schedule, hiding her own hospitalizations even from her closest colleagues on the faculty. The end of Tara\'s story.', next: null, choices: [] },
      },
    },
    galya: {
      start: 'galya_intro',
      scenes: {
        galya_intro: { text: "Gail and her husband declared bankruptcy after their small family business collapsed in a single year over one failed deal. It got to the point where the house did not even have a refrigerator, and food was kept in an ordinary camping cooler box, refilled with ice at the supermarket every day. On top of the ordinary business debts came a tax debt that had quietly piled up for years — together they became the wall that no new loan could get around anymore.", next: 'galya_scene2' },
        galya_scene2: { text: "In the first months after the bankruptcy, Gail tried to keep the kids from noticing the difference — inventing games instead of the usual shopping trips, joking about a 'camping adventure' instead of admitting there wasn't money for a normal dinner. At night, once everyone was asleep, she would stare for a long time at the stack of unpaid bills, not knowing where to even start. In the evenings during those months a Christian TV channel was often left on in the background — Gail listened to programs about how God cares about the way a Christian handles money, even though she and her husband had no savings at all to actually try any of it.", next: 'galya_choice1' },
        galya_choice1: { text: "A woman from church, who happened to learn their real situation from a mutual acquaintance, did not offer a loan — she simply said: 'Come by tomorrow morning, we will sit down together and work through your finances God's way, step by step.'", choices: [
          { label: "Come, even though it is humiliating to admit how bad things are", effects: { faith: 10 }, next: 'galya_bridgeA' },
          { label: 'Refuse — pride will not let her show poverty to outsiders', effects: { faith: -10 }, next: 'galya_bridgeB' },
        ] },
        galya_bridgeA: { text: "Gail came, burning with shame through the entire first hour of the conversation. Every meeting began with prayer, and the plan itself was built around one specific biblical principle — 'give, and it will be given to you' — which Gail read over and over, at first unable to see how to live by it when there seemed to be nothing left to give. Gradually the shame gave way to unexpected relief — it turned out she was not the only family among people she knew going through this, and there was an actual plan she could really follow, not just endure. Instead of a loan, they were offered something else — to give not money they didn't have, but time: Gail started helping at a food pantry for families in need, and her husband began delivering meals to elderly people living alone nearby, even while they themselves were barely scraping by. That was when they started setting aside a tithe for the first time in their lives, even from the small odd jobs they managed to find — not because there was suddenly extra money, but in spite of having none at all.", next: 'galya_choice2' },
        galya_bridgeB: { text: "Gail refused the help out of pride and kept coping silently, hiding the debt letters from her husband and children in the back of a drawer, until the stack grew too thick to keep hiding. The kind of help the church had offered — not a loan, but work at a food pantry alongside other families in the same situation — Gail never actually tried, deciding that standing there among people in need would be even more humiliating than hiding the bills in a drawer.", next: 'galya_choice2' },
        galya_choice2: { text: 'Two years into painstakingly working through the debt and retraining herself to live within her means, Gail is asked to tell her story to other families in the same situation at a community meeting.', choices: [
          { label: 'Tell it all honestly, including the cooler box of ice', effects: { faith: 15 }, next: 'galya_endLight' },
          { label: 'Refuse — the past is better left in the past', effects: { faith: -15 }, next: 'galya_endDark' },
        ] },
        galya_endLight: { text: "Gail told it all honestly, starting with that very camping cooler box instead of a refrigerator. Today she and her husband run the same course for families going through what they once went through — starting every session with the words 'we did not have a refrigerator either.' The small business they started over again right out of their rented apartment was, within a few years, serving major national companies, and once even filled an order for the White House — and revenue that had once fallen short of a new refrigerator was, years later, approaching a hundred million dollars. Gail's husband still repeats the same line at every one of these meetings: it was never really about the money, but about whose hands manage the little you actually have. The end of Gail's story.", next: null, choices: [] },
        galya_endDark: { text: "Gail refused to tell her story, and although the debts were eventually paid off, the shame of those years remained a family secret, unspoken even between the two of them behind closed doors. The food pantry where she'd been invited to help, not to receive, stayed just a place Gail occasionally drove past, never once going inside. The end of Gail's story.", next: null, choices: [] },
      },
    },
    denis: {
      start: 'denis_intro',
      scenes: {
        denis_intro: { text: "Dennis had risen through the ranks of a radical nationalist group to become one of its regional leaders, recruiting new members among angry teenagers just like he had once been — hatred was not a belief for him but a way of life he chose fresh every day, seeing in it, since youth, the only way to matter. By thirty he had climbed to the rank of Grand Dragon, one of the highest posts in the Ku Klux Klan's hierarchy, and when even the Klan began to feel not harsh enough, he joined a neo-Nazi group and marched with them in a rally the whole country would later talk about.", next: 'denis_scene2' },
        denis_scene2: { text: 'Dennis kept two versions of his life: an ordinary job for the paperwork, and a completely different, nocturnal one, with flags and marches, that he actually lived for. He had long since stopped noticing the faces of the people he shouted at during rallies — they were not people to him, but symbols of whatever he was fighting, and the tattoos on his arms told any stranger passing by, plainly and without doubt, exactly who they were dealing with.', next: 'denis_choice1' },
        denis_choice1: { text: 'A pastor of a Black church across town, hearing about Dennis, did not avoid him — instead he found a way to pass along an invitation to talk one on one, no cameras, no witnesses, which struck Dennis as either madness or a trap.', choices: [
          { label: 'Go to the meeting, if only out of curiosity about why the pastor would want this', effects: { faith: 10 }, next: 'denis_bridgeA' },
          { label: 'Ignore the invitation as a trap or a sign of weakness', effects: { faith: -10 }, next: 'denis_bridgeB' },
        ] },
        denis_bridgeA: { text: 'Dennis came expecting an argument, a sermon, or a trap, but the pastor simply talked with him like a person, over a cup of tea — and kept inviting him back, conversation after conversation, month after month, never bringing up the subject first and never once mentioning the tattoos on his arms. After several months of these meetings the pastor invited him to an Easter service, and Dennis came along with his fiancée, ending up one of only three white people in a congregation of seventy. Listening to the congregation\'s live singing instead of the marching songs he knew, for the first time in years he felt not hatred, but a quiet, inexplicable shame.', next: 'denis_choice2' },
        denis_bridgeB: { text: 'Dennis ignored the invitation, expecting that would be the end of it. But the pastor did not back off and sent another request to meet through a mutual acquaintance — just to talk, no conditions, no recording — and in the end, more out of sheer weariness at refusing again and again than any real interest, Dennis agreed to come, just once. He showed up backed by half his group, still certain that peaceful preaching was just another kind of weakness, and that the tattoos on his arms told strangers a truer story about him than any words from some random pastor ever could.', next: 'denis_choice2' },
        denis_choice2: { text: "After almost a year of conversations kept secret from his movement comrades, Dennis stands before the pastor's congregation, people he once would have despised without a second thought and without seeing any contradiction in it, and must decide whether he is ready to publicly renounce the life to which he had given years, his reputation, and his own skin under the tattoos.", choices: [
          { label: 'Step forward and tell it all as it is, in front of everyone', effects: { faith: 15 }, next: 'denis_endLight' },
          { label: 'Leave, not ready for such a public break with the past', effects: { faith: -15 }, next: 'denis_endDark' },
        ] },
        denis_endLight: { text: 'Dennis stepped forward and told it all — who he had been and what he felt now, sparing himself nothing in the telling and not hiding the tattoos under his sleeves. "I was Grand Dragon of the Klan, and then even the Klan started to seem not hateful enough for me, so I decided to become a Nazi," he said aloud before the congregation, and by his own account half the people listening literally dropped their jaws — but not one of them said an unkind word to him after the service. He was baptized in the Atlantic Ocean to the singing of that same congregation, and his former movement comrades struck him from every list afterward as a traitor. Today he attends that very church whose members were once, for no reason but their birth, his enemies, and he is gradually having the tattoos removed, since they no longer reflect who he has become. The end of Dennis\'s story.', next: null, choices: [] },
        denis_endDark: { text: 'Dennis left that day, not ready to break with the past in front of witnesses and lose his place in the movement that gave him meaning. The pastor keeps staying close and inviting him back, but Dennis himself remains stuck between two worlds, never fully choosing either — while the movement he gave his youth to increasingly makes headlines after prominent marches like the one he once joined, losing one member after another. The end of Dennis\'s story.', next: null, choices: [] },
      },
    },
    ignat: {
      start: 'ignat_intro',
      scenes: {
        ignat_intro: { text: "Ian secretly led a small house church in a country where merely mentioning the name of Christ in front of strangers could mean a life sentence in a labor camp. His own mother had already been arrested for the same thing years earlier and had never returned; officially, her fate after the arrest was listed as \"unknown,\" even to her own family. Every meeting Ian opened and closed with the same Lord's Prayer, spoken in a barely audible whisper — the one thing that, during a sudden raid, could never be found, confiscated, or written into a report.", next: 'ignat_scene2' },
        ignat_scene2: { text: 'Meetings were held once a week, taking turns between different homes, late in the evening, curtains drawn, without a single extra candle burning. Ian knew by heart not only the texts he read aloud, but the face of every person who risked coming — knowing that if he were arrested, those same faces would be first on the investigation\'s list. For years he never told even his own children what he actually did in the evenings. Beyond the meetings themselves, he secretly carried hand-copied pages of the Bible and small parcels of spiritual literature to believers in neighboring villages, disguised as ordinary gifts — that alone would have been enough for the authorities to bring a separate charge, even without a single meeting.', next: 'ignat_choice1' },
        ignat_choice1: { text: 'Neighbors began asking questions about the people who occasionally dropped by Ian\'s house in the evenings, too regularly to be casual visitors, and one of them even complained to the local police about a "strange sect." One of those who came to the meetings turned out, later, to be an informant, reporting on every gathering in detail, including the names and faces of everyone present.', choices: [
          { label: 'Keep holding the meetings, trusting God rather than his own safety', effects: { faith: 10 }, next: 'ignat_bridgeA' },
          { label: 'Stop the meetings and lie low to protect the community', effects: { faith: -10 }, next: 'ignat_bridgeB' },
        ] },
        ignat_bridgeA: { text: 'Ian kept the meetings going, only more carefully — fewer people at a time, different times, coded phrases instead of names spoken aloud, gatherings disguised as birthday parties with a real cake on hand in case of a sudden check. Things got harder for the community, but it kept living and growing, if slower and quieter than before. Neighbors who knew him personally said later that he had a will of steel: he once refused a local official to his face who had hinted at a bribe in exchange for silence about the meetings, though that refusal alone could have cost him his freedom long before any raid.', next: 'ignat_choice2' },
        ignat_bridgeB: { text: 'Ian stopped the meetings for several months, sending everyone the same short warning. Members scattered to pray alone at home, but the bond between them that had held them together for years began quietly weakening with every week of silence. When the meetings finally resumed, the circle of trusted members was half what it had been, and the old warmth that had held the community together for years could never quite be restored.', next: 'ignat_choice2' },
        ignat_choice2: { text: "Ian is arrested anyway, at night, in a search that lasted several hours and turned the whole house upside down in front of his terrified children. The official charge sounded dry and bureaucratic: organizing an unregistered religious association with intent directed against the state — for praying and handing out Bibles in his own home. During interrogation, the investigator, in a rather friendly tone, offers him freedom in exchange for just a few names — the people who came to his house in the evenings.", choices: [
          { label: 'Stay silent, whatever the consequences', effects: { faith: 15 }, next: 'ignat_endLight' },
          { label: 'Give the names in exchange for freedom', effects: { faith: -15 }, next: 'ignat_endDark' },
        ] },
        ignat_endLight: { text: "Ian stayed silent through every interrogation the investigator threw at him, and was transferred to a special political camp from which, like his mother years before him, he was never meant to return. Officially, his fate, like hers, remained \"unknown\" to his family. But surviving members of the community and neighbors, quietly passing the story on for decades afterward, remember him as a man who never once gave up a single name and never once bowed to anyone — even facing his own death. The end of Ian's story.", next: null, choices: [] },
        ignat_endDark: { text: 'Ian gave the names and was free within a week — but every name he gave under pressure belonged to someone who had trusted him more than anyone else in the world. Freedom cost him dearly; he simply was not the only one who paid the price — those he named paid it too. Some of them managed to flee before the follow-up searches, but not all, and from that week on, faith in that part of the city grew noticeably quieter. The end of Ian\'s story.', next: null, choices: [] },
      },
    },
    artem: {
      start: 'artem_intro',
      scenes: {
        artem_intro: { text: "Arthur built a business on real-estate loans and, within a few years, became genuinely wealthy — a new house, executive-class cars, recognition in the city's business circles — until the market collapsed in a single year, taking everything he had built with it and leaving only debt with interest. By twenty-six, he and his wife owned a real-estate portfolio worth several million dollars, built entirely on borrowed money — and when the market cracked, the banks all called in their short-term loans at once, a demand almost no portfolio like his could have survived.", next: 'artem_scene2' },
        artem_scene2: { text: "In the first months after the crash, Arthur still tried to save at least part of his assets, selling off cars and watches piece by piece just to delay the inevitable reckoning with the banks. At night he recounted the same figures on paper, as if that could change an outcome that had long been obvious. Arthur and his wife signed the personal bankruptcy papers in the last days of September — a date he remembered for the rest of his life, because, in his own later words, it was the start of an entirely different story, not just the end of the old one. He later said more than once in interviews that he went from a millionaire to a bankrupt in less than a year, and it was that speed of the fall that made him doubt money could ever be built the same way he had built it before.", next: 'artem_choice1' },
        artem_choice1: { text: "The banks demanded repayment of money Arthur no longer had in any form. His wife, looking at the pile of documents on the kitchen table, asked quietly, without reproach: 'What if we started with what's actually ours — not the money?'", choices: [
          { label: 'Honestly look, for the first time, at his life without money as the measure of success', effects: { faith: 10 }, next: 'artem_bridgeA' },
          { label: 'Keep looking for a way to get the money back at any cost', effects: { faith: -10 }, next: 'artem_bridgeB' },
        ] },
        artem_bridgeA: { text: "Arthur started attending a small group at church with his wife, a place he never would have set foot in before — there they talked not about investments or recouping losses, but about what it means to trust God when there is decisively nothing left to trust. In the evenings he himself, for the first time in his life, began reading the Bible in search of answers, comparing what it said about money with everything he'd spent years learning in business school — and it was out of that comparison that his own strikingly simple plan, made of a few concrete steps, gradually took shape, rather than out of any new financial theory. He wasn't looking for another quick way to win it all back but for the plain, honest truth about money — and he found it in those same evening notes on paper where he had once just recounted hopeless figures, now gradually taking shape as a short course of a few simple lessons, which he first self-published without any publisher and then began teaching in person to a few families in his own home.", next: 'artem_choice2' },
        artem_bridgeB: { text: 'Arthur kept chasing new deals, each riskier than the last, trying to win back his losses in one lucky move. Every new attempt ended the same way — deeper in debt, with fewer options for the next step.', next: 'artem_choice2' },
        artem_choice2: { text: 'Years into painstakingly rebuilding his finances step by step, without the old shine but also without the old debts, Arthur is asked to start teaching other people what he ultimately learned about money and faith through his own bitter experience.', choices: [
          { label: 'Start teaching, beginning with the story of his own fall', effects: { faith: 15 }, next: 'artem_endLight' },
          { label: 'Refuse — the past bankruptcy is too shameful to talk about', effects: { faith: -15 }, next: 'artem_endDark' },
        ] },
        artem_endLight: { text: "Arthur started teaching — and the first story he always tells at every session remains the day the bank took everything from him except what actually mattered. Today thousands of people climb out of debt after hearing that very story first. The same course that began with a few families in his home soon led him to a local radio station that was itself on the edge of bankruptcy by then — and that modest airtime slowly grew into a daily program millions listen to today, while the company he founded names its one purpose as honest, Bible-based financial education, not getting rich quick. The end of Arthur's story.", next: null, choices: [] },
        artem_endDark: { text: "Arthur rebuilt his finances through years of hard work, but never spoke of that bankruptcy out loud even with those closest to him — it remained the one subject his household simply did not discuss. The course he might once have created and taught to other families remained someone else's idea, one he only ever read about in other people's books, while he kept sorting through the same pile of figures at the kitchen table alone. The end of Arthur's story.", next: null, choices: [] },
      },
    },
    grisha: {
      start: 'grisha_intro',
      scenes: {
        grisha_intro: { text: "By sixteen, Gregory had earned a reputation as the most dangerous teenager in the district — he had already been involved in a killing during a street fight, for which he got more than ten years in an adult penal colony, though he looked younger there than everyone else. While the investigation was still under way, he was released on bail and, just four months later, got into another fight and killed a second young man — it was that second killing that ultimately set his final sentence.", next: 'grisha_scene2' },
        grisha_scene2: { text: "Gregory spent his first years in the colony proving to everyone around him that his young age did not mean weakness — proof that cost him several fights and stints in solitary. He let no one get close, including the psychologists and counselors sent on schedule, who to him were just another case file. Inside the colony he quickly became one of the youngest gang leaders, and later got drawn into the communist ideology some of the older cellmates preached — Gregory grabbed onto any system that promised some kind of meaning and power.", next: 'grisha_choice1' },
        grisha_choice1: { text: "In the colony, a prison chaplain came every week without a single missed visit, for nearly two years straight, to the same row of cells, including Gregory's, reading a few lines from the Bible aloud through the bars each time and getting the same icy silence in return — but before leaving, he'd still leave his worn copy on the cell floor, and kept coming back no matter what the other guards said about how pointless it was.", choices: [
          { label: 'One day finally answer his question', effects: { faith: 10 }, next: 'grisha_bridgeA' },
          { label: 'Keep staying silent, as always', effects: { faith: -10 }, next: 'grisha_bridgeB' },
        ] },
        grisha_bridgeA: { text: "Gregory answered — first with one short word through the bars, then a sentence, then a whole conversation about something entirely unrelated. At night, once his cellmates were asleep, he'd secretly open the Bible the chaplain had left behind and read a few lines by the light from the corridor, then, for the first time in his life, tried saying something like a prayer — clumsily, under his breath. Months later he spoke aloud for the first time in years about the fight itself and the face of the man he'd taken from the world with a single blow. The chaplain was not surprised or judgmental about the change, just kept coming every week as before, as if it had always been meant to happen. One of those nights, left completely alone in his cell, Gregory suddenly remembered words his grandfather had once told him as a child: a day would come when no one could help him except Jesus Christ. It was then, for the first time in his life, in his own words rather than out of the book, that he cried out to God aloud.", next: 'grisha_choice2' },
        grisha_bridgeB: { text: 'Gregory kept silent for months on end, but noticed to himself that the chaplain never stopped coming despite the silence — and that persistence alone made him think harder than any words could have.', next: 'grisha_choice2' },
        grisha_choice2: { text: "Over the years that followed — across four different prisons in the country, through nearly twelve years behind bars — Gregory learned the Bible almost by heart and, more than once, sat down by the bars himself next to newly arrived, equally frightened teenagers, repeating to them, word for word, what the chaplain had once said to him. He spent nearly all of those twelve years in several maximum-security prisons, including the largest in the country, and his freedom was eventually restored by a presidential pardon. Before his release, Gregory is offered a chance to stay on at the prison church as a volunteer — to go back to the very place he once served time, but now from the other side of the bars, by choice, not by sentence, and without a single dollar of pay for the work.", choices: [
          { label: 'Stay and devote his life to those walking the path he once walked', effects: { faith: 15 }, next: 'grisha_endLight' },
          { label: 'Leave as far as possible and never look back at the prison', effects: { faith: -15 }, next: 'grisha_endDark' },
        ] },
        grisha_endLight: { text: 'Gregory stayed. More than forty years later he still comes to those same rows of cells that the chaplain once came to visit him in as a teenager — only now from the side of the bars where he himself is needed, every week without fail, decade after decade, and dozens of former inmates across the country now call him the one person who never turned away first, back when everyone else had already written them off. The end of Gregory\'s story.', next: null, choices: [] },
        grisha_endDark: { text: 'Gregory left and built a new life as far as possible from anything that reminded him of prison, including his old name and old addresses. He never spoke of the past out loud again — not with anyone, including himself before falling asleep. The end of Gregory\'s story.', next: null, choices: [] },
      },
    },
    stas: {
      start: 'stas_intro',
      scenes: {
        stas_intro: { text: 'Stanley was picked first overall in the draft and spent his early professional years on a clear path to stardom, until injuries and chronic pain led him to painkillers, and from there to alcohol and drugs. Within a few years he had lost his contract, his reputation, and nearly his whole family, and his wife, worn down by endless relapses, was seriously preparing to file for divorce.', next: 'stas_scene2' },
        stas_scene2: { text: "Rock bottom came on one particular night, when Stanley, high on a mix of drugs, showed up at his grandmother's door at two in the morning — twenty pounds thinner, hollow-eyed, hands shaking. He still remembers the look on her face in the doorway — not anger, but something far more frightening: a mix of horror and pity for a man she barely recognized. His grandmother's name was Mary, and over the following weeks she personally nursed her emaciated grandson back to health, barely leaving his side a single day, though she also set one hard condition on the spot: quit drugs immediately or find somewhere else to live.", next: 'stas_choice1' },
        stas_choice1: { text: "A few days later, having regained a little strength in his grandmother's house, Stanley relapsed again — right there under her roof. She silently waited for him to come out of the room and said only one sentence: 'I can't take this anymore' — and then issued a challenge: surrender not to another rehab program, but directly to God.", choices: [
          { label: 'Accept the challenge, however strange it sounds', effects: { faith: 10 }, next: 'stas_bridgeA' },
          { label: "Brush it off — he'll handle it himself, like always", effects: { faith: -10 }, next: 'stas_bridgeB' },
        ] },
        stas_bridgeA: { text: "Stanley accepted his grandmother's challenge, and that same night, ashamed and desperate, he seriously asked God for the first time in his life to take the addiction away entirely. He braced for the withdrawal he knew almost by heart from experience — but it never came, not that night, not the next day, not a week later, and that absence stunned and frightened him almost more than the addiction itself ever had. That same morning he opened his grandmother's Bible at random and landed on the words: 'Submit yourselves therefore to God. Resist the devil, and he will flee from you' — and it was from that very verse that he began counting the days of his sobriety. From that day he never touched drugs again, and every morning he began reading the Bible with his grandmother day after day, though years later, back in professional sports, he relapsed on alcohol a few times — and each time admitted it honestly to the press instead of hiding it.", next: 'stas_choice2' },
        stas_bridgeB: { text: "Stanley brushed off his grandmother's challenge and kept handling it himself, the way he had for years, only getting worse each time — his wife spent more and more nights at her parents' with the girls, tired of waiting for changes he promised but never actually made. One of those relapses happened right during the team's spring training camp, when Stanley simply vanished for a few days, eventually turning up at a tattoo parlor in the company of equally lost people — the coaching staff was nearly the last to find out where he was.", next: 'stas_choice2' },
        stas_choice2: { text: 'After several months of sobriety and weekly meetings at a small church support group, where the same grandmother drove him every Sunday, his wife agrees to a series of joint sessions with a family counselor — not as a formality before divorce, but as one real last chance to test whether Stanley is willing to change in practice, day by day, not just in moments of inspiration at prayer meetings.', choices: [
          { label: 'Go through counseling honestly, owning his full share of blame', effects: { faith: 15 }, next: 'stas_endLight' },
          { label: 'Go through the motions while staying the same inside', effects: { faith: -15 }, next: 'stas_endDark' },
        ] },
        stas_endLight: { text: "Stanley went through counseling honestly, admitting out loud to his wife for the first time the full extent of what he had done to the family — and in the very first session told the counselor plainly that his sobriety rested not on willpower but on a daily habit of prayer and Bible reading that he never once gave up, even after relapses. The marriage held, and a few years later he returned to professional sports a completely different man, openly and honestly talking about addiction and faith to anyone willing to listen to his story. The club later assigned him a permanent 'accountability partner' who literally lived and traveled with him through every road trip of the season, so there was always someone nearby he could confess to the moment he felt weak. Today his family has four daughters, and he says honestly that every sober day is a decision that has to be made all over again, every single morning, starting with prayer. The end of Stanley's story.", next: null, choices: [] },
        stas_endDark: { text: 'Stanley went through the motions of counseling but never really changed inside, and within a few months the old habits gradually came back. The marriage fell apart, and his daughters remembered a father who was better at talking beautifully about change on camera than making it happen at home. The end of Stanley\'s story.', next: null, choices: [] },
      },
    },
    zhenya: {
      start: 'zhenya_intro',
      scenes: {
        zhenya_intro: { text: "As a teenager, in the middle of family arguments at the dinner table, Jenny discovered that her own body was the one thing that belonged to her alone, and that it could make her feel strong and untouchable: she began counting every last calorie and losing weight, driving herself down to a dangerously low weight she hid under baggy clothes even from her parents.", next: 'zhenya_scene2' },
        zhenya_scene2: { text: "That teenage episode seemed to pass on its own: Jenny got into university with honors, became a model student, and her parents breathed a sigh of relief, deciding their daughter had simply grown out of a difficult age. But ten years later, while preparing to become a small church's pastor's wife and finishing seminary classes for future pastors' wives, the old habit came back with a vengeance — and, in her own later words, she had never felt more enslaved and, at the very same time, never more certain of her own strength. She admitted later that it was the new town and the new calling — 'a pastor's wife!' — that weighed on her more heavily than she was willing to admit even to herself, and that she stopped eating not because of any one argument but under the sheer weight of expectations landing on her all at once.", next: 'zhenya_choice1' },
        zhenya_choice1: { text: "A doctor at the hospital where she was rushed after collapsing right in the middle of helping her husband prepare Sunday's sermon told her plainly, without softening it: without treatment, her heart could stop any night. Unable to sleep through the hospital hours, Jenny finally opened her own Bible — the same one she had carried through two years of seminary classes but never finished — and started with the book of Revelation.", choices: [
          { label: 'Keep reading, even though the familiar thoughts about food never let go for a minute', effects: { faith: 10 }, next: 'zhenya_bridgeA' },
          { label: "Put the Bible down — faith definitely won't solve a problem with scales", effects: { faith: -10 }, next: 'zhenya_bridgeB' },
        ] },
        zhenya_bridgeA: { text: "Jenny finished Revelation that same night, and something inside her shifted: she suddenly saw that all these years she had clung to control over her own body as the last proof of strength — when in reality it had always been slavery, which she called strength so she would not have to admit it even to herself. In the passages about Christ standing among the lampstands, His eyes like blazing fire, and the same Christ as both Lion and Lamb holding the whole world in His hands, she felt for the first time in years not condemnation for an unfinished plate but something like words spoken straight to her: 'I love you as you are, but I won't leave you that way — I'm giving you a new start, I'm giving you a new name.' Thoughts about food and numbers did not disappear overnight, but for the first time in years Jenny stopped treating them as proof of who she was.", next: 'zhenya_choice2' },
        zhenya_bridgeB: { text: "Jenny put the Bible down without finishing it, and kept counting calories in the ward just as diligently as at home, only now secretly from the doctors and nurses, hiding leftover food in napkins under her pillow. The words about a new name and a new start that might have reached her that very night stayed unread, just more pages further on in the book.", next: 'zhenya_choice2' },
        zhenya_choice2: { text: "A year into treatment, relapses, and constant inner struggle — a year she spent either praying for the day she would be able to sit at a table without counting calories in her head, on one branch of this story, or entirely alone with her old habits, on the other — Jenny is invited to a support group where she has to honestly say what is happening inside her head, not just show the doctor a number on the scale.", choices: [
          { label: 'Tell it all, including the thoughts she is ashamed of', effects: { faith: 15 }, next: 'zhenya_endLight' },
          { label: 'Stick to vague phrases so no one sees how serious it really is', effects: { faith: -15 }, next: 'zhenya_endDark' },
        ] },
        zhenya_endLight: { text: "Jenny told it all exactly as it was, including her most shameful thoughts about food and her body, which she had never dared say aloud even to her doctors before. The illness did not retreat in a single day, and her body still carries, years later, the consequences of what she did to herself all those years — but for the first time she stopped fighting it in complete solitude, and stopped calling strength what had actually been slavery. Years later she wrote two books about it under her own name, calling things by their real names without embarrassed euphemisms, and now, together with her pastor husband, she supports women stuck where she recently was. She called the first book A New Name, echoing those very lines from Revelation read on a hospital bed, and the second, years later, A New Day, once she could finally write honestly about the relapses that kept coming back, not just about one final, complete healing. The end of Jenny's story.", next: null, choices: [] },
        zhenya_endDark: { text: "Jenny stuck to vague phrases at the meeting and left the hospital with a normal weight on paper, but the same quiet war inside her head as before. The same books she might one day have written under her own name stayed an unlived story she preferred not to talk about even with her husband. The end of Jenny's story.", next: null, choices: [] },
      },
    },
    inna: {
      start: 'inna_intro',
      scenes: {
        inna_intro: { text: 'Ivy and her husband endured five miscarriages over several years — at different stages, with different doctors and protocols, and each time hope grew thinner and more painful than the last. One of the lost pregnancies, far enough along that she could have picked a name, she privately called Scarlett — just so that child would remain in her life as something more than a date in a medical chart.', next: 'inna_scene2' },
        inna_scene2: { text: "After the second miscarriage, Ivy stopped going to her friends' children's birthday parties — not out of envy, but because smiling there had become physically unbearable. She set up the nursery several times and took it apart just as many times, packing the tiny onesies into a box on the top shelf, and eventually started keeping an open diary about it online, under her own name, with no anonymity. Every evening she reread the same verse of a psalm about tears God collects and keeps — returning to it more than any other passage in the Bible, especially on the nights when she couldn't find her own words to pray at all.", next: 'inna_choice1' },
        inna_choice1: { text: "After she published an especially raw entry about Scarlett, a friend from church, knowing all her pain without needing the words, did not say the usual 'God is in control' — she just sat down beside her on the kitchen floor and cried with her in silence, asking nothing and offering no rehearsed comfort, then quietly asked before leaving whether she could come by in the evenings just to pray together — not for a new pregnancy, but for Ivy to get through that one night.", choices: [
          { label: 'Let herself truly grieve instead of pretending to be strong', effects: { faith: 10 }, next: 'inna_bridgeA' },
          { label: 'Bury the grief deeper and pretend everything is fine', effects: { faith: -10 }, next: 'inna_bridgeB' },
        ] },
        inna_bridgeA: { text: "For the first time in years, Ivy let herself cry openly, in front of her husband and friends, without shame or apology for the tears, and agreed to those evening prayers — at first just listening to her friend pray, then a few weeks later beginning, out loud, in her own words, to name God alongside Scarlett's name with her. The grief did not shrink, but it stopped being a secret she had to carry entirely alone — and the diary she kept began to be read by hundreds of strangers carrying that exact same pain.", next: 'inna_choice2' },
        inna_bridgeB: { text: "Ivy smiled in public and kept the pain strictly to herself, telling everyone around her she had 'nearly made peace with it,' turning down the evening prayers too — though at night the pain returned, in the same box of onesies on the top shelf, and the online diary remained an unpublished draft.", next: 'inna_choice2' },
        inna_choice2: { text: 'After the fifth miscarriage and another failed protocol, the doctor states plainly, without hopeful qualifiers: a natural pregnancy is extremely unlikely. A publisher who stumbled on her diary offers to turn her private entries into a book for thousands of women with the same story — but that means telling everything, including Scarlett\'s name and those same evening prayers on the kitchen floor, not just to a small circle of friends but to complete strangers.', choices: [
          { label: 'Agree, and turn her private grief into a book for others', effects: { faith: 15 }, next: 'inna_endLight' },
          { label: "Refuse — some things are too personal for strangers' eyes", effects: { faith: -15 }, next: 'inna_endDark' },
        ] },
        inna_endLight: { text: "Ivy agreed and wrote the book, softening nothing for readers' comfort, including the chapter about Scarlett and about learning to pray again on her own kitchen floor. The book reached thousands of women, who read for the first time that grieving an unborn child is not a failure of faith but part of an honest path toward it. Today she still prays every evening with that same friend, and motherhood came not the way she had planned, but it came, truly — through adopting a child who had been left without parents. The end of Ivy's story.", next: null, choices: [] },
        inna_endDark: { text: "Ivy turned down the book, deciding that Scarlett's name and those years of loss should stay within the narrow circle of her family. The diary remained an unpublished draft on an old computer, and the bitterness of those years was something she never let herself fully work through, even with those closest to her. The end of Ivy's story.", next: null, choices: [] },
      },
    },
    karina: {
      start: 'karina_intro',
      scenes: {
        karina_intro: { text: "Carrie had worked at a strip club since she was eighteen — the money was genuinely good, far more than any ordinary job for her age, and she had long since stopped seriously asking herself how she felt about it.", next: 'karina_scene2' },
        karina_scene2: { text: 'Shifts started late in the evening and ended toward morning, and Carrie had long since learned to switch off the part of her that might feel shame — turning it on only in rare moments when she happened to catch sight of old classmates at the mall in daytime.', next: 'karina_choice1' },
        karina_choice1: { text: "A group of women from a local church began coming by the club regularly at night — not with condemnation or pamphlets about sin, but with bags of simple gifts and a note reading 'you are worth more,' addressed to each dancer by name. The woman who led the group had once danced in clubs just like it herself for six years, starting at twenty-one, until fear of the coming millennium drove her to beg God in prayer for the first time not to let her die; a year later, after finishing beauty school and leaving the industry, she walked into an ordinary church for the first time in her life and cried right at the door, giving God her whole life without holding anything back.", choices: [
          { label: 'Take the gift and at least read the note', effects: { faith: 10 }, next: 'karina_bridgeA' },
          { label: "Throw the gift away — she does not need anyone's pity", effects: { faith: -10 }, next: 'karina_bridgeB' },
        ] },
        karina_bridgeA: { text: "Carrie read the note several times that night between sets, careful not to let the other girls in the dressing room notice, and found a short link to a Bible verse at the bottom — after her shift she opened a Bible on her phone for the first time in her life, just to see what it said. That same morning, for the first time ever, she tried praying in her own words — awkwardly, with no memorized phrases, just out loud in an empty apartment. A couple of weeks later she finally texted the number at the bottom — just to find out what these women actually wanted from her and why they kept coming back to the club week after week with nothing in it for themselves. She was told the ministry had existed officially since that very Good Friday when its founder decided to name it after Christ, and that volunteers sometimes paid the club themselves for private time with the dancers — not for a show, but simply to talk without judgment and without hurry.", next: 'karina_choice2' },
        karina_bridgeB: { text: "Carrie threw the gift in the dressing room trash in front of the other girls and kept working as usual, though the short note somehow would not leave her head for several days straight. The women from the ministry kept coming back to the club every week just the same, and one evening Carrie finally couldn't help herself and spoke to one of them by the back door. The woman explained that their ministry had existed officially since that very Good Friday when its founder decided to name it after Christ, and that volunteers sometimes paid the club for private time with the dancers, but never for a show — only to talk without judgment and without hurry.", next: 'karina_choice2' },
        karina_choice2: { text: 'The ministry offers Carrie concrete help with a new profession, courses, and temporary housing while she gets on her feet — plus weekly meetings with the same group of women, where they always start by reading a few lines of the Bible together and praying before talking about work and money — but that means leaving the club immediately, without the familiar safety net of her old income, which for years had supported not just her but part of her family too.', choices: [
          { label: 'Leave now, trusting that things will somehow work out', effects: { faith: 15 }, next: 'karina_endLight' },
          { label: 'Stay — too risky to trade stable income for promises', effects: { faith: -15 }, next: 'karina_endDark' },
        ] },
        karina_endLight: { text: "Carrie left that same week, packing up her things from the dressing room in one evening without explaining anything to anyone at the club, and for a while she struggled to make ends meet on her new, far more modest salary. She never once missed one of the weekly prayer-and-Bible meetings, even in the hardest months financially — and today she herself meets other girls outside similar clubs, starting every such evening with that same short prayer in her own words that she once received herself. The end of Carrie's story.", next: null, choices: [] },
        karina_endDark: { text: 'Carrie stayed, telling herself the change could wait for a more convenient, less risky moment. That convenient moment never came on its own — the weeks quietly turned into several more years of the same life on the same terms. The end of Carrie\'s story.', next: null, choices: [] },
      },
    },
    darya: {
      start: 'darya_intro',
      scenes: {
        darya_intro: { text: 'Dana was a professional athlete at the peak of her career — medals at international competitions, endorsement deals, a recognizable face on the covers of sports magazines across the country. Underneath the camera-ready smile, she had carried a shame for twenty years that she never fully told anyone about. She had accepted Christ as her Savior back as a teenager, alone at the wheel of a car driving between two states — and for years she struggled to make peace with the fact that the very person who first talked to her about Christ that day was the one who would go on to abuse her.', next: 'darya_scene2' },
        darya_scene2: { text: 'Dana had long since mastered the art of the perfect interview — answering exactly what journalists and sponsors expected, never straying a word outside the image of the unbreakable champion. At home, behind closed doors, keeping up that role cost her sleepless nights and panic attacks before every major tournament — her body remembered that old abuse better than she was ready to admit, and any unexpected touch during training, even something perfectly ordinary, could pull her back without warning into that same childhood room from twenty years before. Only her coach knew about any of it, and even he not all of it.', next: 'darya_choice1' },
        darya_choice1: { text: 'After another major win, a journalist at the press conference unexpectedly asked, not about technique or rivals, but simply whether she was happy. Dana froze for a second in front of the cameras, not knowing whether to lie as usual or, for the first time in her career, tell the truth.', choices: [
          { label: 'Start gradually being honest, at least with herself, about her pain', effects: { faith: 10 }, next: 'darya_bridgeA' },
          { label: 'Answer with her usual practiced smile', effects: { faith: -10 }, next: 'darya_bridgeB' },
        ] },
        darya_bridgeA: { text: "'No,' Dana answered quietly into the microphone, not giving her usual practiced smile in front of the cameras for the first time in her life. 'Not really.' The room went silent for a second, and she went on to start meeting with the team chaplain once a week — at first just formally, to check a box for the coaching staff, then more and more honestly, saying out loud for the first time what she had hidden behind twenty years of success, even from herself in every locker-room mirror. The chaplain prayed with her before each of those meetings and once told her something she would repeat to herself before every race after that: God had seen her even before her first medal, and had never stopped seeing her through all those years of shame no one else knew about.", next: 'darya_choice2' },
        darya_bridgeB: { text: 'Dana answered with her usual practiced smile, polished by years of training in front of the camera no less than her technique, and went home, as always, hiding an exhaustion no one in the arena even suspected. Dana kept leaning on what she would later call the "addictive power of performance" — winning again and again was easier than stopping for even a second to say out loud what had happened to her as a teenager.', next: 'darya_choice2' },
        darya_choice2: { text: 'After retiring from competitive sport, Dana is offered a chance to write a book — not about the wins, medals, and records, but about the exact shame and emptiness that hid behind them all those years, under a coat of press-ready polish.', choices: [
          { label: 'Write it honestly, without softening anything', effects: { faith: 15 }, next: 'darya_endLight' },
          { label: 'Refuse — the image of the invincible athlete is safer than the truth', effects: { faith: -15 }, next: 'darya_endDark' },
        ] },
        darya_endLight: { text: "Dana wrote it honestly, without softening it for the sake of the invincible-champion image she had guarded for two decades. The book spread among fellow athletes across the country, many of whom learned for the first time that they were not the only ones carrying that kind of shame under their own medals and endorsement deals, hiding it as carefully as she once had. She never once skipped her weekly prayer meetings with the team chaplain — the one training routine she never gave up, even after retiring from competition. Two years after retiring, she finally began truly working through the trauma she had buried under training and trophies for two decades, and she called her book Finding My Course: A Professional Athlete's Journey Through Pain to Purpose. She later founded an initiative bearing her own name, training coaches and team chaplains to understand an athlete's trauma emotionally and spiritually, not just physically. The end of Dana's story.", next: null, choices: [] },
        darya_endDark: { text: 'Dana turned down the book, and the carefully built image of the invincible champion stayed with her forever — along with a shame that no one outside her coaching staff ever learned about. The end of Dana\'s story.', next: null, choices: [] },
      },
    },
    milana: {
      start: 'milana_intro',
      scenes: {
        milana_intro: { text: "Melanie was thirty-four, the wife of a small church's pastor and mother of four, when the doctor said the words 'stage four' after her breast cancer diagnosis — she barely remembers the rest of the conversation in that office, only staring at the desk lamp over the doctor's shoulder, counting the glints on its base. She had prayed out loud with other people's families almost every week for twenty years straight, and that evening found she could not get out a single word of prayer for herself, no matter how hard she tried.", next: 'milana_scene2' },
        milana_scene2: { text: 'Melanie rode home as usual, looking out the window at the same familiar houses, thinking the world outside looked exactly the same as yesterday, even though an earthquake had just happened inside her. After several months of treatment, still unable to pray in her own words again, she started keeping an open diary about her illness online under her own name — not for sympathy, but because she no longer had the strength to smile at her congregation and pretend everything was fine. She named the diary Mundane Faithfulness, writing in the very first entry that faith isn\'t built on rare, dramatic miracles but on what you keep doing day after day, including the hardest ordinary days.', next: 'milana_choice1' },
        milana_choice1: { text: "A nurse friend, among the first to learn the diagnosis, did not offer comfort with empty words about staying positive, but simply asked directly: 'Do you want me to come to every chemo session, just to sit next to you?' Melanie remembered that this same plain presence, without rehearsed comforting phrases, was exactly how she herself had comforted people at hospital bedsides for twenty years — and now it was her turn to receive the same thing from someone else.", choices: [
          { label: 'Agree — it is frightening to go through this alone', effects: { faith: 10 }, next: 'milana_bridgeA' },
          { label: 'Refuse — she does not want to burden anyone with her illness', effects: { faith: -10 }, next: 'milana_bridgeB' },
        ] },
        milana_bridgeA: { text: "Her friend came to every session, exactly as promised, never missing one, and between IV drips they prayed — sometimes in her friend's own words, which Melanie finally found in herself again after so many weeks of being unable to speak, sometimes just sitting in silence, holding hands under the steady hum of the machines. To Melanie's own surprise, thousands of strangers across the country started reading her diary entries about those hours.", next: 'milana_choice2' },
        milana_bridgeB: { text: 'Melanie went through the chemotherapy alone, hour after hour, under that same steady hum of machines, hiding from everyone, including herself, just how frightened she really was between the injections, and wrote in the diary less and less, crossing out the most honest paragraphs before posting.', next: 'milana_choice2' },
        milana_choice2: { text: "Once Melanie's diary became known across the country, she learns from the news about a terminally ill woman her own age who had publicly set a date to end her life under the euthanasia law. A publisher offers Melanie the chance to write that complete stranger an open letter — an invitation to coffee, not a judgment — knowing millions will inevitably read it, and that her own illness and faith will be on display for the whole country, including people who wish her ill.", choices: [
          { label: 'Write an honest open letter, whatever comes of it', effects: { faith: 15 }, next: 'milana_endLight' },
          { label: 'Stay out of it — too personal to put on public display', effects: { faith: -15 }, next: 'milana_endDark' },
        ] },
        milana_endLight: { text: "Melanie wrote the letter, inviting the stranger for a cup of coffee instead of judging her, and it spread through the national news, sparking a wave of debate across the country. A few months later the illness took its course, but Melanie kept writing her diary until the last weeks and kept praying every evening with that same short prayer she had found in herself again back then, between the IV drips — in it, peace despite fear is a choice made every day, not a one-time decision. The end of Melanie's story.", next: null, choices: [] },
        milana_endDark: { text: "Melanie stayed out of it, deciding a personal illness should not become a subject of national debate. The diary remained known only to a small circle of her congregation, and the decision never brought her peace — she went on living from scan to scan with the same quiet fear she had felt on the day of her diagnosis. The end of Melanie's story.", next: null, choices: [] },
      },
    },
    egor: {
      start: 'egor_intro',
      scenes: {
        egor_intro: { text: "George had achieved everything any athlete dreams of — deals with leading brands, national fame, his own face on posters in every sporting goods store in the country, exactly what he'd dreamed of as a boy since childhood. But every win came home to the same dull emptiness, which neither the money nor the crowds chanting his name ever filled.", next: 'egor_scene2' },
        egor_scene2: { text: "George had long since gotten used to a schedule mapped out to the minute — training, camps, interviews, more training, without a single truly free day on his calendar for years running. Free time scared him more than any opponent, because it was exactly in those pauses that the emptiness became especially hard to ignore, with nothing to distract him from it. One of his teammates, for four seasons straight, wrapped himself in a towel after every practice and, not even fully dressed yet, asked him the same blunt question every single time: 'Do you know Jesus?' — and for months George just brushed it off, until the injuries of that same fourth season began piling up one after another.", next: 'egor_choice1' },
        egor_choice1: { text: 'After a severe knee injury at the very peak of the season that nearly ended his career and required two surgeries in a row, George found himself, for the first time in years, without sport, without a schedule, without the athlete identity he was used to — just alone with himself within the four walls of a rehab ward where no one chanted his name anymore.', choices: [
          { label: 'Use this pause to honestly ask who he is without winning', effects: { faith: 10 }, next: 'egor_bridgeA' },
          { label: 'Fight with everything to get back in the game, just to avoid that question', effects: { faith: -10 }, next: 'egor_bridgeB' },
        ] },
        egor_bridgeA: { text: "Still in the ward, George was visited by that same teammate, who once again asked him directly, just as he had dozens of times before in the locker room: 'Do you know Jesus?' — and this time, without the usual noise of the crowd and training, George finally didn't brush it off. He had long noticed how this teammate treated his own wife — nothing like most of the guys in the locker room — and it was that, no less than the question itself, that made him truly listen. He started attending a small group of believing athletes his former teammate, already retired, invited him to — there people talked not about results, records, and contracts, but about what stays with a person once the results inevitably disappear along with health, youth, and contracts.", next: 'egor_choice2' },
        egor_bridgeB: { text: "George threw everything into forced rehabilitation, just to get back on the field as fast as possible and leave himself no time for uncomfortable questions. The question of who he was without sport got shelved again, as it had dozens of times before. This was not the first time it happened this way — his locker-room teammate had raised the exact same conversation season after season, and George just brushed it off year after year, preferring the silence of his headphones to any such questions.", next: 'egor_choice2' },
        egor_choice2: { text: 'Calling his wife late one evening after another group meeting, George told her honestly for the first time in his life that he was afraid of the day his career would end for good — and had to decide what to fill that emptiness with in advance, rather than wait for it to swallow him whole.', choices: [
          { label: 'Fully trust faith, not just sport, as his source of meaning', effects: { faith: 15 }, next: 'egor_endLight' },
          { label: 'Keep holding on to sport as his only anchor', effects: { faith: -15 }, next: 'egor_endDark' },
        ] },
        egor_endLight: { text: "George found in faith something that doesn't end along with a career and its contracts. When sport did end a few years later, quietly and unremarkably, the emptiness he'd feared for so many years never showed up in its usual place — instead, George enrolled in seminary and, together with his wife, started a small church community where he now serves as pastor to people just like he once was. 'For the first time in my life I feel truly loved,' he admitted to himself back then, and that feeling turned out to be sturdier than any win on the field. The community he and his wife founded grew, years later, into a church of thousands. The end of George's story.", next: null, choices: [] },
        egor_endDark: { text: 'George kept holding on to sport as his only source of meaning right up to the end of his career. When it did end, the emptiness he had spent years avoiding at any cost caught up with him at full force, leaving him nothing to fill it with. The end of George\'s story.', next: null, choices: [] },
      },
    },
    vadim: {
      start: 'vadim_intro',
      scenes: {
        vadim_intro: { text: 'Vincent received a death sentence for a murder carefully planned for money, not committed in some blackout of the mind, and spent his first years on death row hating the whole world no less than he hated himself for what he had done, refusing lawyers and appeals because he genuinely believed himself undeserving of any mercy.', next: 'vadim_scene2' },
        vadim_scene2: { text: "Vincent's cell was at the end of the corridor holding those sentenced to death — everyone knew each other by name and by the dates set in their sentences, discussing them with the same casualness people outside used to discuss the weather. Vincent had long since stopped considering himself fully alive, having crossed himself off the list of human beings well before the court did.", next: 'vadim_choice1' },
        vadim_choice1: { text: 'Before he ever first set foot on death row, the prison chaplain spent three months in prayer over whether to even seek a meeting with a condemned man he had never laid eyes on. Having made up his mind, he started coming to see Vincent every week without a single missed visit, for years on end, though Vincent silently and pointedly turned his back to the bars and stayed silent the whole visit from first minute to last, hoping the chaplain would eventually get tired of it and stop coming, as every other visitor had.', choices: [
          { label: 'On one of the visits, finally turn around and speak', effects: { faith: 10 }, next: 'vadim_bridgeA' },
          { label: 'Keep ignoring the chaplain to the very end', effects: { faith: -10 }, next: 'vadim_bridgeB' },
        ] },
        vadim_bridgeA: { text: "To his own surprise, Vincent spoke up during one of the visits, not fully understanding himself why it happened just then — and, for the first time in years, said aloud the full name of the man he had killed and the details of that night, which he had never told anyone, not even his own lawyer at the trial. The chaplain simply listened, without interrupting or flinching, and then suggested they read the Bible together, week after week, right through the bars. A few years later, Vincent was baptized right there in the prison. He began memorizing psalms by heart together with another inmate in the neighboring cell, and years later, with no one ever officially appointing him, he became something like a pastor for the whole death row block — the man the others turned to for a word of comfort before yet another execution, someone else's this time, at the end of that same corridor.", next: 'vadim_choice2' },
        vadim_bridgeB: { text: "Vincent kept silent at every weekly visit, though he himself could not fully explain why this particular chaplain, unlike every other prison staff member, never stopped coming no matter what. Years later, after he was moved to another cell down the same corridor, only the guards still remembered the chaplain who had never once gotten a word back — as a man of almost unbelievable patience.", next: 'vadim_choice2' },
        vadim_choice2: { text: "A few weeks before his scheduled execution date, once every appeal had finally been exhausted, Vincent is given an official chance to write letters — not only to the victim's family, but also to his own brother, whom he himself had once drawn into that fateful night at just fourteen years old — to say what he should have said long ago but had put off all these years out of fear, shame, and the certainty that forgiveness simply could not exist.", choices: [
          { label: 'Write honest letters with a full confession and a request for forgiveness', effects: { faith: 15 }, next: 'vadim_endLight' },
          { label: 'Not write at all — too late and too shameful', effects: { faith: -15 }, next: 'vadim_endDark' },
        ] },
        vadim_endLight: { text: "Vincent wrote both letters, putting into them a full confession without a single attempt to excuse himself — to the victim's family, asking for forgiveness, and to his own brother, taking on an older brother's guilt for failing to hold him back that night instead of going along with him. After nearly forty years on death row — one of the longest such terms in the country's history — on the day of the execution he asked for the very hymn to be sung that the chaplain had quietly sung to him every week, all those years behind bars. In his official written statement before his death, he wrote only two words — 'I am guilty' — refusing any attempt to excuse himself, and shortly before that he had himself petitioned for a review of the cases of several men on the block he believed had been wrongly convicted. The end of Vincent's story.", next: null, choices: [] },
        vadim_endDark: { text: 'Vincent never wrote the letter, putting it off until a last day that never came in time. On the day of the execution, the chaplain was still there beside him, but Vincent himself passed away without ever saying the one thing he should have said decades earlier. The other men on the block, who knew about the chaplain who had come for years without ever getting an answer, never understood what Vincent feared more — death itself, or the thought that it was now too late to ask forgiveness. The end of Vincent\'s story.', next: null, choices: [] },
      },
    },
    kostya: {
      start: 'kostya_intro',
      scenes: {
        kostya_intro: { text: "Kenneth was born with eyes that could make out only light and shadow — the outlines of the world, but not faces or letters. In a believing family, he heard his mother reading the Bible aloud and singing psalms every evening from his earliest childhood, and it was those very melodies, before anything else, that he began picking out by ear on the piano at age five, faster than his sighted peers could read the notes. Three years later he began learning music printed in raised dots, reading music with his fingertips before he could read anything else. When Kostya turned eight, his parents found him a teacher who taught not only these Braille notes but also picking out music by ear in the style of each piece — and the first pieces he learned that way were, again, his mother's psalms. From then on, improvisation became a second language for him, as natural as ordinary speech.", next: 'kostya_scene2' },
        kostya_scene2: { text: "At university, studying music therapy, Kenneth took a job working with troubled teenagers — listening to their life stories by ear and, on the spot, right there in the session, turning what he'd heard into a song he played straight from memory. Many of these kids genuinely felt lighter, knowing someone had turned their pain into a melody instead of just listening and nodding. He studied the field at a music therapy department, and for his practicum took a placement in an actual psychiatric hospital, setting patients' stories to music long before he ever performed for large concert halls.", next: 'kostya_choice1' },
        kostya_choice1: { text: 'After one such session, one of the teenagers asked him straight out: "Can you do that about your own stuff? About what you actually believe?" Kenneth realized that until then he had only been writing songs about other people\'s stories, carefully avoiding any mention on stage of his own faith — which, in those very months, was becoming more and more real to him.', choices: [
          { label: "Start writing honestly about his own faith, not just other people's stories", effects: { faith: 10 }, next: 'kostya_bridgeA' },
          { label: 'Stay in the safe role of an outside music therapist', effects: { faith: -10 }, next: 'kostya_bridgeB' },
        ] },
        kostya_bridgeA: { text: 'Kenneth tried writing his first song in his own voice right there in that same session, with no preparation and no idea what would come of it — and heard in his own voice the same relief he had seen in the teenagers after their songs. He formed a habit of quietly praying to himself every time before he sat down at the instrument, so the right words and notes would come on their own, and more and more often took as his subject not some abstract story but lines straight out of the Bible he had heard from his mother as a child. Over time, these unplanned improvisations of his own at concerts began drawing far more listeners than his carefully rehearsed numbers.', next: 'kostya_choice2' },
        kostya_bridgeB: { text: "Kenneth politely brushed off the teenager's question and stayed in his familiar, safe role — recording other people's stories by ear, saying nothing out loud about his own. Years later he sometimes regretted never finding the nerve that day to play something that was truly his own.", next: 'kostya_choice2' },
        kostya_choice2: { text: 'The organizers of a major concert tour offer Kenneth a contract built entirely around the familiar format of pre-rehearsed numbers with not a single live improvisation — predictable, safe for ticket sales, but without the one real risk: the audience hearing him live, working out the music and words on the spot, with no safety net.', choices: [
          { label: 'Insist on live improvisation in front of the audience, risking failure on stage', effects: { faith: 15 }, next: 'kostya_endLight' },
          { label: 'Agree to the safe, rehearsed format', effects: { faith: -15 }, next: 'kostya_endDark' },
        ] },
        kostya_endLight: { text: 'Kenneth insisted on live improvisation and walked on stage without a single prepared note, composing the music and words right there during the performance, opening every concert with the same quiet prayer he used in rehearsal. For more than forty years now he has toured the country in exactly this format — asking the hall, right in the middle of the performance, what to pray for, and turning those requests, on the spot and unprepared, into a song built on Bible verses — not as some curious "blind phenomenon," but as a musician for whom eyesight and the ability to truly see the person in front of him turned out to be two different things. For his encores, he still asks the audience to shout out three random words and three random notes, and weaves them into a brand-new song on the spot, never once repeating himself across decades of touring the country, Canada, and Europe. He named the recording studio he founded back in the 1980s after the burning bush, and it has more than twenty albums to its name by now, with his wife still at his side after all these years — together they raised their children. The end of Kenneth\'s story.', next: null, choices: [] },
        kostya_endDark: { text: "Kenneth agreed to the safe format with no improvisation, and the concerts always went smoothly, following the same script from city to city. He never found out what that risk he chose to turn down might have become. The end of Kenneth's story.", next: null, choices: [] },
      },
    },
    marat: {
      start: 'marat_intro',
      scenes: {
        marat_intro: { text: "Martin was one of the leaders of a mafia clan — not a gang you join, but a clan you're born into and never leave — extortion, schemes with fuel companies, other people's open fear were simply part of an ordinary work week for him for nearly two decades, and the annual turnover of the fuel schemes alone, according to later investigators' estimates, ran into the hundreds of millions.", next: 'marat_scene2' },
        marat_scene2: { text: "Martin followed in his own father's footsteps, a man who for decades had remained one of the key figures in that same organization, and from his youth he saw that path not as a choice but as something taken for granted, like a surname. By thirty-five he had already served more than one prison term and knew full well the unwritten rule of his world: you don't retire from the organization, you only leave it feet first. The one bright spot behind bars was a girl he'd met on a film set — a believer, nothing like anyone he'd known in his old life. He'd offered that same twenty-year-old dancer a role on the set of a film he was producing himself. They got married. A few years later they had children. Then Martin was arrested.", next: 'marat_choice1' },
        marat_choice1: { text: 'In a solitary cell two meters by three, where Martin spent nearly two and a half years straight, a guard once looked through the peephole and asked, "You don\'t look so good. You all right?" Martin snapped at him to go away — but a minute later the guard came back and silently pushed a Bible through the gap in the door, asking for nothing in return. Martin later called that night nearly the worst of his life — certain he was about to lose everything he cared about and would never see his wife or children again.', choices: [
          { label: 'Pick up the Bible and open it in earnest', effects: { faith: 10 }, next: 'marat_bridgeA' },
          { label: 'Throw the Bible into the corner of the cell', effects: { faith: -10 }, next: 'marat_bridgeB' },
        ] },
        marat_bridgeA: { text: 'Martin angrily hurled the Bible against the cell wall, but there was nowhere to go in solitary — and eventually, out of sheer boredom, he picked the book up off the floor and started reading. One line from Proverbs — "when a man\'s ways please the Lord, he makes even his enemies to be at peace with him" — stopped him cold, and he read it over and over. He spent the rest of his months in solitary never letting go of the Bible, and came out of it, in his own words, already a firmly believing man.', next: 'marat_choice2' },
        marat_bridgeB: { text: "Martin threw the Bible into the corner of the cell and decided he'd get by without anyone's handouts — the book lay there untouched for nearly two and a half years of solitary confinement, while thoughts he'd never noticed in himself before began coming on their own, without a single page ever opened.", next: 'marat_choice2' },
        marat_choice2: { text: "Once released, Martin has to make a decision that in his world is never made without a price: officially and openly break with the organization, knowing that his former partners, including men his own father had trusted, would see such a move as betrayal — a betrayal that carries exactly one price, regardless of past service or old ties.", choices: [
          { label: 'Break completely with the organization, whatever it costs', effects: { faith: 15 }, next: 'marat_endLight' },
          { label: 'Stay formally in the business, choosing familiar safety', effects: { faith: -15 }, next: 'marat_endDark' },
        ] },
        marat_endLight: { text: "Martin broke completely with the organization, stayed with that very believer who never once doubted him through all the years of his imprisonment, and openly, under his own name, wrote a book about his old life and his conversion. To this day he remains a rare example of someone at his level in the organization who got out of it alive and on his own feet. The end of Martin's story.", next: null, choices: [] },
        marat_endDark: { text: "Martin stayed formally tied to his old partners, choosing familiar, predictable danger over unknown freedom. That Bible was never read, and the chance he'd thrown into the corner of his solitary cell was something he later remembered more often than he cared to admit to himself. The end of Martin's story.", next: null, choices: [] },
      },
    },
    yuriy: {
      start: 'yuriy_intro',
      scenes: {
        yuriy_intro: { text: "Jordan ran a small theological seminary near the front line when the war reached his own city in a single night. The building he had spent years building as a place to train future pastors ended up inside the shelling zone, and Jordan, like most of his neighbors, lost his own home in the very first weeks. He and his colleagues had founded the seminary back in the nineties with the support of an American missionary, spending years building brick by brick the library they'd long dreamed of — and later, learning that soldiers had looted and wrecked several campus buildings, he bitterly repeated that everything they'd treasured had ended up burned, scattered, or carted away.", next: 'yuriy_scene2' },
        yuriy_scene2: { text: "Instead of getting his family out and staying somewhere safe, Jordan, together with several teachers, organized the evacuation of students and their families on rented buses, while he himself went back to the front-line areas with humanitarian aid almost every week. He kept a detailed diary of those months — not for himself, but because he felt that if it wasn't written down, what happened would be forgotten faster than it should be. Power and phone lines would go out for days at a stretch, and some of the entries later had to be reconstructed from memory by candlelight in the basement, which served at once as a bomb shelter and a makeshift classroom for the students who remained. The evacuation route stretched nearly eight hundred kilometers across half a war-torn country — all the way to a relatively calm city in the west, where Jordan brought not just students but their families and almost the entire teaching staff. The front-line areas he kept returning to with aid were, by then, considered among the most heavily mined in the world after the fighting, and he knew that risk every single time he got behind the wheel.", next: 'yuriy_choice1' },
        yuriy_choice1: { text: "In one small town under nonstop shelling, a group of teenagers who had lost their parents or been separated from them were left without a single adult willing to take responsibility for them in conditions like that. Jordan had to decide right there on the spot whether to take on the care of other people's children in the middle of active fighting.", choices: [
          { label: 'Take the teenagers under his own care, despite the risk', effects: { faith: 10 }, next: 'yuriy_bridgeA' },
          { label: 'Pass them along the volunteer chain and continue on his own route', effects: { faith: -10 }, next: 'yuriy_bridgeB' },
        ] },
        yuriy_bridgeA: { text: "Jordan took the teenagers with him, housing some of them in the surviving wing of the seminary alongside his own family. Five of them stayed in his care for years afterward, while he managed to track down and reunite nearly all the others he'd evacuated along that same route with their relatives.", next: 'yuriy_choice2' },
        yuriy_bridgeB: { text: 'Jordan handed the teenagers over to the next group of volunteers further along the evacuation route and continued on his way as planned, though the question of what became of those particular children kept him up at night for a long time afterward.', next: 'yuriy_choice2' },
        yuriy_choice2: { text: "After two years of nearly nonstop shelling, having lost his home and half of the seminary's former building, Jordan is offered grants and invitations to move the remaining students and the teaching entirely abroad, to safety — rather than continuing to teach and minister under fire on ruined home soil. And yet by then the seminary still hadn't fully stopped its classes: several dozen students kept studying in person in rented space, and another eighty remotely, from all kinds of corners of the country, some of them still dangerous.", choices: [
          { label: 'Stay and continue the ministry on the spot, despite the shelling', effects: { faith: 15 }, next: 'yuriy_endLight' },
          { label: 'Move the seminary abroad for everyone\'s safety', effects: { faith: -15 }, next: 'yuriy_endDark' },
        ] },
        yuriy_endLight: { text: "Jordan stayed and kept running the seminary right there in the ruined city, training new pastors amid sounds that had long since become a familiar background noise for everyone around. He later gathered his diary of those years into a book — not a story of victory, but an honest lament alongside questions to God with no ready answers, and an account of how the hands of strangers, people he had never met, kept turning up again and again exactly when his own strength had run out. Through it all, he never stopped living an ordinary life of faith — he threw his daughter's wedding, went to pastors' conferences to pray alongside other ministers, walked his own dog in the evenings — and it was in these simple, ordinary things that he found the strength to keep going. The end of Jordan's story.", next: null, choices: [] },
        yuriy_endDark: { text: "Jordan moved the seminary and the remaining students abroad, choosing safety over continuing to minister under fire. Classes resumed in far calmer conditions, but he admits that part of him stayed behind in that ruined city, the one he ultimately left. The end of Jordan's story.", next: null, choices: [] },
      },
    },
    olya: {
      start: 'olya_intro',
      scenes: {
        olya_intro: { text: "Olivia was seventeen — an avid horseback rider with plans for her senior year ahead of her — when, in late July, during an ordinary beach outing with friends on the Chesapeake Bay that had nothing to do with horses, she dove off a raft anchored in the water into shallows, misjudged the depth, and hit her head on the sandy bottom — in that split second her life split cleanly into before and after: she was left paralyzed from the neck down, unable even to turn her head or call for help. It was her own sister who pulled her out of the water — a crab bite on her sister's finger was the only thing that made her turn around and notice Olivia had never come back up.", next: 'olya_scene2' },
        olya_scene2: { text: "Olivia's first months in the hospital blurred into one indistinguishable day — IV drips, machines, doctors' routine phrases about a 'long road of rehabilitation' that clearly meant something else entirely. Friends visited less and less, not knowing what to say to someone who couldn't even turn her head to face them or shake an offered hand. In the darkest of those months, she more than once literally prayed for an accident or some kind of miracle to simply end her life — and years later she openly called those very desperate words to God her first truly honest prayer, not a shameful weakness to hide.", next: 'olya_choice1' },
        olya_choice1: { text: "In the hospital room, in the deepest darkness of despair, Olivia arrived at a simple and terrifying thought: if God truly did not exist, the most logical thing would be to end her own life. Lacking even the physical strength for that, she managed a short, desperate prayer toward the ceiling: 'If I can't die, show me how to live.' That question, not any ready-made answer, became the first truly honest conversation Olivia ever had with God in her whole life.", choices: [
          { label: 'Keep praying that same prayer every day, searching for an answer', effects: { faith: 10 }, next: 'olya_bridgeA' },
          { label: 'Withdraw into depression and let no one near', effects: { faith: -10 }, next: 'olya_bridgeB' },
        ] },
        olya_bridgeA: { text: "Friends and family began praying for Olivia every day, gathering at her bedside, even when she herself could barely find the strength to believe it mattered. Friends took turns reading the Psalms aloud to her, and over time she learned to turn the pages of a Bible herself using a wooden stick held between her teeth, so she could read on her own again. Gradually, step by step, the darkness began to recede — not because her body suddenly healed, but because she stopped being completely alone inside that darkness. In time she learned to hold a paintbrush in her teeth and began to paint, hour after hour, long past the point where other painters' fingers would have given out from exhaustion.", next: 'olya_choice2' },
        olya_bridgeB: { text: 'Olivia shut out everyone who tried to visit, turning to face the wall and spending her days in the dark of the room in complete, voluntary solitude, refusing any conversation about the meaning of what was happening to her.', next: 'olya_choice2' },
        olya_choice2: { text: 'Years into determined rehabilitation, Olivia is offered the chance to become a mentor for other people with disabilities — to speak openly and publicly about her paralysis as part of her own complete story, not just as a tragedy that invites pity.', choices: [
          { label: 'Agree, and turn her story into help for others', effects: { faith: 15 }, next: 'olya_endLight' },
          { label: "Refuse — she's tired of being an example for anyone else", effects: { faith: -15 }, next: 'olya_endDark' },
        ] },
        olya_endLight: { text: "Olivia agreed. She got married, kept painting with a brush held in her teeth, and about twelve years after the accident founded a ministry for people with disabilities around the world. Its wheelchair program has since delivered more than two hundred thousand refurbished wheelchairs, together with Bibles in each recipient's own language, to more than a hundred countries. She says her paralysis became the place where she came to know God as closely as she never would have on her own two feet — and today she helps not dozens but hundreds of thousands of people with disabilities find that same comfort. The end of Olivia's story.", next: null, choices: [] },
        olya_endDark: { text: 'Olivia refused and withdrew into herself completely, never finding a real answer to the one question she asked on that first terrifying night in the hospital. The years passed, and the darkness inside her never fully lifted. The end of Olivia\'s story.', next: null, choices: [] },
      },
    },
    natasha: {
      start: 'natasha_intro',
      scenes: {
        natasha_intro: { text: "Diane and her husband kept a shared journal of his illness for all three years while cancer slowly but relentlessly took his strength — recording good days and bad, medication doses, brief moments of laughter between treatments. When he finally died, she was left alone with that thick journal and an enormous, frightening question of what to do with the life that remained — a young widow at an age when almost none of her acquaintances yet knew what that was really like. Years later, those very pages would become the basis of a book, each chapter named after one of the questions to God she had been afraid to say aloud back then, even to those closest to her.", next: 'natasha_scene2' },
        natasha_scene2: { text: "She wasn't yet forty when she became a widow — an age when most of her friends were still complaining about sleepless nights with infants, not an empty side of the bed. In the first weeks after the funeral, Diane kept automatically doing many of the things she'd done for her husband — buying his favorite tea, leaving space on his side of the bed, not yet daring to change anything in the house. Widow acquaintances warned her it would pass with time, but no one could say exactly how much time that would take.", next: 'natasha_choice1' },
        natasha_choice1: { text: "Friends and relatives competed to offer different ways to cope with grief — not to dwell on the bad, to distract herself with work, to move on as quickly as possible for her own good. Diane had to decide for herself whether to listen to this entirely well-meaning advice or to grieve her own way, at her own pace. She was offered therapy, a change of scenery, any means of distraction — and none of it was wrong, but not one piece of advice answered her one real question: where was the God she had prayed to for her husband's recovery all three years, and why had that prayer, the one she had waited so long for, gone unanswered.", choices: [
          { label: 'Let herself grieve for as long as it takes, without rushing', effects: { faith: 10 }, next: 'natasha_bridgeA' },
          { label: 'Push the grief down inside and act as if she had already coped', effects: { faith: -10 }, next: 'natasha_bridgeB' },
        ] },
        natasha_bridgeA: { text: "Diane kept writing the journal, only now about her own grief instead of his illness as before. She began every entry the same way — 'Dear God' — and wrote with total honesty, without a single attempt to sound more devout than she actually felt, drawing the courage for such directness from the Psalms of David, where praise sits right alongside open complaints to God. Once a week she went to a church group for young widows just like her, and it was there, in company rather than alone at her desk, that the grief gradually became bearable. Over time, individual entries grew into chapters, and she named each one not with some pious title but with the very question to God she had once been afraid to say aloud.", next: 'natasha_choice2' },
        natasha_bridgeB: { text: 'Diane put on a careful smile in public just a month after the funeral, pretending to be coping better than she really was, though at night she cried so loudly and for so long that neighbors through the wall sometimes knocked, thinking something new had happened. The journal she and her husband had started together stayed closed on the nightstand — she could no longer make herself add even a line to it, even alone, when no one could see what her practiced smile was hiding.', next: 'natasha_choice2' },
        natasha_choice2: { text: 'Years after losing her husband, Diane is offered the chance to turn the entries from her private journal into a real book under her own name — to make something intensely intimate, written only for herself in the darkest nights, available to thousands of other young widows going through exactly the same thing right now.', choices: [
          { label: 'Publish it all, including the darkest entries', effects: { faith: 15 }, next: 'natasha_endLight' },
          { label: 'Refuse — some things should stay private', effects: { faith: -15 }, next: 'natasha_endDark' },
        ] },
        natasha_endLight: { text: "Diane published the book in full, crossing nothing out from even the hardest entries about that first year after the funeral, leaving in every 'Dear God' just as she had written it instead of smoothing it into more impersonal prose. Thousands of young widows from across the country wrote back to her that, for the first time, they felt their own grief was not something shameful to hide, but part of a shared road that did not have to be walked entirely alone, carried by that same honest prayer. She later became a speaker and the host of a podcast for young widows across the country who, like her once, had had no one to talk to that honestly. The end of Diane's story.", next: null, choices: [] },
        natasha_endDark: { text: 'Diane refused to publish the journal, leaving the worn notebooks in the back of a desk drawer. The grief remained her strictly private burden, shared with no one, for the rest of her own days. The end of Diane\'s story.', next: null, choices: [] },
      },
    },
    lena: {
      start: 'lena_intro',
      scenes: {
        lena_intro: { text: "Megan learned she was pregnant shortly after graduation, not yet twenty — instead of a joyful start to adult life, panic met her, and her first and clearest thought, even before she called the clinic, was that abortion was the only realistic option worth considering. At the appointment where her pregnancy was confirmed, the doctor immediately wrote the word 'ABORTION' across her medical chart in bold red letters, as if the decision had already been made by someone other than her.", next: 'lena_scene2' },
        lena_scene2: { text: "Megan had already scheduled the clinic appointment, but with each passing day she felt more crushed carrying the decision alone — she hadn't told her parents yet, afraid of their reaction, and each time she rehearsed the conversation in her head she understood more clearly that she wasn't ready to carry all of it by herself. The night before the appointment she barely slept, running through every possible outcome in her mind and never settling on any of them for long, and once, in the dark of the room, she tried saying a short prayer out loud, but immediately felt embarrassed and stopped mid-sentence.", next: 'lena_choice1' },
        lena_choice1: { text: 'On the day of the appointment, waiting her turn at the clinic among other equally silent women, Megan suddenly caught herself wondering whether to turn to God right there and then, not really knowing if He would even listen to someone like her, or simply to sit out the wait and get it over with, as she had planned.', choices: [
          { label: 'Pray to God right there in the waiting room, without delay', effects: { faith: 10 }, next: 'lena_bridgeA' },
          { label: "Don't get distracted, and stick to the original plan", effects: { faith: -10 }, next: 'lena_bridgeB' },
        ] },
        lena_bridgeA: { text: 'Without getting up from her chair in the waiting room, Megan mouthed silently: "God, I don\'t want to have an abortion... I\'m desperate" — and felt a presence beside her so plain, almost physical, that she rose to her feet at once and said out loud, to herself: "I choose hope." She turned around and walked out the door, never waiting for her turn to be called.', next: 'lena_choice2' },
        lena_bridgeB: { text: 'Megan brushed off the fleeting thought of prayer and sat out the wait to the end, already ready to walk into the office, but at the very last moment, standing right in front of the door, something made her turn around and leave, never doing what she had insisted on the whole way to the clinic.', next: 'lena_choice2' },
        lena_choice2: { text: "At home that same evening, her parents, learning the truth, met the news, to her surprise, not with judgment but with unconditional support, promising to walk beside her through motherhood from day one. But once word reached the community at their church, Megan had to decide whether to let the care of these, essentially, near-strangers into the most vulnerable part of her life, trusting them with the same desperation she had once spoken to God in the clinic waiting room, or to politely keep them at a distance and cope alone, as she was used to.", choices: [
          { label: 'Let the community\'s care in, even from people she barely knows', effects: { faith: 15 }, next: 'lena_endLight' },
          { label: 'Keep to herself and manage on her own strength', effects: { faith: -15 }, next: 'lena_endDark' },
        ] },
        lena_endLight: { text: 'Megan let the community\'s care into her life — women from church she barely knew by name threw her one baby shower after another and welcomed her son as part of one big family, not as fodder for gossip. Megan says that in those months, the people around her literally became "Jesus in the flesh" to her — not an abstract idea from a sermon, but the living, tangible presence of the One she had turned to in the clinic waiting room at the most desperate moment of her life. Years later she wrote an article about it herself for a Christian women\'s magazine, so other girls facing the same choice would know they don\'t have to go through it alone. The end of Megan\'s story.', next: null, choices: [] },
        lena_endDark: { text: 'Megan chose to manage on her own strength, politely but firmly declining the community\'s involvement in her life. The care she was offered remained an unrealized possibility, and she spent the first months of motherhood far more alone than she could have. The end of Megan\'s story.', next: null, choices: [] },
      },
    },
    vera: {
      start: 'vera_intro',
      scenes: {
        vera_intro: { text: "Faith started noticing worrying mix-ups with dates and the same questions repeating in her mother long before dementia was finally confirmed officially — it took nearly three years just to get an accurate diagnosis. When it finally came, Faith left her job to become her mother's primary caregiver.", next: 'vera_scene2' },
        vera_scene2: { text: "At first, an assisted-living arrangement was enough for her mother — Faith expected it would last a long while. But within six months far more help was needed: a transfer to a full-care unit, and then to a special unit for people who could no longer manage even under regular staff supervision. That same year, Faith's own blood pressure spiked and her knee started aching from the constant lifting and transferring, and soon after, doctors diagnosed her husband with Parkinson's too, so she found herself caring for two people she loved at the very same time.", next: 'vera_choice1' },
        vera_choice1: { text: 'All through those years Faith prayed for the same one thing every evening — for God to simply stop the disease — kneeling by her mother\'s bed with the very same words. When it finally became clear that this particular prayer would go unanswered, she had to decide for herself what to do with prayer going forward.', choices: [
          { label: 'Keep praying, but no longer for healing', effects: { faith: 10 }, next: 'vera_bridgeA' },
          { label: 'Stop praying altogether — since it clearly isn\'t working', effects: { faith: -10 }, next: 'vera_bridgeB' },
        ] },
        vera_bridgeA: { text: 'Faith started attending a weekly Tuesday Bible study and a support group for married couples at her church — simply so as not to go through this alone. There she gradually learned to notice what she herself came to call "moments of grace": the fact that even having lost almost everything else, her mother had never lost her old sense of humor — and Faith began to consider these small things no less a real answer from God than the healing she had originally asked for. One such moment happened at a distant relative\'s funeral: her mother first mistook Faith for a cousin, then a minute later looked at her more closely and said, "I\'m so glad to know you\'re my daughter — I always liked you."', next: 'vera_choice2' },
        vera_bridgeB: { text: "Faith stopped praying altogether, deciding that since her main request had gone unanswered, there was simply no point continuing the conversation. Caring for her mother didn't get any easier for it — faith itself simply stopped being any kind of support in exactly the months she needed it most, and she now spent her long shifts in the full-care unit in complete silence, no longer finding words even for herself.", next: 'vera_choice2' },
        vera_choice2: { text: 'Going through her mother\'s old things, back when she could still occasionally manage a few written words, Faith found a card, begun but never sent — a few phrases in an already unsteady hand: "You are a special daughter. I love you so much. Thank God for giving you to me" — written before almost all her other words had slipped away. She had to decide whether to keep this discovery to herself or tell other caregivers going through the very same thing.', choices: [
          { label: 'Tell other caregivers about this discovery', effects: { faith: 15 }, next: 'vera_endLight' },
          { label: 'Keep the discovery to herself', effects: { faith: -15 }, next: 'vera_endDark' },
        ] },
        vera_endLight: { text: 'Faith told her support group about the card she\'d found, then posted her whole story on a Christian platform where people share real testimonies — honestly, including the years of unanswered prayer for a healing that never came. Other caregivers looking after parents with dementia later wrote to her that her words about "moments of grace" were the first thing that helped them stop experiencing what was happening as God having abandoned them. To this day she tells herself and others: she never did learn why God didn\'t stop the disease, but she knows for certain that the whole story rests entirely in His hands. The end of Faith\'s story.', next: null, choices: [] },
        vera_endDark: { text: 'Faith kept the discovery to herself, never sharing it with anyone. Years later, looking back on that time, what she regretted was not the caregiving itself, but precisely the silence in which she was left alone with her lost faith back then, never once looking into a church support group again. The end of Faith\'s story.', next: null, choices: [] },
      },
    },
    alya: {
      start: 'alya_intro',
      scenes: {
        alya_intro: { text: 'Since she was thirteen, with no single clear cause she could ever point to, Alyssa had been hit from time to time by panic attacks so severe that more than once she hid from classmates in a school bathroom stall, afraid someone would hear her shaking. Years later, already a famous performer with millions of streams, she still hid these attacks from almost everyone around her — the same panic that had come at thirteen was waiting for her backstage at literally every concert. Back then, as a teenager, the attacks were not just fear but genuine physical pain too — cramps low in her stomach and nausea — and it was in that very school stall that she first started not just hiding but whispering, barely audible even to herself, asking God for help.', next: 'alya_scene2' },
        alya_scene2: { text: "Her team and managers knew Alyssa as a composed, steady artist who could keep her face together in front of any camera — only a handful of people knew about the panic that sometimes literally paralyzed her right before walking on stage. What scared Alyssa was not so much the condition itself as the thought that admitting it publicly would destroy the image she had spent years building. Even those closest to her didn't immediately know that before every concert, in the dressing room, she closes her eyes for a moment and doesn't just breathe but actually prays, before walking out to the audience as that same confident performer everyone was used to seeing.", next: 'alya_choice1' },
        alya_choice1: { text: 'One day, after an especially bad attack right before a show, Alyssa tried pouring what she was feeling straight into the lyrics of a new song, without smoothing over or softening a single line — and had to decide whether to leave that draft in a drawer or actually offer it to her producer for the new album.', choices: [
          { label: 'Offer the song as it is, without prettying it up', effects: { faith: 10 }, next: 'alya_bridgeA' },
          { label: 'Hide the draft and write something safer instead', effects: { faith: -10 }, next: 'alya_bridgeB' },
        ] },
        alya_bridgeA: { text: "Alyssa gave the producer the song exactly as it came out in that moment of panic — about needing God right now, not someday later when things get easier. It came out as a single, hit the top of the charts, and sold a quarter of a million copies — and with it, for the first time publicly, people learned what Alyssa had actually been going through backstage for more than ten years. She said afterward that for her the song wasn't a complaint but an almost shouted-out prayer — a way to reconnect directly with God in the middle of a crisis that, she's convinced, catches up with everyone sooner or later. The song was nominated for an award as best Christian song of the year.", next: 'alya_choice2' },
        alya_bridgeB: { text: 'Alyssa hid the honest draft in a drawer and wrote something safer and more predictable for the album instead, without a single hint of the panic that still caught up with her before every concert.', next: 'alya_choice2' },
        alya_choice2: { text: 'Years later — on one branch of this story thanks to the unexpected success of that brutally honest song that became a single, on the other simply because the panic backstage never let go of her and eventually became known against her will, despite all the safer lyrics since — journalists one after another began asking Alyssa directly whether she was managing with prayer alone or had also seen doctors, a question she had never had to answer out loud before.', choices: [
          { label: 'Answer honestly: prayer, therapy, and medication together', effects: { faith: 15 }, next: 'alya_endLight' },
          { label: 'Dodge the question, leaving things as they are, with faith as the only story', effects: { faith: -15 }, next: 'alya_endDark' },
        ] },
        alya_endLight: { text: "Alyssa answered honestly: prayer and faith gave her a community and a framework of meaning, but what actually helped her cope were therapy and medication prescribed by a doctor too — and one does not replace the other. Instead of destroying her image, as she had feared, that admission made her a voice for thousands of fans who, for the first time, heard a famous person say you can sincerely believe in God and still get honest treatment. Later she wrote a memoir about her own path — about panic, about faith, and about a marriage that nearly fell apart but was restored — and named it after that same line as the honest song. The end of Alyssa's story.", next: null, choices: [] },
        alya_endDark: { text: "Alyssa dodged the direct question, choosing to leave her public image as it was — faith as the only explanation, without a single word about doctors or medication. The panic attacks never went away over the years, and the honest conversation about them never happened. The end of Alyssa's story.", next: null, choices: [] },
      },
    },
    nina: {
      start: 'nina_intro',
      scenes: {
        nina_intro: { text: "As an infant Nadine had polio, which doctors initially failed to diagnose correctly, and she spent roughly ten years of her childhood in total shuttling between a hospital ward and home, relearning to walk — but, to the doctors' own surprise, she recovered so well that for decades she barely thought about it, until, in adulthood, pain and weakness in those same muscles began coming back, this time with no hope of a new recovery. Post-polio syndrome, as doctors eventually called it, meant that a body which had once already won this battle was now slowly losing it all over again — and the doctors warned her outright that, over time, she risked becoming fully paralyzed.", next: 'nina_scene2' },
        nina_scene2: { text: "Outwardly Nadine barely changed for years, which made it only harder to explain her growing fatigue and pain to acquaintances and coworkers — from the outside she looked perfectly healthy, so to many her complaints sounded exaggerated. At night, when the pain in her muscles kept sleep away, she often dreamed of a completely healthy body, and every morning's waking brought her right back to the same old exhaustion.", next: 'nina_choice1' },
        nina_choice1: { text: "For years Nadine begged God to extend and increase what strength she still had left — praying that He would stop, or at least slow, the decline — and again and again she woke up in the very same body, not a healed one. She had to decide for herself what to do with this prayer going forward, since the answer clearly wasn't coming the way she had asked for it.", choices: [
          { label: 'Keep praying, even as her body stays the same', effects: { faith: 10 }, next: 'nina_bridgeA' },
          { label: 'Stop praying, disillusioned by the lack of an answer', effects: { faith: -10 }, next: 'nina_bridgeB' },
        ] },
        nina_bridgeA: { text: "Nadine kept praying, even though her body stayed the same year after year. Gradually the prayer stopped being a request for healing and became simply a conversation with God about how to live one more day with the pain, rather than in spite of it — she calls it not a change in her body, but a change in the question 'why' itself.", next: 'nina_choice2' },
        nina_bridgeB: { text: 'Nadine stopped praying altogether, worn out from repeating a request that brought no answer year after year. The pain itself grew neither stronger nor weaker from this — she simply no longer had anyone to share it with, even in her own mind, and the growing muscle weakness the doctors had warned her about now greeted her every morning in complete silence, without a single word directed at the sky.', next: 'nina_choice2' },
        nina_choice2: { text: 'Years into living with the progressive illness, Nadine is offered the chance to write a book — not about the healing that never came, but specifically about the honest, unanswered questions to God inside prolonged suffering — under her own name, without softening anything, from the very first bout of her childhood illness right up to today.', choices: [
          { label: 'Agree and write the book, even though her body was never healed', effects: { faith: 15 }, next: 'nina_endLight' },
          { label: 'Refuse — she barely has strength for herself, let alone others', effects: { faith: -15 }, next: 'nina_endDark' },
        ] },
        nina_endLight: { text: "Nadine agreed and wrote the memoir about unanswered questions inside a long illness, calling it 'Walking Through Fire.' Her body remained sick, the pain and weakness never went away, but she says she found something that turned out to matter more than healing itself — that a Christian's hope rests not on a guaranteed outcome of prayer, but on the character of the One she prays to. Thousands of readers with invisible chronic illnesses later wrote to her that, for the first time, they didn't feel alone inside their pain. The end of Nadine's story.", next: null, choices: [] },
        nina_endDark: { text: "Nadine refused, deciding she barely had the strength for herself. She kept coping alone, convinced that prayers left unanswered for so many years weren't worth repeating again. The end of Nadine's story.", next: null, choices: [] },
      },
    },
    lyuda: {
      start: 'lyuda_intro',
      scenes: {
        lyuda_intro: { text: "Linda adopted twin boys, Matthew and Daniel, when they were very small, and learned both boys were autistic when they were three, before either of them had ever once called her Mom — the speech therapist stated the diagnosis in an even voice for both brothers at once, while Linda stared at two identical children's chairs in the corner of the office, feeling the picture of their future family she had imagined while bringing both babies home collapse. Later, a second diagnosis was added for both sons — fetal alcohol spectrum disorder, a consequence from before their adoption — so Linda found herself raising two overlapping diagnoses inside two small bodies at once. The doctors warned her right away: each brother's development could go in a completely different direction, and the same methods that worked for one might well not work for the other.", next: 'lyuda_scene2' },
        lyuda_scene2: { text: "In the first year after the double diagnosis, Linda went through seven specialists looking for even one who would say they were wrong about at least one of the brothers, and started a single thick notebook for both sons, where she wrote down every new word either of them said — afraid she'd forget, and between the two of them there were too few words to afford forgetting even one.", next: 'lyuda_choice1' },
        lyuda_choice1: { text: 'At the playground in the park, other mothers would look away and quietly steer their kids aside the moment one brother started rocking and screaming through a meltdown, and the other echoed the scream right after him — something only Linda herself really knew how to handle, and even she not always.', choices: [
          { label: "Keep going to the playground despite everyone's stares", effects: { faith: 10 }, next: 'lyuda_bridgeA' },
          { label: 'Stop leaving the house to avoid the judgment', effects: { faith: -10 }, next: 'lyuda_bridgeB' },
        ] },
        lyuda_bridgeA: { text: 'Linda kept going to that same playground every day, praying briefly to herself before opening the building\'s door — for each son by name, separately, not one shared prayer for both, first for one, then going back for the other, because handling both of them in public at once was even harder. On the hardest evenings she repeated the same Bible verse from a psalm to herself — that both boys had been wonderfully made by God even in the womb, whatever words the doctors used for it. Half a year later, one mother, Susan, turned out not to look away like the rest, but came closer instead and simply asked: "What can I do to help right now, with both of them at once?"', next: 'lyuda_choice2' },
        lyuda_bridgeB: { text: "Linda stopped leaving the house for almost a year, taking both boys out only by car late in the evening, once the playgrounds were already empty. The loneliness of those months turned out heavier than the diagnosis itself — heavier even than any of the stares she'd been hiding from, and her rare thoughts of prayer stayed unfinished, since she couldn't find the strength to complete even a silent sentence, locked behind that same front door.", next: 'lyuda_choice2' },
        lyuda_choice2: { text: 'The pastor of their church offers to help Linda organize a special Sunday service for families with children with developmental differences — with dimmed lights, quiet music, and a place where both her sons could come exactly as they are, in full view of the whole congregation.', choices: [
          { label: 'Agree and bring her story into the light', effects: { faith: 15 }, next: 'lyuda_endLight' },
          { label: 'Refuse — too many years spent hiding her sons to suddenly show them publicly', effects: { faith: -15 }, next: 'lyuda_endDark' },
        ] },
        lyuda_endLight: { text: "Linda agreed. The service she helped create gathered more than thirty families in its first year, each of whom had spent years hiding at home just as she once had with Matthew and Daniel. Years later, both sons, now grown, found a permanent place for themselves in that same congregation — one greets people at the door before the service, the other helps with the sound system — and both, each in his own way, turned out to be needed by the church far more than anyone could have imagined in the speech therapist's office when they were three. The end of Linda's story.", next: null, choices: [] },
        lyuda_endDark: { text: "Linda refused, frightened of showing her sons in front of the whole congregation. She kept raising both boys apart from everyone, and the notebook with their first words stayed sitting in the desk drawer, never finished — years later she admitted that what she still regretted was not the boys' double diagnosis itself, but the years she spent hiding both of them from people who might well have accepted them exactly as they were. The end of Linda's story.", next: null, choices: [] },
      },
    },
    andrey: {
      start: 'andrey_intro',
      scenes: {
        andrey_intro: { text: "Andrew founded and led an underground Christian seminar for young people in a country where the mere existence of such a group meant a real sentence in the labor camps — the idea seemed important enough to him that he knowingly took the risk, even though he could have lived a perfectly calm, unnoticed life instead. The seminar he brought together united Catholics, Baptists, and Orthodox believers — a rare thing in those days — and grew into a network that thousands of young people across the country passed through over the years. The secret police watched him for months through informants before raiding his home at dawn and confiscating every religious book they found in the house.", next: 'andrey_scene2' },
        andrey_scene2: { text: 'The seminar met every two weeks in different apartments across the city, disguised as birthdays or ordinary get-togethers — Andrew memorized entire chapters of Scripture by heart, since keeping printed copies at home would have been direct evidence in a search. By twenty-five he had already grown used to living with the constant sense that any new acquaintance might turn out to be an informant, and that the apartment phone was being tapped.', next: 'andrey_choice1' },
        andrey_choice1: { text: 'During interrogation after the raid, the investigator, in a fairly businesslike tone, offered Andrew immediate freedom in exchange for signing an official renunciation of the organization — one simple signature on a ready-made text instead of long years in a camp.', choices: [
          { label: 'Refuse to sign, whatever the consequences', effects: { faith: 10 }, next: 'andrey_bridgeA' },
          { label: 'Sign, deciding freedom matters more than principle', effects: { faith: -10 }, next: 'andrey_bridgeB' },
        ] },
        andrey_bridgeA: { text: 'Andrew refused to sign anything. He got nine years — a special-regime camp the prisoners themselves called the death camp. After the camp came exile. And after his release, constant surveillance. In the camp he went on hunger strike several times to protest the conditions, and one of them stretched, in total and in stages, to nearly two years — over a single demand: that he be allowed to keep a Bible and prayer book in his cell. He also secretly gathered other prisoners around him for group prayer, making everyone get up off their bunks, because before God, he said, a person ought to stand, not lie down — and against every logic of caution he kept holding the same quiet conversations about faith, now with fellow prisoners in the barracks.', next: 'andrey_choice2' },
        andrey_bridgeB: { text: "Andrew signed the renunciation and walked free that same day on a signed statement, but the feeling that he had betrayed not just the organization and his comrades, but himself, stayed with him far longer than the full sentence would have lasted. Afterward he often found himself regretting not the freedom he'd gained, but the hunger strike he never declared — the one that might have won him at least a Bible back, but that he was too afraid to start a second time in his life.", next: 'andrey_choice2' },
        andrey_choice2: { text: 'After release, trusted contacts offer Andrew a choice — secretly leave the country, where he would certainly be persecuted again at the first opportunity, or stay and keep helping people just like himself back in the camps.', choices: [
          { label: 'Stay and keep fighting for those currently in the camps', effects: { faith: 15 }, next: 'andrey_endLight' },
          { label: 'Leave and put the fight behind him for a peaceful life', effects: { faith: -15 }, next: 'andrey_endDark' },
        ] },
        andrey_endLight: { text: "Andrew stayed and devoted the following decades to helping those who had gone through the camps just as he had — openly gathering aid for prisoners of conscience broken in body and spirit across the country, and pushing for official recognition of the crimes of a system that had once taken nine years of his life. He was eventually freed from the camp thanks to direct diplomatic pressure from Western leaders on the Soviet leadership — the very international attention he had never once seen inside his solitary cell, but which, it turned out, the whole world had known about. The end of Andrew's story.", next: null, choices: [] },
        andrey_endDark: { text: "Andrew secretly left the country, choosing personal peace over continuing a dangerous fight. He genuinely found peace in his new home, but along with it came a question he never honestly asked himself for the rest of his life: how many more times would he have been willing to sign anything for his own freedom. The thought that the same international pressure would have freed people like him anyway, without a single signed renunciation, haunted him every time he saw those years mentioned in the news. The end of Andrew's story.", next: null, choices: [] },
      },
    },
    gleb: {
      start: 'gleb_intro',
      scenes: {
        gleb_intro: { text: "Glen was the guitarist of a cult rock band at the very peak of world fame — platinum albums, packed stadiums on multiple continents, millions of devoted fans worldwide, and methamphetamine, without a regular dose of which he could no longer physically walk onstage for the next show. He wrote some of the band's most recognizable riffs in years when a dose before the show was as routine a part of getting ready as tuning his guitar.", next: 'gleb_scene2' },
        gleb_scene2: { text: "Between tours, Glen saw his daughter from his first marriage at most once every few months, usually squeezed between interviews and soundchecks — and each time noticed her growing older and less familiar, and himself becoming a stranger to her behind the dressing-room glass. He remembered her as a toddler, and now in the photos people sent him he saw an almost unrecognizable school-age girl — he couldn't pinpoint when exactly that leap had happened.", next: 'gleb_choice1' },
        gleb_choice1: { text: "The daughter he saw so rarely once asked over the phone, in a completely childlike, defenseless voice: 'Dad, do you still love me?' — and something in that simple question instantly broke through the armor Glen had been methodically building over years on tour.", choices: [
          { label: 'Honestly ask for help for the first time, instead of coping alone', effects: { faith: 10 }, next: 'gleb_bridgeA' },
          { label: "Brush it off and write his daughter's question off as childish anxiety", effects: { faith: -10 }, next: 'gleb_bridgeB' },
        ] },
        gleb_bridgeA: { text: "On his knees right there in a hotel room, in some city on yet another tour stop, seriously for the first time in his life, Glen asked God, if He even existed, to take the addiction away entirely — and felt a change so real and instant that by the very next day he had quit every drug completely, without a single withdrawal symptom, something no doctor, therapist, or expensive rehab clinic had ever managed to achieve. He couldn't sleep that night — instead he read the room's Bible until morning, as hungrily as if it had been written for him personally, though he'd never finished a single chapter of it before in his life. That same night one simple thought struck him especially hard, repeating again and again in the text: that he remained a beloved son, not a debtor who still had to earn forgiveness through years of good behavior — and that this was exactly how, asking nothing in return, he himself had once loved his own small daughter, no matter what she'd done that day. He suddenly saw his own addiction and years of self-destruction not as a sentence with no chance of appeal, but simply as a stretch of road already behind him, one God had no intention of holding against him forever — and it was that, not fear of punishment, that made him decide firmly the next morning that his old life was over.", next: 'gleb_choice2' },
        gleb_bridgeB: { text: "Glen irritably brushed off the question and went back to the next show as if nothing had happened, though his daughter's childlike voice kept sounding in his head every time he reached for another dose before walking onstage. He tried on his own, without telling anyone, to cut back before especially important shows — and relapsed every time by mid-tour, telling himself it was just tour stress, not the fact that he'd long since stopped running his own life.", next: 'gleb_choice2' },
        gleb_choice2: { text: "The band is preparing for a massive new world tour that will bring everyone in it more millions, but will inevitably mean going back to the same exhausting life on the road. Glen has to decide right now whether to go with them this time.", choices: [
          { label: 'Leave the band for his daughter and a new life', effects: { faith: 15 }, next: 'gleb_endLight' },
          { label: 'Go on tour, telling himself this time will be different', effects: { faith: -15 }, next: 'gleb_endDark' },
        ] },
        gleb_endLight: { text: "Glen left the band for good, right at the peak of its success, despite protests from management, the record label, and millions of fans worldwide. The press and some critics called it the end of a promising career, but for his daughter it became the beginning of something far more important than any career — a father who was finally there for good, not just squeezed in between tours. The end of Glen's story.", next: null, choices: [] },
        gleb_endDark: { text: "Glen went on tour anyway, telling himself he could keep the addiction under control differently this time. By the middle of the tour, everything was back to where it had been — including the same dose before walking onstage, and the same question from his daughter on the phone, still left without an honest answer. The albums kept selling by the millions, the stadiums kept filling up, and the conversations with his daughter kept getting shorter and more routine, until they'd shrunk to little more than a dutiful 'how's school' between calls from his manager. The end of Glen's story.", next: null, choices: [] },
      },
    },
    oleg: {
      start: 'oleg_intro',
      scenes: {
        oleg_intro: { text: 'Oliver lost three people at once — his wife, his young daughter, and his own mother — when a drunk driver in the oncoming lane slammed into the car carrying his whole family. Oliver himself and the surviving children survived with severe injuries, but the car with four generations of family inside it no longer existed, and neither did the life he had planned to go on living.', next: 'oleg_scene2' },
        oleg_scene2: { text: 'In the first weeks after the crash, Oliver, on crutches and still in a cast, walked through a house crammed full of the belongings of the three who had died at once — his daughter\'s crib, his mother\'s Bible on the kitchen table, his wife\'s jewelry in a box he couldn\'t bring himself to open. Friends and coworkers no longer knew what to even say to him besides a dry "hang in there," and gradually started visiting less and less. The driver of the oncoming car, as it later came out in court, had driven drunk before, not for the first time in his life — but Oliver learned that only much later, while still lying in a hospital bed next to his surviving children.', next: 'oleg_choice1' },
        oleg_choice1: { text: "A psychologist he knew gently offered Oliver a simple idea that, in his state, was terrifying: grief on this scale can't be quickly overcome or neatly sidestepped — you have to go all the way into it, or it will grow even larger from the inside.", choices: [
          { label: 'Enter that grief for real, however enormous it is', effects: { faith: 10 }, next: 'oleg_bridgeA' },
          { label: 'Keep the grief at a distance, staying busy with tasks', effects: { faith: -10 }, next: 'oleg_bridgeB' },
        ] },
        oleg_bridgeA: { text: 'Oliver let himself grieve for real, without setting himself any deadline for when it had to end — he cried in front of his surviving children without hiding his tears, and gradually began writing down what he learned each day about a loss of this size, things no one could have explained to him beforehand.', next: 'oleg_choice2' },
        oleg_bridgeB: { text: 'Oliver threw himself headlong into tasks — fixing the car, sorting through paperwork, going back to work early — filling every free minute with something to do, anything rather than being left alone with the silence where three familiar voices used to sound at once.', next: 'oleg_choice2' },
        oleg_choice2: { text: 'Years after the crash, now raising the surviving children alone and having completed a theological education, Oliver is offered a chance to write a book about what he went through — honestly, including the months when he was certain joy would never return to his life in any form, and including his anger at the driver who survived that night. Years later Oliver taught theology at a university, and students repeatedly voted his course the most important of their entire studies — though he himself honestly admitted that not one lecture he had ever given had fully explained why that grief had to happen at all.', choices: [
          { label: "Write the book without softening anything for the reader's comfort", effects: { faith: 15 }, next: 'oleg_endLight' },
          { label: 'Refuse — too personal to put in front of the public', effects: { faith: -15 }, next: 'oleg_endDark' },
        ] },
        oleg_endLight: { text: 'Oliver wrote the book without embellishment, honestly naming the grief from that crash for what it was — a catastrophe that had struck three generations of his family at once, not merely a hardship to be quietly "accepted in peace." He came to assert something that surprised many readers: the soul can actually grow through a loss like this, not only in spite of it — and that admission helped thousands of people who had lived through their own catastrophes stop being ashamed that grief doesn\'t run on a schedule. At trial, that same drunk driver was ultimately acquitted on a legal technicality, and living on with that fact turned out to be almost harder than the crash itself. It was then, in prayer, that Oliver arrived at a conclusion he would go on repeating for years afterward: forgiveness isn\'t a single decisive act, but a long, sometimes agonizingly slow process you have to live through all over again every time the pain comes back. The end of Oliver\'s story.', next: null, choices: [] },
        oleg_endDark: { text: "Oliver turned down the book and kept filling his days with tasks, never once stopping to truly live through what had happened. Years later his children noticed their father could talk about anything at all except the one single day that had actually shaped the rest of their lives. That same drunk driver, ultimately acquitted at trial on a legal technicality, remained for Oliver an unclosed, festering wound he preferred never to approach at all, rather than a subject for honest conversation even with himself. The end of Oliver's story.", next: null, choices: [] },
      },
    },
    kirill: {
      start: 'kirill_intro',
      scenes: {
        kirill_intro: { text: 'Carl was a successful businessman with an impeccable reputation on paper, and a bottle he could no longer make it to lunch without. When alcohol finally got the upper hand over his business and his family, he traveled across the ocean for treatment with one of the most famous psychiatrists of the era, spending nearly a year of his life and a small fortune on the course of therapy.', next: 'kirill_scene2' },
        kirill_scene2: { text: 'A year of treatment brought temporary relief, but just a few months after coming home, Carl started drinking again, worse than before, and went back to see the same doctor a second time, expecting a new program or a new medication. Instead, the celebrated psychiatrist told him something Carl never expected to hear from a man of science: medicine had exhausted its options, and the only chance left was a genuine spiritual conversion, which, on rare occasions, completely turns around hopeless cases exactly like his.', next: 'kirill_choice1' },
        kirill_choice1: { text: 'Coming home with this unexpected diagnosis from a materialist doctor, Carl learned of a small Christian lay group where people openly, out loud, in front of witnesses, confessed their own sins and weaknesses and tried in practice to make right the harm they had done to those close to them. The group insisted that every member measure their life daily against four absolute standards — complete honesty, complete purity, complete unselfishness, and complete love — rather than just remembering faith now and then in passing.', choices: [
          { label: 'Go to a meeting of the group, however frightening open confession feels', effects: { faith: 10 }, next: 'kirill_bridgeA' },
          { label: 'Dismiss the idea as ridiculous amateur theatrics', effects: { faith: -10 }, next: 'kirill_bridgeB' },
        ] },
        kirill_bridgeA: { text: 'Carl came to a meeting of the group and followed their process in full, however strange it sounded for a man of his standing: he fully surrendered his will to God, admitting out loud that he could not manage on his own; he wrote out a merciless, honest list of his own sins and weaknesses, without softening a single one; he spoke that list aloud in front of witnesses, not just in silence with himself; and he began, one by one, making right the wrongs he had done to specific people during his years of drinking — with money, with apologies, with his time. It was through this, not through willpower alone, that the craving for alcohol that had tormented him for years began to weaken, day after day. He would later call it a genuine spiritual conversion — a deep, real change, not the temporary relief of another round of treatment.', next: 'kirill_choice2' },
        kirill_bridgeB: { text: 'Carl dismissed the suggestion and chose to trust in science and his own willpower alone, though neither one ever helped him stay sober more than a few weeks at a stretch. He kept remembering the psychiatrist\'s words about spiritual conversion, but each time convinced himself that such religiosity was mere superstition, unworthy of a serious, rational man of his caliber, and went back to the bottle every time things got genuinely hard.', next: 'kirill_choice2' },
        kirill_choice2: { text: "Years after that choice, one of Carl's own acquaintances from his old life reaches out to him — a man just as successful, and just as secretly drinking — with a direct question: would Carl agree to tell him, specifically him, openly and in front of witnesses, the whole story of his own fall, and whether anything had truly helped, without a single detail softened.", choices: [
          { label: 'Tell it exactly as it happened, without embellishment, in person and openly', effects: { faith: 15 }, next: 'kirill_endLight' },
          { label: 'Get by with vague generalities, so as not to stir up the past', effects: { faith: -15 }, next: 'kirill_endDark' },
        ] },
        kirill_endLight: { text: "Carl told it exactly as it happened, softening nothing, and that conversation became one link in a chain of similarly candid conversations between men like them, which years later helped lay the groundwork for an entire mutual-help movement for people struggling with addiction — one known worldwide today. The end of Carl's story.", next: null, choices: [] },
        kirill_endDark: { text: "Carl got by with vague generalities and never worked up the nerve to tell his acquaintance the whole truth about his own fall and about what had actually helped, or hadn't. A chance that might have helped one more person passed by, remaining nothing more than a polite conversation behind a closed office door. The end of Carl's story.", next: null, choices: [] },
      },
    },
    vlad: {
      start: 'vlad_intro',
      scenes: {
        vlad_intro: { text: "Walter was sentenced to death for a double murder he never committed — the prosecution's only substantial evidence was ballistics experts who claimed the bullets from the crime scene had been fired from an old revolver found in his own mother's closet, even though that revolver hadn't been fired in years and had long been broken. Before the trial, Walter had even passed a police polygraph confirming his innocence, but the judge refused to admit the results into the case, and the public defender, wrongly assuming there was no money to be found for a competent ballistics expert, hired a man who admitted at trial he didn't even know how to operate the equipment needed to analyze bullets.", next: 'vlad_scene2' },
        vlad_scene2: { text: 'Walter spent his first three years on death row in almost total, agonizing silence, choking on hatred for everyone connected to his case, including himself for failing to prove the obvious. He heard his neighbors down death row executed one after another, and understood that, on paper, he was condemned exactly like they were, despite being completely innocent.', next: 'vlad_choice1' },
        vlad_choice1: { text: 'In his fourth year of imprisonment, Walter decided: either this hatred would eventually kill the last living thing in him, or he would find a way to survive inside his own mind, without waiting for the outcome of appeals that had dragged on for years without a single change.', choices: [
          { label: 'Let something besides hatred into his cell and his mind', effects: { faith: 10 }, next: 'vlad_bridgeA' },
          { label: 'Stay locked in fury and share it with no one', effects: { faith: -10 }, next: 'vlad_bridgeB' },
        ] },
        vlad_bridgeA: { text: 'Walter remembered words his mother had told him as a child: "God can do anything except fail" — and began praying and reading the Bible in his cell every evening, deciding that since the earthly courts kept saying no, again and again, he would hold on to faith that the God he loved would not let him die for something he hadn\'t done. Only after that did he start talking with his neighbors down death row through the bars in the evenings, and eventually became, for many of them, an unspoken source of support — reading aloud, helping write letters home, sitting with them in spirit on what was truly their last night, knowing that for them it really was the last one. He organized a book club on his block, which one day a white neighbor down death row signed up for — the son of a Ku Klux Klan leader, convicted of brutally murdering a Black man — and Walter made himself pray for and talk with exactly that man, not just with those who were easy to love. Over the following twenty-seven years he saw off fifty-four people, executed just a few meters from his own cell.', next: 'vlad_choice2' },
        vlad_bridgeB: { text: 'Walter finally shut himself away in a cold, dull fury, refusing any conversation with his neighbors down death row. The years went by, the count of those executed near his cell kept growing, and the darkness inside him only thickened with every new appeal denied.', next: 'vlad_choice2' },
        vlad_choice2: { text: "After nearly thirty years of imprisonment, a new team of lawyers pushes to have the ballistics evidence re-examined with the most advanced equipment available, and the result conclusively proves that the bullets from the crime scene could not physically have been fired from the revolver that was found. The supreme court overturns the conviction, and the prosecutor's office, acknowledging the forensic error, declines to retry the case. Walter becomes the hundred and fifty-second person in the country exonerated and released from death row since the early 1980s — but for him personally, this above all means thirty lost years no statistic can give back. Walter now has a real choice in how to meet the system that had taken nearly thirty years of his life for nothing.", choices: [
          { label: 'Forgive, without ever giving up the demand for systemic reform', effects: { faith: 15 }, next: 'vlad_endLight' },
          { label: 'Devote the rest of his life to revenge against those who imprisoned him', effects: { faith: -15 }, next: 'vlad_endDark' },
        ] },
        vlad_endLight: { text: "Walter walked free and, to the visible astonishment of the assembled journalists, said outside the courthouse that he forgave the experts whose professional error had cost him thirty years on death row — because the same God who, as he had believed all those years, would not let him die for someone else's crime now, in his own words, left him no choice but forgiveness. Together with the lawyers who had won back his freedom, he wrote a book about what he had lived through, which became an international bestseller, was picked by one of the country's most famous television hosts for her book club, and forced a review of dozens of similar cases across the country. The end of Walter's story.", next: null, choices: [] },
        vlad_endDark: { text: "Walter walked free with a single clear goal: to make absolutely everyone connected to his case pay. Freedom of the body never really brought him freedom from the all-consuming fury that now defined, without exception, literally every day that followed. The end of Walter's story.", next: null, choices: [] },
      },
    },
    kolya: {
      start: 'kolya_intro',
      scenes: {
        kolya_intro: { text: "Nicholas was a young geneticist with a promising scientific future, deeply convinced that religious faith was a simple psychological crutch for those too afraid to honestly face a cold, meaningless universe with no God at all. At the bedside of dying patients in the hospital where he was doing his residency, he was increasingly struck by how calmly so many of them met death precisely because of a faith he himself considered a childish illusion.", next: 'kolya_scene2' },
        kolya_scene2: { text: 'Nicholas had built his entire scientific career on the principle of accepting no claim without rigorous, verifiable evidence, and secretly took pride in his reputation as the most nitpicking skeptic in the clinic. One elderly patient, learning of his atheism, asked him without a trace of judgment: "Doctor, have you ever seriously studied even a single religion — or did you just reject all of them without ever figuring out what they actually teach?" The question caught him off guard precisely because answering honestly meant admitting he never had.', next: 'kolya_choice1' },
        kolya_choice1: { text: "A local pastor, whom Nicholas approached more out of sporting curiosity than any real seriousness, suggested he start not with a theological treatise but with a short book by a former atheist who had become a Christian — simply to apply the same investigative rigor to the question of faith that he applied to his own lab hypotheses. Nicholas took the book off the shelf mostly out of politeness, expecting predictable pious platitudes.", choices: [
          { label: 'Read the book and investigate the question as rigorously as any other hypothesis', effects: { faith: 10 }, next: 'kolya_bridgeA' },
          { label: 'Refuse — the question was settled for him as a scientist long ago', effects: { faith: -10 }, next: 'kolya_bridgeB' },
        ] },
        kolya_bridgeA: { text: "Nicholas read the book in a single night, then reread it twice more, struck by how logically constructed the argument about the moral law inside every human being turned out to be — the very argument that had once led the book's own author from atheism to faith. Already within the first three pages, Nicholas reluctantly admitted that all his own objections to faith sounded like the reasoning of a mischievous schoolboy, not a serious scientist. Over the next several years, Nicholas spent his free time studying the philosophy of science and historical primary sources with the same rigor he applied to his own published genetics work.", next: 'kolya_choice2' },
        kolya_bridgeB: { text: "Nicholas refused to spend time on such reading and kept doing his usual science, though the elderly patient's question — whether he had ever seriously studied even one religion — unexpectedly surfaced in his mind at the most inconvenient moments in the lab, especially at the bedside of yet another dying patient whose calm faith remained, for Nicholas, an unexplained mystery.", next: 'kolya_choice2' },
        kolya_choice2: { text: "On a mountain hike, looking at a frozen waterfall split into three separate streams of ice that merged back into one at its base, Nicholas suddenly felt the resistance he had carried inside for years against all of this fall away at once, leaving behind a strange, inexplicable relief. He has to decide what to do with this sudden moment, one he cannot himself write off to mere exhaustion from the long climb.", choices: [
          { label: 'Accept it as a moment of genuine conversion to faith', effects: { faith: 15 }, next: 'kolya_endLight' },
          { label: 'Write off what he felt as overexertion and keep going as if nothing happened', effects: { faith: -15 }, next: 'kolya_endDark' },
        ] },
        kolya_endLight: { text: 'Nicholas accepted that moment by the waterfall as the start of a genuine conversion, and the next morning, at first light, knelt down in the dew-wet grass and said out loud what he now believed: "God is God, Christ is His Son, and I give Him my life." Years later, that same yesterday\'s skeptic led an international project to sequence the human genome, and in his time away from the lab wrote a book in which, as both scientist and Christian at once, he explained why rigorous science and deep faith don\'t contradict each other but coexist beautifully within one inquiring mind. The book reached an enormous number of readers worldwide, and part of the scientific community never forgave him for that admission. The end of Nicholas\'s story.', next: null, choices: [] },
        kolya_endDark: { text: "Nicholas wrote off what he had felt in the mountains to exhaustion and altitude dizziness and went on doing science as if nothing had happened, carefully avoiding any further conversation about that day even with himself. The elderly patient's question stayed without an honest answer for many years to come. The end of Nicholas's story.", next: null, choices: [] },
      },
    },
    bogdan: {
      start: 'bogdan_intro',
      scenes: {
        bogdan_intro: { text: 'Theodore traveled to a war-torn country as a church envoy — to personally negotiate the release of hostages held by an armed group — and less than a day after arriving became one of the hostages himself, held by the very group he had come to negotiate with. He had already conducted negotiations like this before and won the release of other hostages, so this time he traveled almost without fear, believing his status as a church envoy would protect him.', next: 'bogdan_scene2' },
        bogdan_scene2: { text: 'Theodore spent most of the nearly five years that followed — about four of them — in complete solitary isolation, chained in a windowless room, blindfolded every time the guards appeared. With not a single conversation with another prisoner, no books, no clock, he kept count of the days only by the rare meals, and several times the guards led him out for a staged execution, never once letting him know beforehand whether it was real or not.', next: 'bogdan_choice1' },
        bogdan_choice1: { text: 'In his second year of solitary confinement, Theodore noticed that his habitual, pleading prayer said aloud — "get me out of here" — left only a sharper sense of abandonment after every repetition, not relief. He had to decide how to keep going: search for some other, more durable way of holding onto faith within himself, or give in to hopelessness.', choices: [
          { label: 'Look for a discipline of hope in his faith, not pleading', effects: { faith: 10 }, next: 'bogdan_bridgeA' },
          { label: 'Sink into despair and stop hoping for anything', effects: { faith: -10 }, next: 'bogdan_bridgeB' },
        ] },
        bogdan_bridgeA: { text: 'Theodore stopped begging God for immediate release and instead, every morning in the dark, repeated the same inner vow to himself: the body could be chained, and the mind could be attacked, but the captors would never get his soul. He held onto this faith not as comfort but as a discipline requiring fresh effort every single day — and in place of prayers of request, he began composing stories in his head and retelling them to himself, so as not to let his mind dissolve completely into the darkness and silence. One of these stories, composed and held only in memory, without a single word written down, over years in chains, he later, once free, put down on paper almost unchanged — it became a chapter of his memoir about captivity.', next: 'bogdan_choice2' },
        bogdan_bridgeB: { text: "Theodore gradually sank into deep despair, mechanically counting the days with no real hope that anyone from outside would come to help, or that this captivity would ever truly end at all. The silence of the windowless room, which he used to try to fill with at least some words to himself, now simply stayed empty, day after day.", next: 'bogdan_choice2' },
        bogdan_choice2: { text: "After nearly five years of captivity and long negotiations carried out on his behalf by the church organization, Theodore is finally released — emaciated, but alive, in November, nearly five years to the day since he himself had been taken hostage in place of the very people he'd come to free. Journalists at the foot of the airplane steps back home ask him directly whether he's willing to ever forgive those who held him in chains and darkness for so many years, or whether he intends to demand the harshest possible punishment for them.", choices: [
          { label: 'Say that forgiveness liberates more powerfully than any sentence', effects: { faith: 15 }, next: 'bogdan_endLight' },
          { label: 'Refuse to forgive and demand retribution', effects: { faith: -15 }, next: 'bogdan_endDark' },
        ] },
        bogdan_endLight: { text: "Theodore told the journalists that forgiveness liberates more powerfully than any court sentence — and in 2012 personally returned to that same country and met with his former captors, in order, in his own words, to finally bury the ghosts of the past. Soon after his release he took charge of a charity helping the homeless that back then had just a single center — over the following years, under his leadership, it grew into several dozen communities across the country — saying that the windowless room had taught him to see in every destitute person the same dignity that had once been taken from him. The end of Theodore's story.", next: null, choices: [] },
        bogdan_endDark: { text: "Theodore refused to forgive his captors and for years openly demanded the harshest possible punishment for them. His body was free, but for a long time inside he remained in that same dark, windowless room he had physically left long before, and the stories he had once composed in the dark to hold onto his sanity remained untold to anyone. The end of Theodore's story.", next: null, choices: [] },
      },
    },
  };

  const data = { CHARACTERS, STORIES };
  if (typeof module !== 'undefined' && module.exports) module.exports = data;
  else { window.Content = window.Content || {}; window.Content.en = data; }
})();
